window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["law"] = window.COMMON_BANK["law"] || {name:"法律常识", items:[]};
window.COMMON_BANK["law"].items.push(
{"id": "law-1", "q": "下列哪一情形符合我国公务员法的相关规定？", "options": ["某新录用的公务员经历了六个月的试用期后，便可予以任职", "某公务员因工作失误，受到了免职处分", "某公务员在挂职期间，为了工作便利，把人事关系转入挂职单位", "机关聘任公务员可以进行公开招聘，也可以从符合条件的人员中直接选聘"], "a": 3, "e": "D】本题考查法律常识。A项错误，根据《中华人民共和国公务员法》第三十四条规定：“新录用的公务员试用期为一年。试用期满合格的，予以任职；不合格的，取消录用。”B项错误，根据《国家公务员暂行条例》第四十八条规定：“国家公务员有下列情形之一的，应当予以免职：（一）转换职位任职的；（二）晋升或者降低职务的；（三）离职学习期限超过一年的；（四）因健康原因不能坚持正常工作一年以上的；（五）退休的；（六）因其他原因职务发生变化的。”C项错误，根据《国家公务员暂行条例》第六十条规定：“挂职锻炼，是指国家行政机关有计划地选派在职国家公务员在一定时间内到基层机关或者企业、事业单位担任一定职务。国家公务员在挂职锻炼期间，不改变与原机关的人事行政关系。”D项正确，根据《中华人民共和国公务员法》第一百零一条第一款规定：“机关聘任公务员可以参照公务员考试录用的程序进行公开招聘，也可以从符合条件的人员中直接选聘。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-2", "q": "以下情况中，没有违反公务员法中需要任职回避规定情形的是：", "options": ["小张和他的妻子在同一个厅级机关分别任不同处的处长", "老李是某厅级机关处长，其女儿是该处某科室的科员", "小刘是某厅级机关财务处科员，其妻小梁是该厅老干部处科员", "老周是某厅副厅长，其妻老钱是该厅人事处主任科员"], "a": 2, "e": "C】本题考查法律常识。根据我国《公务员法》第七十四条第一款规定：“公务员之间有夫妻关系、直系血亲关系、三代以内旁系血亲关系以及近姻亲关系的，不得在同一机关双方直接隶属于同一领导人员的职位或者有直接上下级领导关系的职位工作，也不得在其中一方担任领导职务的机关从事组织、人事、纪检、监察、审计和财务工作。”A项错误，小张和他妻子在同一厅级机关，且均为处级干部，二人直接隶属于同一领导，应当任职回避。B项错误，老李是处长，其女儿是该处某科室的科员，二者存在上下级的关系，应当任职回避。C项正确，小刘是财务处科员，小梁是老干部处科员，二者隶属于不同处室的领导，不存在上下关系，无需任职回避。D项错误，老周是副厅长，为领导职务，其妻在该厅人事处任职，从事人事工作，应当任职回避。故正确答案为C。", "tag": "法律常识"},
{"id": "law-3", "q": "以下情形，不违反《中华人民共和国公务员法》规定的任职回避情形的是（）。", "options": ["甲乙为夫妻，在同一机关工作，甲担任领导职务，乙在组织部门任普通科员", "甲乙为表兄妹，在同一机关工作，甲担任领导职务，乙是甲的下级由甲直接领导", "甲乙为兄妹，在同一机关工作，甲在组织部门担任部长，乙在行政部门担任普通科员", "甲乙为父子，在同一机关工作，两人都在人事部门任普通科员"], "a": 2, "e": "C】本题考查行政法。根据《公务员法》第七十四条规定：“公务员之间有夫妻关系、直系血亲关系、三代以内旁系血亲关系以及近姻亲关系的，不得在同一机关双方直接隶属于同一领导人员的职位或者有直接上下级领导关系的职位工作，也不得在其中一方担任领导职务的机关从事组织、人事、纪检、监察、审计和财务工作。公务员不得在其配偶、子女及其配偶经营的企业、营利性组织的行业监管或者主管部门担任领导成员。因地域或者工作性质特殊，需要变通执行任职回避的，由省级以上公务员主管部门规定。”A选项错误，甲乙是夫妻关系，而且在同一机关，甲是领导，乙是组织部门科员，根据规定，有夫妻关系的，不得在其中一方担任领导职务的机关从事组织、人事、纪检、监察、审计和财务工作。该项违反了任职回避的规定。B选项错误，甲乙为表兄妹，属于三代以内旁系血亲，甲担任领导职务，乙是甲的下级由甲直接领导，二者具有直接上下级的领导关系。该项违反了任职回避的规定。C选项正确，甲乙为兄妹，属于三代以内旁系血亲，甲在组织部门担任部长，乙在行政部门担任普通科员，不违反《中华人民共和国公务员法》第七十四条关于任职回避的规定。D选项错误，甲乙为父子，属于直系血亲关系，在同一机关的人事部门任普通科员，直接隶属于同一领导，该项违反了任职回避的规定。故正确答案为C。", "tag": "法律常识"},
{"id": "law-4", "q": "公务员辞去公职，应当向任免机关提出书面申请。任免机关应当自接到申请之日起（）日内予以审批，其中对领导成员辞去公职的申请，应当自接到申请之日起（）日内予以审批。", "options": ["十，二十", "十，三十", "三十，六十", "三十，九十"], "a": 3, "e": "D】本题主要考查公务员法。《中华人民共和国公务员法》第八十五条规定：“公务员辞去公职，应当向任免机关提出书面申请。任免机关应当自接到申请之日起三十日内予以审批，其中对领导成员辞去公职的申请，应当自接到申请之日起九十日内予以审批。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-5", "q": "关于机关对聘任制公务员的管理，以下说法正确的是：", "options": ["与委任制公务员的管理规定相同", "公务员法的管理规定均适用于聘任制公务员", "聘任合同的内容中可以有不执行公务员法管理规定的部分", "聘任合同一经签订不得更改或者解除"], "a": 2, "e": "C】本题考查行政法。A项错误，根据《公务员法》第四十条规定：“公务员领导职务实行选任制、委任制和聘任制。公务员职级实行委任制和聘任制。领导成员职务按照国家规定实行任期制。”该法第四十二条规定：“委任制公务员试用期满考核合格，职务、职级发生变化，以及其他情形需要任免职务、职级的，应当按照管理权限和规定的程序任免。”该法第一百条规定：“机关根据工作需要，经省级以上公务员主管部门批准，可以对专业性较强的职位和辅助性职位实行聘任制。前款所列职位涉及国家秘密的，不实行聘任制。”所以，聘任制公务员管理和委任制公务员管理规定不完全相同。B项错误，C项正确。根据《公务员法》第一百零四条规定：“机关依据本法和聘任合同对所聘公务员进行管理。”可知，聘任制公务员的管理适用的是公务员管理的一般原则和制度精神，公务员法的管理规定并不均适用于聘任制公务员，聘任合同的内容中可以有不执行公务员法规定的部分，例如聘任制公务员在聘任期间，没有职务晋升的问题，但可以按照聘任合同的约定，定期增长工资和其他福利待遇。D项错误，根据《公务员法》第一百零二条规定：“机关聘任公务员，应当按照平等自愿、协商一致的原则，签订书面的聘任合同，确定机关与所聘公务员双方的权利、义务。聘任合同经双方协商一致可以变更或者解除。聘任合同的签订、变更或者解除，应当报同级公务员主管部门备案。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-6", "q": "公务员的行为规范是指公务员在任职期间必须遵守和履行的行为准则和：", "options": ["工作方法", "工作作风", "工作程序", "工作纪律"], "a": 3, "e": "D】本题考查法律常识。公务员行为规范，从广义上讲，是指公务员的言谈举止在任何时候、任何场合都要进行一定的约束和限制。从狭义上讲，是指公务员在公务活动中必须自觉遵守和遵循的各项基本准则和纪律，包括政治思想、工作作风、办事规则、行政程序等等。出处：公共管理系列教材《国家公务员制度教程》（舒放王克良主编），中国人民大学出版社2001年第1版。故正确答案为D。", "tag": "法律常识"},
{"id": "law-7", "q": "公务员法对公务员的范围重新做了界定，根据规定，公务员必须具备三个条件，其中体现公务员最本质特征的是：", "options": ["依法履行公职", "纳入国家行政编制", "由国家财政负担工资福利", "三项均属于"], "a": 0, "e": "A】本题考查法律常识。《公务员法》第二条第二款：“本法所称公务员，是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的工作人员。”根据《公务员法释义》对本条的释义，是否属于公务员，必须符合三个条件：一是依法履行公职。即依法从事公务活动的人员，他不是为自己工作，也不是为某个私人的企业或者组织工作或者服务，故A选项正确。二是纳入国家行政编制。有一些非行政编制的工作人员，例如法院法官等，也属于公务员，故B选项错误。三是由国家财政负担工资福利。公务员属于国家财政供养的人员，但并不是财政供养的人员都是公务员。财政供养人员的很大一部分，如公立学校的老师、科研院所的科研人员等，虽然由国家负担其工资福利，但不属于公务员，故D选项错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-8", "q": "我国对公务员管理实行的制度是：", "options": ["党政干部单一的管理", "集中统一管理", "分类管理", "职位管理"], "a": 2, "e": "C】本题考查法律常识。根据《公务员法》第十六条规定：“国家实行公务员职位分类制度。公务员职位类别按照公务员职位的性质、特点和管理需要，划分为综合管理类、专业技术类和行政执法类等类别。根据本法，对于具有职位特殊性，需要单独管理的，可以增设其他职位类别。各职位类别的适用范围由国家另行规定。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-9", "q": "公务员的任用，坚持的原则是：", "options": ["勤能并重", "管理与监督并重", "唯才是用", "任人唯贤，德才兼备"], "a": 3, "e": "D】根据《公务员法》第七条规定：“公务员的任用，坚持德才兼备、以德为先，坚持五湖四海、任人唯贤，坚持事业为上、公道正派，突出政治标准，注重工作实绩。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-10", "q": "根据《中华人民共和国公务员法》，下列说法中正确的是：", "options": ["新录用的公务员，试用期为六个月", "公务员解除降级、撤职处分的，不视为恢复原级别、原职务", "公务员在挂职锻炼期间，人事关系转到挂职的单位", "曾被开除公职的人员，可以被再次录用为公务员"], "a": 1, "e": "【B】本题考查行政法。A项错误，根据《公务员法》第三十四条规定：“新录用的公务员试用期为一年。试用期满合格的，予以任职；不合格的，取消录用。”B项正确，根据《公务员法》第六十五条第二款规定：“解除处分后，晋升工资档次、级别和职务、职级不再受原处分的影响。但是，解除降级、撤职处分的，不视为恢复原级别、原职务、原职级。”C项错误，根据《公务员法》第七十二条的规定：“根据工作需要，机关可以采取挂职方式选派公务员承担重大工程、重大项目、重点任务或者其他专项工作。公务员在挂职期间，不改变与原机关的人事关系。”D项错误，根据《公务员法》第二十六条的规定：“下列人员不得录用为公务员：（一）因犯罪受过刑事处罚的；（二）被开除中国共产党党籍的；（三）被开除公职的；（四）被依法列为失信联合惩戒对象的；（五）有法律规定不得录用为公务员的其他情形的。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-11", "q": "根据我国《公务员法》，公务员应当履行的义务包括()。①模范遵守宪法和法律②获得履行职责应当具有的工作条件③清正廉洁，公道正派④参加培训⑤遵守纪律，恪守职业道德，模范遵守社会公德", "options": ["①④⑤", "①③⑤", "②③④⑤", "①②③④⑤"], "a": 1, "e": "【B】本题考查了公务员法的知识点。根据《公务员法》第十四条的规定：“公务员应当履行下列义务：（一）忠于宪法，模范遵守、自觉维护宪法和法律，自觉接受中国共产党领导；（二）忠于国家，维护国家的安全、荣誉和利益；（三）忠于人民，全心全意为人民服务，接受人民监督；（四）忠于职守，勤勉尽责，服从和执行上级依法作出的决定和命令，按照规定的权限和程序履行职责，努力提高工作质量和效率；（五）保守国家秘密和工作秘密；（六）带头践行社会主义核心价值观，坚守法治，遵守纪律，恪守职业道德，模范遵守社会公德、家庭美德；（七）清正廉洁，公道正派；（八）法律规定的其他义务。”根据《公务员法》第十五条规定：“公务员享有下列权利：（一）获得履行职责应当具有的工作条件；（二）非因法定事由、非经法定程序，不被免职、降职、辞退或者处分；（三）获得工资报酬，享受福利、保险待遇；（四）参加培训；（五）对机关工作和领导人员提出批评和建议；（六）提出申诉和控告；（七）申请辞职；（八）法律规定的其他权利。”①③⑤属于公务员应当履行的义务，②④属于公务员应当享有的权利。故正确答案为B。", "tag": "法律常识"},
{"id": "law-13", "q": "根据《中华人民共和国公务员法》，公务员是指、纳入国家行政编制、由国家财政负担工资福利的工作人员。", "options": ["在国家行政机关工作", "在党政机关工作", "行使公共权力", "依法履行公职"], "a": 3, "e": "【D】根据《公务员法》第二条：“本法所称公务员，是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的工作人员。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-14", "q": "根据《公务员法》的相关规定，下列哪个不属于公务员在机关外兼职应符合的条件：", "options": ["因工作需要", "非领导职务公务员", "经有关机关批准", "不领取兼职报酬"], "a": 1, "e": "【B】《中华人民共和国公务员法》第四十四条规定：“公务员因工作需要在机关外兼职，应当经有关机关批准，并不得领取兼职报酬。”对应A、C、D项。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-15", "q": "根据《公务员法》的规定，下列选项正确的是：", "options": ["公务员李某因接受纪律审查，自觉无颜在单位呆下去，在审查过程中，向单位请辞，单位很理解地批准辞职", "公务员赵某对降职处分要求复核，复核期间停止了降职处分的执行", "某工作由于专业性较强，单位聘任常某担任公务员，并签订了10 年的聘任合同", "公务员段某因公外出，无正当理由逾期不归连续超过20 天而被辞退"], "a": 3, "e": "【D】本题考查行政法。A选项错误，根据《公务员法》第八十六条第四款规定：“公务员有下列情形之一的，不得辞去公职：（四）正在接受审计、纪律审查、监察调查，或者涉嫌犯罪，司法程序尚未终结的；”可见，李某在纪律审查过程中不得辞去公职。B选项错误，根据《公务员法》第九十六条第二款规定：“复核、申诉期间不停止人事处理的执行。”C选项错误，根据《公务员法》第一百零三条第二款规定：“聘任合同期限为一年至五年。”因而单位与常某签订10年的聘任合同不符合法律的规定。D选项正确，根据《公务员法》第八十八条规定：“公务员有下列情形之一的，予以辞退：（一）在年度考核中，连续两年被确定为不称职的；（二）不胜任现职工作，又不接受其他安排的；（三）因所在机关调整、撤销、合并或者缩减编制员额需要调整工作，本人拒绝合理安排的；（四）不履行公务员义务，不遵守法律和公务员纪律，经教育仍无转变，不适合继续在机关工作，又不宜给予开除处分的；（五）旷工或者因公外出、请假期满无正当理由逾期不归连续超过十五天，或者一年内累计超过三十天的。”段某因公外出，无正当理由逾期不归连续超过20天而被辞退符合法律规定的情形。故正确答案为D。", "tag": "法律常识"},
{"id": "law-16", "q": "职业精神与人们职业活动紧密联系，是具有自身职业特征的精神。我国公务员职业精神的本质是：", "options": ["恪尽职守", "诚实守信", "公而忘私", "服务人民"], "a": 3, "e": "【D】公务员是依法履行公职的工作人员，其义务是全心全意为人民服务，接受人民监督，服务人民是公务员的职业特征。故正确答案为D。", "tag": "法律常识"},
{"id": "law-17", "q": "下列关于我国公务员制度的表述，不正确的是：", "options": ["根据《公务员法》，我国公务员职位类别划分为综合管理类、专业技术类和行政执法类等类别", "已被开除的公职人员，不得录用为公务员", "工作年限满三十年的公务员，可以申请提前退休", "对公务员考核的内容包括德、能、勤、绩、廉五个方面，重点考核思想道德与工作能力"], "a": 3, "e": "【D】本题考查法律常识。A项正确，《公务员法》第十六条规定：“国家实行公务员职位分类制度。公务员职位类别按照公务员职位的性质、特点和管理需要，划分为综合管理类、专业技术类和行政执法类等类别。根据本法，对于具有职位特殊性，需要单独管理的，可以增设其他职位类别。各职位类别的适用范围由国家另行规定。”B项正确，根据《公务员法》第二十六条：“下列人员不得录用为公务员：（一）因犯罪受过刑事处罚的；（二）被开除中国共产党党籍的；（三）被开除公职的；（四）被依法列为失信联合惩戒对象的；（五）有法律规定不得录用为公务员的其他情形的。”曾被开除公职的人不得录用为公务员。C项正确，根据《公务员法》第九十三条：“公务员符合下列条件之一的，本人自愿提出申请，经任免机关批准，可以提前退休：（一）工作年限满三十年的；（二）距国家规定的退休年龄不足五年，且工作年限满二十年的；（三）符合国家规定的可以提前退休的其他情形的。”D项错误，根据《公务员法》第三十五条：“公务员的考核应当按照管理权限，全面考核公务员的德、能、勤、绩、廉，重点考核政治素质和工作实绩。考核指标根据不同职位类别、不同层级机关分别设置。”本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-18", "q": "下列选项中，属于公务员应当具备的条件是：", "options": ["具有身份证、军民证或护照", "年满20 周岁，且无犯罪记录", "男性身高170cm 以上，女性身高165cm 以上", "具有良好的品行"], "a": 3, "e": "【D】本题考查行政法。根据《公务员法》第十三条的规定：“公务员应当具备下列条件：（一）具有中华人民共和国国籍；（二）年满十八周岁；（三）拥护中华人民共和国宪法，拥护中国共产党领导和社会主义制度；（四）具有良好的政治素质和道德品行；（五）具有正常履行职责的身体条件和心理素质；（六）具有符合职位要求的文化程度和工作能力；（七）法律规定的其他条件。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-19", "q": "根据我国公务员制度的相关规定，录用担任（）及其他相当职级层次的公务员，采取公开考试、严格考察、平等竞争、择优录取的办法。", "options": ["科员以上", "主任科员以上", "科员以下", "一级主任科员以下"], "a": 3, "e": "【D】根据《公务员法》第二十三条：“录用担任一级主任科员以下及其他相当职级层次的公务员，采取公开考试、严格考察、平等竞争、择优录取的办法。民族自治地方依照前款规定录用公务员时，依照法律和有关规定对少数民族报考者予以适当照顾。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-20", "q": "下列哪项不属于公务员所享受的权利：", "options": ["公务员非经所在地人大许可不受公安机关逮捕", "非因法定事由、法定程序不被免职、降职、辞退或处分", "小李因个人原因向所在单位申请辞职", "小王不满上级给予的处分，提出申诉和控告"], "a": 0, "e": "【A】根据《公务员法》第十五条的规定：“公务员享有下列权利：（一）获得履行职责应当具有的工作条件；（二）非因法定事由、非经法定程序，不被免职、降职、辞退或者处分；（三）获得工资报酬，享受福利、保险待遇；（四）参加培训；（五）对机关工作和领导人员提出批评和建议；（六）提出申诉和控告；（七）申请辞职；（八）法律规定的其他权利。”故正确答案为A。", "tag": "法律常识"},
{"id": "law-21", "q": "根据《公务员法》的回避原则，下列哪种情况不需要回避：", "options": ["一个市内，丈夫是公安局局长，妻子是教育局局长", "父亲是某市公安局局长，儿子是下级分局局长", "丈夫是某市公安局局长，妻子的妹妹的女儿是该局财政科科员", "丈夫是某市公安局局长，妻子是该局财政科科员"], "a": 2, "e": "【C】《公务员法》第七十四条规定：“公务员之间有夫妻关系、直系血亲关系、三代以内旁系血亲关系以及近姻亲关系的，不得在同一机关担任双方直接隶属于同一领导人员的职务或者有直接上下级领导关系的职务，也不得在其中一方担任领导职务的机关从事组织、人事、纪检、监察、审计和财务工作。”《公务员回避规定（试行）》中，对该条规定做了详细阐述和说明：（一）夫妻关系；（二）直系血亲关系，包括祖父母、外祖父母、父母、子女、孙子女、外孙子女；（三）三代以内旁系血亲关系，包括伯叔姑舅姨、兄弟姐妹、堂兄弟姐妹、表兄弟姐妹、侄子女、甥子女；（四）近姻亲关系，包括配偶的父母、配偶的兄弟姐妹及其配偶、子女的配偶及子女配偶的父母、三代以内旁系血亲的配偶。本规定所指直接隶属，是指具有直接上下级领导关系；同一领导人员，包括同一级领导班子成员；直接上下级领导关系，包括上一级正副职与下一级正副职之间的领导关系。A项正确，同一市内，丈夫是公安局局长，妻子是教育局局长，属于同一级领导班子成员，且是夫妻关系，应该回避；B项正确，父亲和儿子属于直系血亲关系，公安局局长和下级分局局长属于直接上下级领导关系，应该回避；C项错误，该局长妻子妹妹的女儿，不属于近姻亲关系，也不属于三代以内旁系血亲关系，故不需要回避；D项正确，财政科科员从事的是财务工作，也属于应当回避的范围。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-22", "q": "根据《公务员法》的有关规定，公务员的处分形式不包括：", "options": ["记大过", "降级", "降职", "撤职"], "a": 2, "e": "【C】根据《公务员法》第六十二条：“处分分为：警告、记过、记大过、降级、撤职、开除。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-23", "q": "根据2018 年12 月29 日新修订的《公务员法》的相关规定，下列说法中正确的是（）。", "options": ["甲在一年内累计旷工超过15 天，对甲应当予以辞退", "乙因涉嫌受贿正接受监察机关调查，乙可以在调查结束前辞去公职", "丙在受警告处分期间不得晋升职务，但不影响晋升工资档次", "丁按照上级的命令执行公务，执行的后果由上级负责，丁不承担责任"], "a": 2, "e": "【C】本题考查法律常识。A项错误，根据《公务员法》第八十八条规定：“公务员有下列情形之一的，予以辞退：（五）旷工或者因公外出、请假期满无正当理由逾期不归连续超过十五天，或者一年内累计超过三十天的。”甲未连续旷工超过十五天或一年内累计超过三十天，不得辞退。B项错误，根据《公务员法》第八十六条规定：“公务员有下列情形之一的，不得辞去公职：（四）正在接受审计、纪律审查、监察调查，或者涉嫌犯罪，司法程序尚未终结的。”乙正在接受监察调查，不得辞去公职。C项正确，根据《公务员法》第六十四条第一款规定：“公务员在受处分期间不得晋升职务、职级和级别，其中受记过、记大过、降级、撤职处分的，不得晋升工资档次。”丙受到的是警告处分，因此在此期间不得晋升职务，但不影响晋升工资档次。D项错误，根据《公务员法》第六十条规定：“公务员执行公务时，认为上级的决定或者命令有错误的，可以向上级提出改正或者撤销该决定或者命令的意见；上级不改变该决定或者命令，或者要求立即执行的，公务员应当执行该决定或者命令，执行的后果由上级负责，公务员不承担责任；但是，公务员执行明显违法的决定或者命令的，应当依法承担相应的责任。”如果丁执行明显违法的决定或者命令的，应当依法承担相应的责任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-24", "q": "2018 年12 月29 日第十三届全国人民代表大会常务委员会第七次会议修订了《公务员法》并将于2019 年6 月1 日起实施，本次修订之后，下列可以录用为公务员的是（）。", "options": ["因犯罪受过刑事处罚的张三", "被开除中国共产党党籍的李四", "被依法列为失信联合惩戒对象的王五", "被某民企辞退的马六"], "a": 3, "e": "【D】本题考查法律常识。根据最新修订的《公务员法》第二十六条的规定：“下列人员不得录用为公务员：（一）因犯罪受过刑事处罚的；（二）被开除中国共产党党籍的；（三）被开除公职的；（四）被依法列为失信联合惩戒对象的；（五）有法律规定不得录用为公务员的其他情形的。”A项错误，张三符合第（一）项的情形，不得被录用为公务员。B项错误，李四符合第（二）项的情形，不得被录用为公务员。C项错误，王五符合第（四）项的情形，不得被录用为公务员。D项正确，马六没有法律规定的限制情形，可以被录用为公务员。故正确答案为D。", "tag": "法律常识"},
{"id": "law-25", "q": "根据我国公务员法的相关规定，下列情形中正确的是：", "options": ["在中国定居的30 岁外籍老师山姆可以报考中国国家公务员", "某市政府公务员张三有对其领导提出批评和建议的权利", "李四受过刑事处罚，但只要服刑完毕，就可以考试后正常录用为公务员", "王五收到了定期考核结果的书面文件，结果显示其为“基本合格”"], "a": 1, "e": "【B】本题考查行政法。A项错误，根据《公务员法》第十三条第一款规定：“公务员应当具备下列条件：（一）具有中华人民共和国国籍；……”拥有中华人民共和国国籍是报考我国公务员的条件之一，A选项中的外籍教师不具备中国国籍，无法报考中国国家公务员。B项正确，根据《公务员法》第十五条第五款规定：“公务员享有下列权利：……(五)对机关工作和领导人员提出批评和建议……”B选项中张三对其领导提出批评建议符合公务员法的相关规定。C项错误：根据《公务员法》第二十六条规定：“下列人员不得录用为公务员：（一）因犯罪受过刑事处罚的；（二）被开除中国共产党党籍的；（三）被开除公职的；（四）被依法列为失信联合惩戒对象的；（五）有法律规定不得录用为公务员的其他情形的。”C选项中李四曾受刑事处罚，因此不能录用为公务员。D项错误，根据《公务员法》第三十八条规定：“定期考核的结果分为优秀、称职、基本称职和不称职四个等次。定期考核的结果应当以书面形式通知公务员本人。”D选项中王五收到了定期考核结果的书面文件符合该规定，但结果为“基本合格”错误。故正确答案为B。", "tag": "法律常识"},
{"id": "law-26", "q": "对侵害英雄烈士的姓名、肖像、名誉、荣誉的行为，有权向人民法院提起诉讼的主体是：①英雄烈士近亲属②检察机关③当地人民政府④负责英雄烈士保护工作的部门", "options": ["②④", "①④", "①③", "①②"], "a": 3, "e": "【D】本题考查法律常识。《英雄烈士保护法》第二十五条第一款、第二款规定：“对侵害英雄烈士的姓名、肖像、名誉、荣誉的行为，英雄烈士的近亲属可以依法向人民法院提起诉讼。英雄烈士没有近亲属或者近亲属不提起诉讼的，检察机关依法对侵害英雄烈士的姓名、肖像、名誉、荣誉，损害社会公共利益的行为向人民法院提起诉讼。”因此，有权向人民法院提出诉讼的主体是英雄烈士的近亲属和检察机关。故正确答案为D。", "tag": "法律常识"},
{"id": "law-27", "q": "某有限责任公司有股东甲、乙、丙、丁、戊5 人，注册资本为200 万元，其中甲出资10 万元、乙20 万元、丙10 万元、丁10 万元、戊150 万元。公司运行3 年后，效益良好，甲、乙、丙、丁在戊出差期间自行商量后通过了进一步增加注册资本50 万元的决议。下列说法正确的是：", "options": ["甲、乙、丙、丁通过的决议有效", "该增资决议应由全体股东一致同意", "戊可以自行决定是否增加注册资本，无需经过甲乙丙丁的同意", "戊可以向人民法院起诉确认该增资决议无效"], "a": 3, "e": "【D】本题考查法律常识。根据《中华人民共和国公司法》第三十七条规定：“股东会行使下列职权：……(七)对公司增加或者减少注册资本作出决议……对前款所列事项股东以书面形式一致表示同意的，可以不召开股东会会议，直接作出决定，并由全体股东在决定文件上签名、盖章。”根据该法第四十三条第二款规定：“股东会会议作出修改公司章程、增加或者减少注册资本的决议，以及公司合并、分立、解散或者变更公司形式的决议，必须经代表三分之二以上表决权的股东通过。”根据该法第四十二条规定：“股东会会议由股东按照出资比例行使表决权；但是，公司章程另有规定的除外。”A项错误，根据《中华人民共和国公司法》第三十七条的规定，公司通过增资决议且不需要召开股东会会议的情形为股东以书面形式一致表示同意，则可直接作出决定，并由全体股东在决定文件上签名、盖章。本题中，戊出差不知情，显然不属于《中华人民共和国公司法》第三十七条规定的可以不召开股东会会议的情形。且甲、乙、丙、丁四人不能代表三分之二以上表决权，故其自行商量通过的增资决议无效。B项错误，甲、乙、丙、丁四人自行商量后通过增资决议，不属于《中华人民共和国公司法》第三十七条的可以不召开股东会会议的情形，需要召开股东会会议，并且经代表三分之二以上表决权的股东通过即可，不需要全体股东一致同意。C项错误，虽然戊代表该公司三分之二以上的表决权，但通过增资决议需要按照法律和章程规定召开股东会由股东会决议，或者以书面形式一致表示同意，而不能由戊自行决定。D项正确，由于甲乙丙丁四人自行商量通过的增资决议无效(A项已解析)，故根据《最高人民法院关于适用<中华人民共和国公司法>若干问题的规定（四）》第一条：“公司股东、董事、监事等请求确认股东会或者股东大会、董事会决议无效或者不成立的，人民法院应当依法予以受理。”所以戊可以向人民法院起诉确认该增资决议无效。故正确答案为D。", "tag": "法律常识"},
{"id": "law-28", "q": "关于人民陪审员，下列说法符合法律规定的是：", "options": ["陪审员小李所在的单位因其在工作日参加审判活动而扣发他的奖金", "公证员小张被某县人民法院选聘为人民陪审员", "陪审员小赵在七人合议庭审理的案件中对法律适用参加表决", "陪审员小刘参加审判活动，人民法院按实际工作日对其给予补助"], "a": 3, "e": "【D】本题考查法律常识。A项错误，《人民陪审员法》第二十九条第一款规定：“人民陪审员参加审判活动期间，所在单位不得克扣或者变相克扣其工资、奖金及其他福利待遇。”因此，小李所在单位扣发奖金的做法不符合法律规定。B项错误，《人民陪审员法》第六条规定：“下列人员不能担任人民陪审员：（一）人民代表大会常务委员会的组成人员，监察委员会、人民法院、人民检察院、公安机关、国家安全机关、司法行政机关的工作人员；（二）律师、公证员、仲裁员、基层法律服务工作者；（三）其他因职务原因不适宜担任人民陪审员的人员。”因此，公证员小张不能担任人民陪审员。C项错误，《人民陪审员法》第二十二条规定：“人民陪审员参加七人合议庭审判案件，对事实认定，独立发表意见，并与法官共同表决；对法律适用，可以发表意见，但不参加表决。”因此，陪审员小赵参加七人合议庭审判案件，不能对法律适用进行表决。D项正确，《人民陪审员法》第三十条第一款规定：“人民陪审员参加审判活动期间，由人民法院依照有关规定按实际工作日给予补助。”因此，法院的做法符合法律规定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-29", "q": "甲国与乙国因领土纠纷发生争端，下列说法不符合国际法相关规定的是：", "options": ["甲乙两国可以派出外交使节进行谈判，这是解决争端最直接的方法", "甲乙两国可以约定将争端交付仲裁机构处理，但仲裁裁决不具有法律制裁性质", "丙国可以调停者的身份参加两国的谈判，但其提出的解决方案对甲乙两国没有约束力", "甲乙两国可用请求书方式将争端提交国际法院，国际法院作出的判决交由联合国强制执行"], "a": 3, "e": "【D】本题考查法律常识之国际法。解析依据《2018年国家统一法律职业资格考试辅导用书•第四卷》（国家统一法律职业资格考试辅导用书编辑委员会编，法律出版社出版）A项正确，根据《2018年国家统一法律职业资格考试辅导用书•第四卷》344页：“谈判是争端当事国就其争端直接进行交涉，交换意见以求解决的方式。谈判是解决国际争端的最基本方式”。“谈判”即当事国直接进行交涉，是最直接的方式。因此表述正确。B项正确，根据《2018年国家统一法律职业资格考试辅导用书•第四卷》345-346页：“仲裁或称公断，是指根据争端当事国之间的协议，将争端交与他们选定的仲裁人作出对争端当事方具有拘束力的裁决，从而解决争端的方法”。此外，仲裁裁决不具有法律制裁性质，但当事国出于道义上的责任，必须严格执行。因此表述正确。C项正确，根据《2018年国家统一法律职业资格考试辅导用书•第四卷》345页：“调停是指第三方以调停人的身份，就争端的解决提出方案，并直接参加或主持谈判，以协助争端解决。调停国提出的方案本身没有拘束力，调停国对于进行调停或调停成败也不承担任何法律义务或后果”。因此表述正确。D项错误，根据《2018年国家统一法律职业资格考试辅导用书•第四卷》348页：“国际法院的判决是终局性的。判决一经作出，即对本案及本案当事国产生拘束力，当事国必须履行。如有一方拒不履行判决，他方得向安理会提出申诉，安理会可以作出有关建议或决定采取措施执行判决”。因此该项“国际法院作出的判决交由联合国强制执行”表述错误。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-30", "q": "下列有关律师的说法错误的是：", "options": ["律师不得在同一案件中为双方当事人担任代理人", "律师根据案情的需要，可以申请人民法院通知证人出庭作证", "律师可以在多个律师事务所执业，律师执业不受地域限制", "律师担任辩护人的，有权查阅、摘抄、复制本案的案卷材料"], "a": 2, "e": "【C】本题考查法律常识，主要涉及《律师法》的相关知识点。A项正确，我国《律师法》第三十九条规定：“律师不得在同一案件中为双方当事人担任代理人，不得代理与本人或者其近亲属有利益冲突的法律事务。”故A选项说法正确。B项正确，我国《律师法》第三十五条第一款规定：“受委托的律师根据案情的需要，可以申请人民检察院、人民法院收集、调取证据或者申请人民法院通知证人出庭作证。”故B选项说法正确。C项错误，我国《律师法》第十条规定：“律师只能在一个律师事务所执业。律师变更执业机构的，应当申请换发律师执业证书。律师执业不受地域限制。”因此，律师不得同时在多个律师事务所执业，故C选项错误。D项正确，我国《律师法》第三十四条规定：“律师担任辩护人的，自人民检察院对案件审查起诉之日起，有权查阅、摘抄、复制本案的案卷材料。”故D选项正确。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-31", "q": "下列关于“三农”问题的说法错误的是：", "options": ["民政部门是农民专业合作社登记机关", "征地补偿费的使用、分配方案，经村民会议讨论决定方可办理", "深入推进农业供给侧结构性改革是当前和今后一个时期农业农村工作的主线", "村民委员会作出的决定侵害村民合法权益的，受侵害的村民可以申请人民法院予以撤销"], "a": 0, "e": "【A】本题考查法律及时政常识。A项：错误，《农民专业合作社登记管理条例》第四条规定：“工商行政管理部门是农民专业合作社登记机关。国务院工商行政管理部门负责全国的农民专业合作社登记管理工作。”据此可知，民政部门不是农民专业合作社登记机关，故A项表述错误。B项：正确，《中华人民共和国村民委员会组织法》第二十四条第七款规定：“征地补偿费的使用、分配方案，经村民会议讨论决定方可办理。”故B项表述正确。C项：正确，《中共中央国务院关于深入推进农业供给侧结构性改革加快培育农业农村发展新动能的若干意见》中明确提出“推进农业供给侧结构性改革是一个长期过程”；“坚持新发展理念，协调推进农业现代化与新型城镇化，以推进农业供给侧结构性改革为主线”。据此可知，深入推进农业供给侧结构改革是当前和今后一个时期农业农村工作的主线，故C项表述正确。D项：正确，《中华人民共和国村民委员会组织法》第三十六条规定：“村民委员会或者村民委员会成员作出的决定侵害村民合法权益的，受侵害的村民可以申请人民法院予以撤销，责任人依法承担法律责任。”据此可知，D项表述正确。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-32", "q": "下列说法不符合我国《慈善法》规定的是：", "options": ["慈善组织的设立应当向工商行政管理部门申请登记", "慈善组织为实现财产保值、增值，通常可以进行投资", "慈善组织可以委托有服务专长的其他组织提供慈善服务", "慈善组织可以采取基金会、社会团体、社会服务机构等组织形式"], "a": 0, "e": "【A】A项错误：我国《慈善法》第二章第十条第一款规定：“设立慈善组织，应当向县级以上人民政府民政部门申请登记，民政部门应当自受理申请之日起三十日内作出决定。符合本法规定条件的，准予登记并向社会公告；不符合本法规定条件的，不予登记并书面说明理由。”因此慈善组织的设立不用向工商行政管理部门申请登记，当选；B、C、D项说法均符合我国《慈善法》的规定，排除。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-33", "q": "如果我国现行个人所得税适用于古代，下列哪一情形不需要缴纳个人所得税？", "options": ["苏轼发表《赤壁赋》所得的稿酬", "包拯任开封府府尹期间所得俸禄", "康熙年间旱灾灾民获得的救济款", "罗尚德将银两存入钱庄所得利息"], "a": 2, "e": "【C】C项符合题意：根据《中华人民共和国个人所得税法》第四条第四款的规定下列各项个人所得，免纳个人所得税：四、福利费、抚恤金、救济金。因此本项中灾民因旱灾所得的救济款不需要缴纳个人所得税，当选；A、B、D项不符合题意：根据《中华人民共和国个人所得税法》第二条的规定，“下列各项个人所得，应纳个人所得税：一、工资、薪金所得；二、个体工商户的生产、经营所得；三、对企事业单位的承包经营、承租经营所得；四、劳务报酬所得；五、稿酬所得；六、特许权使用费所得；七、利息、股息、红利所得；八、财产租赁所得；九、财产转让所得；十、偶然所得；十一、经国务院财政部门确定征税的其他所得。”A项中的稿酬属于第五项的内容，B项中的俸禄属于第一项的内容、D项中的利息属于第七项的内容，都需要缴纳个人所得税，均排除。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-34", "q": "2020 年6 月30 日颁布的《中华人民共和国香港特别行政区维护国家安全法》是保持香港特别行政区繁荣和稳定的重要法律。以下属于该法规定处罚的罪行有（）。①分裂国家罪②颠覆国家政权罪③恐怖活动罪④勾结外国或者境外势力危害国家安全罪", "options": ["①④", "①②③", "②③④", "①②③④"], "a": 3, "e": "【D】本题考查法律常识。①正确，《香港特别行政区维护国家安全法》第二十条第一款规定：“任何人组织、策划、实施或者参与实施以下旨在分裂国家、破坏国家统一行为之一的，不论是否使用武力或者以武力相威胁，即属犯罪：（一）将香港特别行政区或者中华人民共和国其他任何部分从中华人民共和国分离出去；（二）非法改变香港特别行政区或者中华人民共和国其他任何部分的法律地位；（三）将香港特别行政区或者中华人民共和国其他任何部分转归外国统治。”这是该法关于分裂国家罪的规定。②正确，《香港特别行政区维护国家安全法》第二十二条第一款规定：“任何人组织、策划、实施或者参与实施以下以武力、威胁使用武力或者其他非法手段旨在颠覆国家政权行为之一的，即属犯罪：（一）推翻、破坏中华人民共和国宪法所确立的中华人民共和国根本制度；（二）推翻中华人民共和国中央政权机关或者香港特别行政区政权机关；（三）严重干扰、阻挠、破坏中华人民共和国中央政权机关或者香港特别行政区政权机关依法履行职能；（四）攻击、破坏香港特别行政区政权机关履职场所及其设施，致使其无法正常履行职能。”这是该法关于颠覆国家政权罪的规定。③正确，《香港特别行政区维护国家安全法》第二十四条第一款规定：“为胁迫中央人民政府、香港特别行政区政府或者国际组织或者威吓公众以图实现政治主张，组织、策划、实施、参与实施或者威胁实施以下造成或者意图造成严重社会危害的恐怖活动之一的，即属犯罪：（一）针对人的严重暴力；（二）爆炸、纵火或者投放毒害性、放射性、传染病病原体等物质；（三）破坏交通工具、交通设施、电力设备、燃气设备或者其他易燃易爆设备；（四）严重干扰、破坏水、电、燃气、交通、通讯、网络等公共服务和管理的电子控制系统；（五）以其他危险方法严重危害公众健康或者安全。”这是该法关于恐怖活动罪的规定。④正确，《香港特别行政区维护国家安全法》第二十九条第一款规定：“为外国或者境外机构、组织、人员窃取、刺探、收买、非法提供涉及国家安全的国家秘密或者情报的；请求外国或者境外机构、组织、人员实施，与外国或者境外机构、组织、人员串谋实施，或者直接或者间接接受外国或者境外机构、组织、人员的指使、控制、资助或者其他形式的支援实施以下行为之一的，均属犯罪：（一）对中华人民共和国发动战争，或者以武力或者武力相威胁，对中华人民共和国主权、统一和领土完整造成严重危害；（二）对香港特别行政区政府或者中央人民政府制定和执行法律、政策进行严重阻挠并可能造成严重后果；（三）对香港特别行政区选举进行操控、破坏并可能造成严重后果；（四）对香港特别行政区或者中华人民共和国进行制裁、封锁或者采取其他敌对行动；（五）通过各种非法方式引发香港特别行政区居民对中央人民政府或者香港特别行政区政府的憎恨并可能造成严重后果。”这是该法关于勾结外国或者境外势力危害国家安全罪的规定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-35", "q": "村民张某与村委会就土地承包合同引发纠纷。应村委会要求，乡政府指派工作人员丈量有争议的土地时，毁坏了地里的青苗。对此，下列说法正确的是", "options": ["张某与村委会的纠纷应当通过诉讼途径解决", "乡政府的量地行为属于行政调解中的调查取证", "乡政府介入张某与村委会的纠纷缺乏法律依据", "村委会应当对毁坏的青苗承担行政赔偿责任"], "a": 1, "e": "【B】本题考查法律常识。A项、C项错误，《中华人民共和国农村土地承包经营纠纷调解仲裁法》第三条规定：“发生农村土地承包经营纠纷的，当事人可以自行和解，也可以请求村民委员会、乡(镇)人民政府等调解。”第四条规定：“当事人和解、调解不成或者不愿和解、调解的，可以向农村土地承包仲裁委员会申请仲裁，也可以直接向人民法院起诉。”B项正确，行政调解，是指由我国行政机关主持，通过说服教育的方式，民事纠纷或轻微刑事案件当事人自愿达成协议，解决纠纷的一种调解制度，通常称为政府调解。乡政府的量地行为是现场勘察和固定证据的行为，是调查取证。D项错误，行政赔偿，是指国家行政机关及其工作人员在行使职权的过程中侵犯公民、法人或其他组织的合法权益并造成损害，由国家承担赔偿责任的制度。《村民委员会组织法》第二条第一款规定：“村民委员会是村民自我管理、自我不能作为行政赔偿的主体，村委会对毁坏青苗的赔偿属于民事赔偿。故正确答案为B。", "tag": "法律常识"},
{"id": "law-36", "q": "村民会议可以制定村规民约。下列村规民约约定的内容，与法律法规相抵触的是", "options": ["村民的宅基地不得出售给城市居民", "村民参与赌博的，取消其一切村集体经济待遇", "举行婚丧喜庆活动，时间不得超过三天", "本村子弟考取大学的，给予一定物质奖励"], "a": 1, "e": "【B】本题考查法律常识。A项错误，《农村宅基地管理办法》第八条规定：农村村民宅基地的所有权属于集体，个人只有使用权，未经批准任何人不得擅自转让、出租。《关于加强土地转让管理严禁炒卖土地的通知》规定，“农民的住宅不得向城市居民出售，也不得批准城市居民占用农民集体土地建住宅”。故村民的宅基地不能出售给城市居民未违反法律规定。B项正确，村民是村集体中的一员，依法享有一切村集体经济的待遇，《村民委员会组织法》第二十七条第二款规定：“村民自治章程、村规民约以及村民会议或者村民代表会议的决定不得与宪法、法律、法规和国家的政策相抵触，不得有侵犯村民的人身权利、民主权利和合法财产权利的内容。”村规民约以村民赌博而取消一切村集体经济待遇侵犯了村民的合法财产权利。C项错误，举行婚丧喜庆活动不超过三天的村规民约顺应了全国厉行勤俭节约，反对铺张浪费的大形势和民意要求，利于规范婚庆事宜，与法律法规不冲突。D项错误，对于本村考上大学的学生给予物质奖励，是对大学生的一种赠与奖励，利于鼓励学生好好学习，形成良好的学习氛围，未违反民法、村民委员会组织法等的禁止性规定。故正确答案为B。", "tag": "法律常识"},
{"id": "law-37", "q": "关于社会保险制度，下列说法错误的是：", "options": ["社会保险基金经相关部门同意后，可用于平衡其他政府预算", "外国人在中国境内就业的，参照我国《社会保险法》规定参加社会保险", "基本医疗保险基金和基本养老保险基金应分别建账，分账核算，执行国家统一的会计制度", "国家建立社会保险制度，是为了保障公民在年老、疾病、工伤、失业、生育等情况下获得物质帮助"], "a": 0, "e": "【A】本题考查法律常识。A项错误，《社会保险法》第六十四条第二款规定：“社会保险基金专款专用，任何组织和个人不得侵占或者挪用。”《社会保险法》第六十九条规定：“社会保险基金不得违规投资运营，不得用于平衡其他政府预算，不得用于兴建、改建办公场所和支付人员经费、运行费用、管理费用，或者违反法律、行政法规规定挪作其他用途。”因此，社会保险基金即使经相关部门同意后，也不可用于平衡其他政府预算。B项正确，《社会保险法》第九十七条规定：“外国人在中国境内就业的，参照本法规定参加社会保险。”C项正确，《社会保险法》第六十四条第一款规定：“社会保险基金包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金。除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算。”因此，基本医疗保险基金和基本养老保险基金应分别建账，分账核算，执行国家统一的会计制度。D项正确，《社会保险法》第二条规定：“国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。”本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-38", "q": "下列行为没有违反广告法的是：", "options": ["某电视台养生节目推荐观众购买赞助商的按摩锤", "某6 岁童星代言著名厂商生产的学习机", "某小学的校车车身上载有儿童手表的车体广告", "某药品广告中已康复的患者分享自己的用药经历"], "a": 3, "e": "【D】本题考查法律常识。A项错误，《广告法》第十九条规定：“广播电台、电视台、报刊音像出版单位、互联网信息服务提供者不得以介绍健康、养生知识等形式变相发布医疗、药品、医疗器械、保健食品广告。”因此，该电视台养生节目推荐观众购买赞助商的按摩锤的行为违反广告法。B项错误，《广告法》第三十八条第二款规定：“不得利用不满十周岁的未成年人作为广告代言人。”因此，某6岁的童星代言学习机的行为违反了广告法。C项错误，《广告法》第三十九条规定：“不得在中小学校、幼儿园内开展广告活动，不得利用中小学生和幼儿的教材、教辅材料、练习册、文具、教具、校服、校车等发布或者变相发布广告，但公益广告除外。”在本选项中，儿童手表不是公益广告。因此，某小学的校车车身上载有儿童手表的车体广告违反了广告法。D项正确，《广告法》第十六条规定：“医疗、药品、医疗器械广告不得含有下列内容：（一）表示功效、安全性的断言或者保证；（二）说明治愈率或者有效率；（三）与其他药品、医疗器械的功效和安全性或者其他医疗机构比较；（四）利用广告代言人作推荐、证明；（五）法律、行政法规规定禁止的其他内容。”在本选项中，药品广告中只是用已康复的患者分享了自己的用药经历，其中并无表示功效、安全性的断言或者保证等违反广告法的行为。故正确答案为D。", "tag": "法律常识"},
{"id": "law-39", "q": "下列哪部法律不涉及公民个人信息保护？", "options": ["刑法", "网络安全法", "民法总则", "婚姻法"], "a": 3, "e": "【D】本题考查法律常识。A项正确，根据《刑法》第二百五十三条之一规定：“违反国家有关规定，向他人出售或者提供公民个人信息，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。违反国家有关规定，将在履行职责或者提供服务过程中获得的公民个人信息，出售或者提供给他人的，依照前款的规定从重处罚。窃取或者以其他方法非法获取公民个人信息的，依照第一款的规定处罚。”B项正确，根据《网络安全法》第四十四条规定：“任何个人和组织不得窃取或者以其他非法方式获取个人信息，不得非法出售或者非法向他人提供个人信息。”C项正确，根据《民法总则》第一百一十一条规定：“自然人的个人信息受法律保护。任何组织和个人需要获取他人个人信息的，应当依法取得并确保信息安全，不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息。”D项错误，《婚姻法》中并未涉及有关公民个人信息保护的规定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-40", "q": "下列关于全国经济普查的说法错误的是：", "options": ["根据《全国经济普查条例》的规定，经济普查每5 年进行一次", "目的是全面调查我国第一、第二、第三产业的发展规模、布局和效益", "普查取得的单位和个人资料，不作为对普查对象实施处罚的依据", "2019 年1 月1 日，第四次全国经济普查现场登记工作正式启动"], "a": 1, "e": "【B】本题考查法律常识。A项正确，《全国经济普查条例》第七条规定：“经济普查每5年进行一次，标准时点为普查年份的12月31日。”B项错误，《全国经济普查条例》第二条规定：“经济普查的目的，是为了全面掌握我国第二产业、第三产业的发展规模、结构和效益等情况，建立健全基本单位名录库及其数据库系统，为研究制定国民经济和社会发展规划，提高决策和管理水平奠定基础。”C项正确，《全国经济普查条例》第三十三条规定：“经济普查取得的单位和个人资料，严格限定用于经济普查的目的，不作为任何单位对经济普查对象实施处罚的依据。”D项正确，2019年1月1日零时，第四次全国经济普查现场登记工作正式启动。按照部署，第四次全国经济普查标准时点为2018年12月31日，普查时期资料为2018年年度资料。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-41", "q": "村民刘某欲将6 亩承包地以每亩每年900 元的价格流转。外地种田大户马某、本村村民孙某都有意流转刘某的承包地。下列关于该承包地流转的说法，正确的是", "options": ["该承包地的流转收益全部归刘某所有", "该承包地的流转期限可超过承包期的剩余期限", "马某是种田大户有技术优势，对承包地的流转有优先权", "刘某流转承包地后，与村农民集体的承包关系自动解除"], "a": 0, "e": "【A】本题考查法律常识。A项正确，根据《农村土地承包法》第三十九条的规定：“土地经营权流转的价款，应当由当事人双方协商确定。流转的收益归承包方所有，任何组织和个人不得擅自截留、扣缴。”所以，流转的收益归承包方所有，归刘某所有。B、C项错误，根据《农村土地承包法》第三十八条的规定：“土地经营权流转应当遵循以下原则：…(三)流转期限不得超过承包期的剩余期限;…(五)在同等条件下，本集体经济组织成员享有优先权。”所以，本村村民孙某是比马某享有优先权的。D项错误，《农村土地承包法》第四十四条规定：“承包方流转土地经营权的，其与发包方的承包关系不变。”所以，刘某与村民集体的承包关系不会改变。故正确答案为A。", "tag": "法律常识"},
{"id": "law-42", "q": "某物业服务公司登记了业主苏某的电话号码。下列属于物业公司非法使用苏某电话号码的情形是", "options": ["苏某的房屋漏水，物业公司将苏某的电话告知楼下邻居杨某", "苏某的房屋需要装修，物业公司将苏某的电话告知某装修公司", "苏某的煤气管道未经检测，物业公司将苏某的电话告知市燃气公司", "苏某的汽车阻挡了冯某开车出行，物业公司将苏某的电话告知冯某"], "a": 1, "e": "【B】本题考查法律常识。A项正确，《物权法》第九十二条规定：“不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害；造成损害的，应当给予赔偿。”本题中，苏某和杨某是楼上楼下的邻居，属于相邻关系的范畴，苏某房屋漏水，可能会造成杨某损失，物业及时将苏某电话告知杨某，便于降低损失或落实责任。B项错误，《物业管理条例》第五十二条规定：“业主需要装饰装修房屋的，应当事先告知物业服务企业。物业服务企业应当将房屋装饰装修中的禁止行为和注意事项告知业主。”但是房屋装修是业主的个人行为，物业服务企业不得擅自将业主电话号码告知装修公司，《物业管理条例》并未授予物业服务企业该项权利，擅自告知的行为可能会对业主生活造成骚扰。C项正确，《物业管理条例》第五十一条规定：“供水、供电、供气、供热、通信、有线电视等单位，应当依法承担物业管理区域内相关管线和设施设备维修、养护的责任。”物业将苏某电话告知市燃气公司，便于燃气公司及时联系苏某，尽快完成燃气管道检测、养护工作，以确保燃气使用安全。D项正确，《物业管理条例》第二条规定：“本条例所称物业管理，是指业主通过选聘物业服务企业，由业主和物业服务企业按照物业服务合同约定，对房屋及配套的设施设备和相关场地进行维修、养护、管理，维护物业管理区域内的环境卫生和相关秩序的活动。”物业公司将苏某电话告知冯某，便于疏导小区交通状况，也是物业履行维护物业管理区域内相关秩序职责的体现。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-43", "q": "下列不属于《中华人民共和国监察法》所规定的监督对象的是", "options": ["某居民委员会的主任", "某国有企业工会的主席", "某农民专业合作社的理事长", "某省属高校学报的主编"], "a": 2, "e": "【C】本题考查法律常识。《监察法》第十五条规定：“监察机关对下列公职人员和有关人员进行监察：（一）中国共产党机关、人民代表大会及其常务委员会机关、人民政府、监察委员会、人民法院、人民检察院、中国人民政治协商会议各级委员会机关、民主党派机关和工商业联合会机关的公务员，以及参照《中华人民共和国公务员法》管理的人员；（二）法律、法规授权或者受国家机关依法委托管理公共事务的组织中从事公务的人员；（三）国有企业管理人员；人员；（六）其他依法履行公职的人员。”A项正确，符合上述第（五）项的规定。B项正确，符合上述第（三）项的规定。C项错误，《农民专业合作社法》第二条规定：“农民专业合作社是在农村家庭承包经营基础上，同类农产品的生产经营者或者同类农业生产经营服务的提供者、利用者，自愿联合、民主管理的互助性经济组织。”农民专业合作社的理事长不属于公职人员，不属于《监察法》的监督对象。D项正确，符合上述第（二）项的规定。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-44", "q": "某公司董事长孙某当选为区人大代表。下列关于孙某履行代表义务的说法，正确的是", "options": ["孙某应协助区政府开展招商引资工作", "孙某应设立“人大代表工作室”开展调研工作", "孙某应定期将公司的经营状况报告区人大常委会", "孙某应积极参加对区人民法院执法情况的检查工作"], "a": 3, "e": "【D】本题考查法律常识。根据《代表法》第四条规定：“代表应当履行下列义务：（一）模范地遵守宪法和法律，保守国家秘密，在自己参加的生产、工作和社会活动中，协助宪法和法律的实施；（二）按时出席本级人民代表大会会议，认真审议各项议案、报告和其他议题，发表意见，做好会议期间的各项工作；（三）积极参加统一组织的视察、专题调研、执法检查等履职活动；密切联系，听取和反映他们的意见和要求，努力为人民服务；（六）自觉遵守社会公德，廉洁自律，公道正派，勤勉尽责；（七）法律规定的其他义务。”A、B、C项错误，D项正确，孙某应积极参加对区人民法院执法情况的检查工作符合《代表法》第四条第（三）项的规定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-45", "q": "①某运动服装广告里，一位运动员身披五星红旗，站在领奖台上；②某白酒广告出现未成年人说“请勿贪杯”后饮酒的情形；③某感冒药广告提到该药品对感冒的治愈高达百分之九十；④某牛奶广告出现描述自己产品是“冠军选择，最佳品质”的广告词。①~④中，违反了我国广告法规定的有（）。", "options": ["①②", "③④", "②③④", "①②③④"], "a": 3, "e": "【D】本题考查法律常识。①错误，根据《中华人民共和国广告法》第九条规定：“广告不得有下列情形：（一）使用或者变相使用中华人民共和国的国旗、国歌、国徽，军旗、军歌、军徽”①的广告使用了国旗，属于违反广告法规定的行为。②错误，根据《中华人民共和国广告法》第十条规定：“广告不得损害未成年人和残疾人的身心健康。”本法第二十三条规定：“酒类广告不得含有下列内容：（二）出现饮酒的动作”②的广告中出现未成年人饮酒的动作，损害了未成年人的身体健康，属于违反广告法规定的行为。③错误，根据《中华人民共和国广告法》第十六条第一款规定：“医疗、药品、医疗器械广告不得含有下列内容：（二）说明治愈率或者有效率。”③的广告说明了药品的治愈率，属于违反广告法规定的行为。④错误，根据《中华人民共和国广告法》第九条规定：“广告不得有下列情形：（三）使用‘国家级’、‘最高级’、‘最佳’等用语。”④的广告使用了“最佳”，属于违反广告法规定的行为。因此①②③④都违反了广告法。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-46", "q": "根据住房城乡建设部《生活垃圾分类制度实施方案》，下列选项属于有害垃圾的是：", "options": ["畜禽产品内脏", "废弃电子产品", "废旧纺织物", "废荧光灯管"], "a": 3, "e": "【D】本题主要考查法律常识。《生活垃圾分类制度实施方案》是一部关于生活垃圾分类的方案。该法案于2017年3月18日经国务院同意，转发给国家发展改革委、住房城乡建设部，且要求认真贯彻执行。A项错误，畜禽产品内脏，属于易腐垃圾。该《方案》规定易腐垃圾的主要品种包括：相关单位食堂、宾馆、饭店等产生的餐厨垃圾，农贸市场、农产品批发市场产生的蔬菜瓜果垃圾、腐肉、肉碎骨、蛋壳、畜禽产品内脏等。BC项错误，废弃电子产品和废旧纺织物，都属于可回收物。该《方案》规定可回收物的主要品种包括：废纸，废塑料，废金属，废包装物，废旧纺织物，废弃电器电子产品，废玻璃，废纸塑铝复合包装等。D项正确，废荧光灯管，属于有害垃圾。该《方案》规定有害垃圾的主要品种包括：废电池（镉镍电池、氧化汞电池、铅蓄电池等），废荧光灯管（日光灯管、节能灯等），废温度计，废血压计，废药品及其包装物，废油漆、溶剂及其包装物，废杀虫剂、消毒剂及其包装物，废胶片及废相纸等。故正确答案为D。", "tag": "法律常识"},
{"id": "law-47", "q": "县公安局以涉嫌盗窃犯罪为由将甲拘留，县人民检察院批准对甲的逮捕。3 个月后，经甲的亲属暗中查访并向公安机关提供线索，公安机关抓获了真正的罪犯，县人民检察院对甲作出不起诉决定，甲遂请求国家赔偿。下列说法正确的是：", "options": ["县公安局和人民检察院没有违法行为，国家对甲不承担赔偿责任", "县公安局和人民检察院为共同赔偿义务机关", "县人民检察院作出不起诉决定是对错捕行为的确认", "县公安局应当对错误拘留造成的损失承担赔偿责任"], "a": 2, "e": "【C】本题主要考查国家赔偿的相关知识。国家赔偿是指国家机关及其工作人员因行使职权给公民、法人及其他组织的人身权或财产权造成损害，依法应给予的赔偿。国家赔偿由侵权的国家机关履行赔偿义务。《中华人民共和国国家赔偿法》第二十一条规定：“行使侦查、检察、审判职权的机关以及看守所、监狱管理机关及其工作人员在行使职权时侵犯公民、法人和其他组织的合法权益造成损害的，该机关为赔偿义务机关。对公民采取拘留措施，依照本法的规定应当给予国家赔偿的，作出拘留决定的机关为赔偿义务机关。对公民采取逮捕措施后决定撤销案件、不起诉或者判决宣告无罪的，作出逮捕决定的机关为赔偿义务机关。”《最高人民法院、最高人民检察院关于办理刑事赔偿案件适用法律若干问题的解释》第十一条规定：“对公民采取拘留措施后又采取逮捕措施，国家承担赔偿责任的，作出逮捕决定的机关为赔偿义务机关。”本题中，县人民检察院对甲作出逮捕决定，故县人民检察院为赔偿义务机关，县公安局不需要对其拘留措施承担赔偿义务。故A、B、D三项错误。C项正确，《最高人民法院赔偿委员会关于检察机关不起诉决定是对错误逮捕确认的批复》规定：“根据刑事诉讼法规定，人民检察院因‘事实不清、证据不足’作出的不起诉决定是人民检察院依照刑事诉讼法对该刑事案件审查程序的终结，是对犯罪嫌疑人不能认定有罪的决定。从法律意义上讲，对犯罪嫌疑人不能认定有罪的，该犯罪嫌疑人即是无罪。人民检察院因‘事实不清、证据不足’作出的不起诉决定，应视为是对犯罪嫌疑人作出的认定无罪的决定，同时该不起诉决定即是人民检察院对错误逮捕行为的确认，无需再行确认。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-48", "q": "下列表述中，不符合《中华人民共和国监察法》的一项是（）。", "options": ["中华人民共和国国家监察委员会是最高监察机关，领导地方各级监察委员会的工作", "地方各级监察委员会主任每届任期同本级人民代表大会每届任期相同，连选连任不得超过两届", "国家监察委员会由全国人民代表大会产生，负责全国监察工作", "监察委员会履行监督、调查、处置等职责"], "a": 1, "e": "【B】本题考查法律常识，主要考查《中华人民共和国监察法》的相关知识。A项正确，根据《中华人民共和国监察法》第七条第一款规定：“中华人民共和国国家监察委员会是最高监察机关。”《中华人民共和国监察法》第十条规定：“国家监察委员会领导地方各级监察委员会的工作，上级监察委员会领导下级监察委员会的工作。”B项错误，根据《中华人民共和国监察法》第九条第三款规定：“地方各级监察委员会主任每届任期同本级人民代表大会每届任期相同。”没有“连选连任不得超过两届”的说法。C项正确，根据《中华人民共和国监察法》第八条第一款规定：“国家监察委员会由全国人民代表大会产生，负责全国监察工作。”D项正确，根据《中华人民共和国监察法》第十一条规定：“监察委员会依照本法和有关法律规定履行监督、调查、处置职责。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-49", "q": "下列表述中，正确的一项是（）", "options": ["小张为某企业员工，打算辞职，须在20 日前向单位提交书面辞职申请，这一做法符合劳动法的相关规定", "小李企图入室盗窃，但因入户门锁无法撬开，多次尝试未果，只好放弃，这属于犯罪中止", "小王在网络上匿名发布关于某明星的虚假新闻，对其造成名誉伤害，小王不需要承担法律责任", "小赵在公交车上发现小吴偷其钱包，对其穷追猛打致其死亡，这属于防卫过当"], "a": 3, "e": "【D】本题考查法律常识，涉及劳动法、民法、刑法知识。A项错误，《劳动法》第三十一条规定：“劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。”因此，小张的做法不符合劳动法的规定。B项错误，《刑法》第二十三条第一款规定：“已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂。”《刑法》第二十四条第一款规定：“在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。”本选项中，小李是由于无法撬开门锁才导致的盗窃未成功，属于小李意志以外的因素而未得逞，是犯罪未遂。C项错误，《民法总则》第一百一十条第一款规定：“自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利。”公民的名誉权若受到侵害，有权要求对方停止侵害，恢复名誉，消除影响，赔礼道歉。因此，小王侵犯了明星的名誉权，应当承担法律责任。D项正确，《刑法》第二十条第一款规定：“为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。”第二款规定：“正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚。”在本选项中，小赵为了使自己的权利免受不法侵害，可以采取正当防卫，但是小赵将小吴打死，明显超过了必要的限度并造成重大损害，构成防卫过当。故正确答案为D。", "tag": "法律常识"},
{"id": "law-50", "q": "下列与证件有关的说法错误的是：", "options": ["未满十六周岁的公民不得申领居民身份证", "驾驶机动车上路行驶必须随车携带行驶证", "公共场所直接为顾客服务的人员须有健康证", "港澳通行证由我国公安部出入境管理局签发"], "a": 0, "e": "【A】本题主要考查与证件有关的法律法规。A项错误，根据《中华人民共和国居民身份证法》第五条规定：“未满十六周岁的公民，自愿申请领取居民身份证的，发给有效期五年的居民身份证。”因此选项表述错误。B项正确，根据我国《道路交通安全法》第十一条规定：“驾驶机动车上道路行驶，应当悬挂机动车号牌，放置检验合格标志、保险标志，并随车携带机动车行驶证。”因此选项表述正确。C项正确，根据我国《公共场所卫生管理条例》第七条规定：公共场所直接为顾客服务的人员，持有“健康合格证”方能从事本职工作。因此选项表述正确。D项正确，港澳通行证是由中华人民共和国公安部出入境管理局签发给中国内地居民因私往来香港或澳门地区旅游、探亲、从事商务、培训、就业、留学等非公务活动的旅行证件。因此选项表述正确。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-51", "q": "下列有关村民委员会的说法正确的是（）", "options": ["村民委员会的主任人选应由村党支部提名", "村民委员会组成人员由村民代表选举产生", "村民委员会接受乡人民政府领导并对它负责", "村民委员会协助乡人民政府开展工作"], "a": 3, "e": "【D】本题考查法律常识，主要考查《村民委员会组织法》的相关知识点。A、B项错误，《村民委员会组织法》第十一条第一款规定：“村民委员会主任、副主任和委员，由村民直接选举产生。任何组织或者个人不得指定、委派或者撤换村民委员会成员。”故AB选项表述均错误。C项错误，D项正确。根据《村民委员会组织法》第五条规定：“乡、民族乡、镇的人民政府对村民委员会的工作给予指导、支持和帮助，但是不得干预依法属于村民自治范围内的事项。村民委员会协助乡、民族乡、镇的人民政府开展工作。”所以，村民委员会与乡人民政府没有领导与被领导的关系，C项错误；D项“村民委员会协助乡人民政府开展工作”的说法正确。故正确答案为D。", "tag": "法律常识"},
{"id": "law-52", "q": "根据《中华人民共和国妇女权益保障法》，实行男女平等是国家的基本国策。国家采取必要措施，逐步完善保障妇女权益的各项制度，消除对妇女一切形式的歧视。对此，下列说法错误的是（）。", "options": ["禁止歧视、虐待、遗弃、残害妇女", "妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利", "国家采取有效措施，适当减轻妇女履行法律规定义务的责任", "国家保护妇女依法享有的特殊权益"], "a": 2, "e": "【C】本题考查法律常识，主要涉及《中华人民共和国妇女权益保障法》的相关内容。A项正确，《妇女权益保障法》第二条第四款规定：“禁止歧视、虐待、遗弃、残害妇女。”B项正确，《妇女权益保障法》第二条第一款规定：“妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利。”C项错误，《妇女权益保障法》第二条第二款规定：“实行男女平等是国家的基本国策。国家采取必要措施，逐步完善保障妇女权益的各项制度，消除对妇女一切形式的歧视。”，并不是适当减轻妇女履行法定义务的责任，在履行法定义务的责任是男女平等的。D项正确，《妇女权益保障法》第二条第三款规定：“国家保护妇女依法享有的特殊权益。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-53", "q": "按照我国现行《社会救助暂行办法》，国家建立健全自然灾害救助制度，对（）受到自然灾害严重影响的人员，提供生活救助。", "options": ["基本生活", "日常生活", "工作生活", "家庭生活"], "a": 0, "e": "【A】本题考查法律常识。《社会救助暂行办法》第二十条规定：“国家建立健全自然灾害救助制度,对基本生活受到自然灾害严重影响的人员,提供生活救助。”A项正确，符合法律条文的规定。B、C、D三项均错误，不符合法律条文的表述。故正确答案为A。", "tag": "法律常识"},
{"id": "law-54", "q": "巡视是党内监督的重要方式，下列关于巡视工作的说法错误的是（）。", "options": ["党的中央和省、自治区、直辖市委员会实行巡视制度，建立专职巡视机构", "巡视工作坚持中央统一领导、分级负责", "巡视组依靠被巡视党组织开展工作，履行执纪审查的职责，但不得干预被巡视地区（单位）的正常工作", "派出巡视组的党组织及其组织部门应当把巡视结果作为干部考核评价、选拔任用的重要依据"], "a": 2, "e": "【C】本题考查巡视工作条例相关内容。A项正确，《中国共产党巡视工作条例》第二条规定：“党的中央和省、自治区、直辖市委员会实行巡视制度，建立专职巡视机构，在一届任期内对所管理的地方、部门、企事业单位党组织全面巡视。”B项正确，《中国共产党巡视工作条例》第四条规定：“巡视工作坚持中央统一领导、分级负责；坚持实事求是、依法C项错误，《中国共产党巡视工作条例》第十八条规定：“巡视组依靠被巡视党组织开展工作，不干预被巡视地区(单位)的正常工作，不履行执纪审查的职责。”D项正确，《中国共产党巡视工作条例》第三十条规定：“派出巡视组的党组织及其组织部门应当把巡视结果作为干部考核评价、选拔任用的重要依据。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-55", "q": "甲将其电脑借给乙使用，乙却将该电脑卖给丙。依据我国《合同法》的规定，下列关于乙丙之间买卖电脑的合同效力的表述，正确的是：", "options": ["无效", "有效", "效力待定", "可变更或撤销"], "a": 1, "e": "【B】本题考查合同法。根据《合同法》第一百三十二条规定，出卖的标的物，应当属于出卖人所有或者出卖人有权处分。法律、行政法规禁止或者限制转让的标的物，依照其规定。可知本题中乙为无权处分人。又因《最高人民法院关于审理买卖合同纠纷案件适用法律问题的解释》第三条【无权处分买卖合同效力】规定，当事人一方以出卖人在缔约时对标的物没有所有权或者处分权为由主张合同无效的，人民法院不予支持。故可知该合同为有效合同。故正确答案为B。备注：关于无权处分的买卖合同的效力，在实践中有一定的争议。有些学者认为应当依据《合同法》第五十一条规定：“无处分权的人处分他人财产，经权利人追认或者无处分权的人订立合同后取得处分权的，该合同有效。”认为是效力待定。有些学者认为应当依据《最高人民法院关于审理买卖合同纠纷案件适用法律问题的解释》第三条【无权处分买卖合同效力】规定，当事人一方以出卖人在缔约时对标的物没有所有权或者处分权为由主张合同无效的，人民法院不予支持。认定有效。目前粉笔采取的是司法考试的观点，依照合同法司法解释，认定为有效。", "tag": "法律常识"},
{"id": "law-56", "q": "《中华人民共和国国歌法》于2017 年10 月1 日起施行。该法是为了维护国歌的尊严，规范国歌的奏唱、播放和使用，增强公民的国家观念，弘扬爱国主义精神，培育和践行社会主义核心价值观，根据宪法所制定。根据该法，下列表述不正确的是。", "options": ["在公共场合侮辱国歌的，由公安机关依法追究刑事责任", "国歌不得作为公共场所的背景音乐使用", "中华人民共和国国歌是中华人民共和国的象征和标志", "县级以上各级人民政府及其有关部门在各自职责范围内，对国歌的奏唱、播放和使用进行监督管理"], "a": 0, "e": "【A】A项错误，《中华人民共和国国歌法》第十五条规定，在公共场合,故意篡改国歌歌词、曲谱,以歪曲、贬损方式奏唱国歌，或者以其他方式侮辱国歌的，由公安机关处以警告或者十五日以下拘留；构成犯罪的，依法追究刑事责任。因此根据法条规定，在公共场合侮辱国歌只有构成犯罪时才会被追究刑事责任。B项正确，《中华人民共和国国歌法》第八条规定，国歌不得用于或者变相用于商标、商业广告，不得在私人丧事活动等不适宜的场合使用，不得作为公共场所的背景音乐等。C项正确，《中华人民共和国国歌法》第三条规定，中华人民共和国国歌是中华人民共和国的象征和标志。一切公民和组织都应当尊重国歌，维护国歌的尊严。D项正确，《中华人民共和国国歌法》第十四条规定，县级以上各级人民政府及其有关部门在各自职责范围内，对国歌的奏唱、播放和使用进行监督管理。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-57", "q": "公安机关职权描述不正确的是（）。", "options": ["需要调查取证的，应迅速开展调查", "调查暴恐嫌疑人员，只能在公安机关进行", "关于暴恐相关调查，有权向单位、个人收集信息", "针对暴恐嫌疑人员，要按照法律规定进行调查、盘问、传唤"], "a": 1, "e": "【B】A项正确，《反恐怖主义法》第四十九条规定：公安机关接到恐怖活动嫌疑的报告或者发现恐怖活动嫌疑，需要调查核实的，应当迅速进行调查。A项表述与其一致，故A项正确，故排除；B项错误，《反恐怖主义法》第五十条规定：公安机关调查恐怖活动嫌疑，可以通知了解有关情况的人员到公安机关或者其他地点接受询问。B项“只能在公安机关进行”表述错误，当选；C项正确，《反恐怖主义法》第五十一条规定：公安机关调查恐怖活动嫌疑，有权向有关单位和个人收集、调取相关信息和材料。有关单位和个人应当如实提供。C项表述与其一致，故C项正确，故排除；D项正确，《反恐怖主义法》第五十条规定：公安机关调查恐怖活动嫌疑，可以依照有关法律规定对嫌疑人员进行盘问、检查、传唤，可以提取或者采集肖像、指纹、虹膜图像等人体生物识别信息和血液、尿液、脱落细胞等生物样本，并留存其签名。D项表述与其一致，故D项正确，故排除。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-58", "q": "新疆维吾尔自治区宗教活动场所管理经组织成员（）产生，并向该场所登记机关备案。", "options": ["领导小组推选", "经委派", "民主选举", "民主协商"], "a": 3, "e": "【D】《新疆维吾尔自治区宗教事务条例》第十八条规定：宗教活动场所应当成立管理组织，实行民主管理。宗教活动场所管理组织的成员经民主协商推选产生，并向该场所登记机关备案。宗教活动场所管理组织的成员应当遵纪守法。故正确答案为D。", "tag": "法律常识"},
{"id": "law-59", "q": "关于我国巡回法庭，下列说法错误的是：", "options": ["巡回法庭作出的判决、裁定和决定，是最高人民法院的判决、裁定和决定", "最高人民法院设立巡回法庭是对我国二审终审制的变通规定", "巡回法庭的受案范围暂不包括最高人民检察院抗诉的案件", "巡回法庭根据审判工作需要，可以在巡回区内接待来访"], "a": 1, "e": "【B】B项错误：二审终审制是指一个案件经过两级人民法院审判即告终结的制度，对于第二审人民法院作出的终审判在辖区设置巡回地点，定期或不定期到巡回地点受理并审判案件的制度，也需遵循二审终审制。A项正确：《最高人民法院关于巡回法庭审理案件若干问题的规定》第二条：巡回法庭是最高人民法院派出的常设审判机构。巡回法庭作出的判决、裁定和决定，是最高人民法院的判决、裁定和决定。C项正确：《最高人民法院关于巡回法庭审理案件若干问题的规定》第三条：巡回法庭审理或者办理巡回区内应当由最高人民法院受理的以下案件：（一）全国范围内重大、复杂的第一审行政案件；（二）在全国有重大影响的第一审民商事案件；（三）不服高级人民法院作出的第一审行政或者民商事判决、裁定提起上诉的案件；（四）对高级人民法院作出的已经发生法律效力的行政或者民商事判决、裁定、调解书申请再审的案件；（五）刑事申诉案件；（六）依法定职权提起再审的案件；（七）不服高级人民法院作出的罚款、拘留决定申请复议的案件；（八）高级人民法院因管辖权问题报请最高人民法院裁定或者决定的案件；（九）高级人民法院报请批准延长审限的案件；（十）涉港澳台民商事案件和司法协助案件；（十一）最高人民法院认为应当由巡回法庭审理或者办理的其他案件。不包括最高人民检察院抗诉的案件。D项正确：《最高人民法院关于巡回法庭审理案件若干问题的规定》第九条：巡回法庭根据审判工作需要，可以在巡回区内巡回审理案件、接待来访。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-60", "q": "下列关于食品药品监管说法正确的是：", "options": ["获得“驰名商标”称号，且连续5 年产品抽检合格的食品生产厂家，其所生产的食品可获免检资格", "药品包装上印有“OTC”字样的，表明该药品为处方药", "保健品、药品均需国家食品药品监督管理总局批准注册", "个人姓名不可注册为食品商标"], "a": 2, "e": "【C】本题考查法律常识。A项，错误：《食品安全法》第八十七条：县级以上人民政府食品药品监督管理部门应当对食品进行定期或者不定期的抽样检验，并依据有关规定公布检验结果，不得免检。进行抽样检验，应当购买抽取的样品，委托符合本法规定的食品检验机构进行检验，并支付相关费用；不得向食品生产经营者收取检验费和其他费用。根据规定，不得免检。B项，错误：OTC是英文OverTheCounter，是可在柜台上买到的药物的缩写，即那些不需要医生处方，消费者可直接在药房或药店中购取的药物。C项正确，根据《保健食品注册与备案管理办法》第五条规定，国家食品药品监督管理总局负责保健食品注册管理。根据《药品注册管理办法》第五条规定，国家食品药品监督管理局主管全国药品注册工作，负责对药物临床试验、药品生产和进口进行审批。D项，错误：《商标法》第十一条规定：“下列标志不得作为商标注册：（一）仅有本商品的通用名称、图形、型号的；（二）仅直接表示商品的质量、主要原料、功能、用途、重量、数量及其他特点的；（三）其他缺乏显著特征的。”我国法律并未规定个人姓名不可注册为食品商标，个人姓名注册为食品商标并未违反国家禁止性规定，典型的反例是“王守义十三香”。故正确答案为C。", "tag": "法律常识"},
{"id": "law-61", "q": "下列不符合我国《居民身份证法》规定的是：", "options": ["甲是大陆投资、定居的台商，不能申请领取居民身份证", "乙到派出所办理常住户口登记变更手续，应当出示居民身份证", "丙遗失了居民身份证，可办理户籍证明来证明身份并乘坐火车", "丁在码头候船遇警察查验身份时，应向警察出示居民身份证"], "a": 0, "e": "【A】A项说法错误：《中华人民共和国居民身份证法》第九条规定：“香港同胞、澳门同胞、台湾同胞迁入内地定居的，华侨回国定居的，以及外国人、无国籍人在中华人民共和国境内定居并被批准加入或者恢复中华人民共和国国籍的，在办理常住户口登记时，应当依照本法规定申请领取居民身份证。”当选。B项说法正确：《中华人民共和国居民身份证法》第十四条第一款规定：“有下列情形之一的，公民应当出示居民身份证证明身份：（一）常住户口登记项目变更；（二）兵役登记；（三）婚姻登记、收养登记；（四）申请办理出境手续；（五）法律、行政法规规定需要用居民身份证证明身份的其他情形。”排除。C项说法正确：根据中国铁路客户服务中心网站的规定，旅客购票时或购票后、乘车前因有效身份证件未携带、丢失等原因无法出示有效证件时，可以至车站铁路公安制证口办理临时乘车身份证明。办理时，须符合下列条件之一，并携带一寸照片一张：①出具所在地公安机关的户籍证明信；②学生旅客出具所在学校的证明信；③中国人民解放军、武警部队现役军人持所在部队出具的证明信；④外籍旅客持当地使领馆出具的证明信；⑤凭其他有效证件购买车票的旅客持发证部门出具的证明信；⑥通过其他方式能够证明本人身份的。排除。D项说法正确：《中华人民共和国居民身份证法》第十五条第一、二款规定：“人民警察依法执行职务，遇有下列情形之一的，经出示执法证件，可以查验居民身份证：（一）对有违法犯罪嫌疑的人员，需要查明身份的；（二）依法实施现场管制时，需要查明有关人员身份的；（三）发生严重危害社会治安突发事件时，需要查明现场有关人员身份的；（四）在火车站、长途汽车站、港口、码头、机场或者在重大活动期间设区的市级人民政府规定的场所，需要查明有关人员身份的；（五）法律规定需要查明身份的其他情形。有前款所列情形之一，拒绝人民警察查验居民身份证的，依照有关法律规定，分别不同情形，采取措施予以处理。”排除。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-62", "q": "新《广告法》于2015 年9 月1 日起正式施行，下列选项符合新《广告法》规定的是：", "options": ["童星小明九周岁，代言某文具用品广告", "某制药企业宣称其产品“药到病除，永不再犯”", "某网站弹幕广告必须点击查看详情后才能关闭", "某医疗机构虚假宣传情节严重，工商和卫生行政部门均对其处罚"], "a": 3, "e": "【D】D项正确：《广告法》第五十八条第二款规定：“医疗机构有违法行为，情节严重的，除由工商行政管理部门依照本法处罚外，卫生行政部门可以吊销诊疗科目或者吊销医疗机构执业许可证。”A项错误：《广告法》第三十八条第二款规定：“不得利用不满十周岁的未成年人作为广告代言人。”该项中小明九岁，违反《广告法》规定。B项错误：《广告法》第十六条第一款规定：“医疗、药品、医疗器械广告不得含有下列内容：（一）表示功效、安全性的断言或者保证；……”该项中制药企业宣称其产品“药到病除、永不再犯”属于对功效的断言和保证，违反《广告法》规定。C项错误：《广告法》第四十四条第二款规定：“利用互联网发布、发送广告，不得影响用户正常使用网络。在互联网页面以弹出等形式发布的广告，应当显著标明关闭标志，确保一键关闭。”该项中网站弹幕广告必须点击查看详情后才能关闭，不符合一键关闭要求，违反《广告法》规定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-63", "q": "关于我国的住房公积金制度，下列说法不正确的是：", "options": ["具有强制性、互助性和保障性等特征", "由用人单位和职工个人共同缴纳", "贷款利率一般低于相同期限的商业贷款的利率", "贷款风险由经办住房公积金贷款业务的银行承担"], "a": 3, "e": "【D】住房公积金制度具有强制性、互助性和保障性特点。具体来说，体现在以下几个方面：其一，“强制”地调整人们的消费结构，人们必须把一部分收入积累起来用于住房消费；其二，增强工薪阶层购房能力，雇主必须按1：1的比例在缴存人账户中存入等额的钱；其三，具有强大的互助功能，人们可以从社会归集的公积金中贷款用于住房消费；其四，公积金账户缴存的钱免缴个人所得税；其五，公积金贷款可享受低于商业银行普通住房贷款利率的政策性优惠利率。据上可知，A、C选项正确。根据《住房公积金管理条例》第三条规定：“职工个人缴存的住房公积金和职工所在单位为职工缴存的住房公积金，属于职工个人所有。”所以B选项正确。《住房公积金管理条例》第二十六条规定：“住房公积金贷款的风险，由住房公积金管理中心承担。”而不是银行承担，D选项错误。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-64", "q": "关于我国的社会救助制度，下列说法不正确的是：", "options": ["最低生活保障是社会救助制度的基本内容", "积极参与开展社会救助是集体和社会成员的法定义务", "临时救助的具体事项、标准，由县级以上地方人民政府确定、公布", "县级以上地方人民政府应当确保最低生活保障家庭有劳动能力的成员中至少有一人就业"], "a": 1, "e": "【B】根据2014年5月1日国务院出台的《社会救助暂行办法》：“社会救助的基本内容包括最低生活保障、特困人员供养、受灾人员救助、医疗救助等。”A选项正确；该办法第五十二条规定：“国家鼓励单位和个人等社会力量通过捐赠、设立帮扶项目、创办服务机构、提供志愿服务等方式，参与社会救助。”但并没有规定是法定义务，所以B选项说法错误；该办法第四十九条规定：“临时救助的具体事项、标准，由县级以上地方人民政府确定、公布。”所以C选项说法正确；该办法第四十三条规定：“最低生活保障家庭有劳动能力的成员均处于失业状态的，县级以上地方人民政府应当采取有针对性的措施，确保该家庭至少有一人就业。”D选项说法正确。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-65", "q": "下列关于国家征收农民集体所有土地补偿的规定，说法错误的是：", "options": ["征收农民集体土地，需要按照被征收土地的原用途予以补偿", "征收耕地以外其他土地的补偿标准由省、自治区、直辖市规定", "被征收土地上的附着物和青苗的补偿标准，由市、县人民政府规定", "征收耕地应给予土地补偿费、安置补助费、地上附着物和青苗的补偿费"], "a": 2, "e": "【C】根据《中华人民共和国土地管理法》第四十七条相关规定，征收土地的，按照被征收土地的原用途给予补偿。征收耕地的补偿费用包括土地补偿费、安置补助费以及地上附着物和青苗的补偿费。征收其他土地的土地补偿费和安置补助费标准，由省、自治区、直辖市参照征收耕地的土地补偿费和安置补助费的标准规定。被征收土地上的附着物和青苗的补偿标准，由省、自治区、直辖市规定。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-66", "q": "某村是所在乡的人口第一大村，村民委员会经民主选举成立后通过了一系列事项，下列事项符合法律规定的是：", "options": ["村委会采取主任负责制", "村里财务每两年公布一次", "村委会设置多个下属委员会", "村委会向村党支部负责并报告工作"], "a": 2, "e": "【C】C项正确：《村民委员会组织法》第七条规定：“村民委员会根据需要设人民调解、治安保卫、公共卫生与计划生育等委员会。村民委员会成员可以兼任下属委员会的成员。……”自治组织，应当实行少数服从多数的民主决策机制和公开透明的工作原则，建立健全各种工作制度。可知，村委会不是采取主任负责制。B项错误：《村民委员会组织法》第三十条规定：“村民委员会实行村务公开制度。……集体财务往来较多的，财务收支情况应当每月公布一次；……”D项错误：《村民委员会组织法》第二条规定：“……村民委员会向村民会议、村民代表会议负责并报告工作。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-67", "q": "大学毕业生王某打算在A 市创业，在申办企业的过程中，恰逢该市大力推进行政审批制度改革，关于此次改革对王某申办企业的影响，下列说法错误的是：", "options": ["王某无需提供企业注册场所的证明文件", "王某可通过线上系统随时了解申办进度", "王某无需缴纳政府收费清单以外的费用", "王某可领取“一照一码”的营业执照"], "a": 0, "e": "【A】A项说法错误：《中华人民共和国公司登记管理条例》第二十条规定：“申请设立有限责任公司，应当向公司登记机关提交下列文件：（八）公司住所证明；”《中华人民共和国公司登记管理条例》第二十一条规定：“申请设立股份有限公司，应当向公司登记机关提交下列文件：（八）公司住所证明；”因此，王某无论申办哪一种公司，都需要提供企业注册场所的证明文件。B项说法正确：在部分试点城市已经开始推行网上企业登记，建立和实施电子执照制度。如上海市，已经可以通过该市工商行政管理局的官网进行企业登记状态查询。C项说法正确：2015年9月财政部、国家发改委联合印发的《关于取消和暂停征收一批行政事业性收费有关问题的通知》中明确规定：“取消属于政府提供普遍公共服务或体现一般性管理职能，以及主要目的是养人、违背市场经济基本原则的不合理收费项目。坚决取缔各种乱收费。”D项说法正确：从2015年10月1日起，我国全面实行“一照一码”登记模式，由工商、质检、税务3个部门分别核发不同证照，改为由工商部门核发加载统一社会信用代码的营业执照。因此，王某在大力推进行政审批制度改革的城市中可以领取“一照一码”的营业执照。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-68", "q": "下列法律现象与概念对应错误的是：", "options": ["春秋之治狱，论心定罪——自由裁量权", "载于简牍谓之书，合而验之谓之契——合同", "一兔走，百人追之；积兔于市，过而不顾——物权", "罪疑惟轻，功疑惟重。与其杀不辜，宁失不经——疑罪从无"], "a": 0, "e": "【A】A项错误，“春秋之治狱，论心定罪”对应“原心定罪”，其内容是在审判中重点考察犯罪者的动机是否合乎儒家道德，如不合乎，必须严惩；如合乎，虽犯法亦可从轻论处。这一审判原则从道德至上的立场出发，过分强调了犯罪者的主观动机而相对忽视了犯罪的客观事实，从而为酷吏任意处置罪犯打开了方便之门。由此可知A项法律现象与概念对应错误，当选。B项正确，“载于简牍谓之书，合而验之谓之契”对应的是合同。主要由于书契在买卖交易中又称为“质剂”，在古代使用简牍书写时，总是将交易内容一式两份同时写在简牍两边，然后从中间破别开来，两家各得其一，检验时两片验之相合称为契合。C项正确，“一兔走，百人追之；积兔于市，过而不顾”意思是说一个兔子跑，很多人去追，但对于集市上的那么多的兔子，人们却看也不看。这不是不想要兔子，而是所有权已经确定，不能再争夺了，否则就是违背法律，要受到制裁。这是法家的思想，主要强调法律，尤其是物权的作用，排除。D项正确，“罪疑惟轻，功疑惟重。与其杀不辜，宁失不经”出自《尚书》，基本含义是，在处理两可的疑难案件时，宁可偏宽不依常法，也不能错杀无辜。此概念源自西周，西周时期为保证适用法律的谨慎，防止错杀无辜，凡是疑难案件，都采取了从轻处断或赦免的办法。这就是中国古代“疑罪从无”法律思想的一个印证，排除。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-69", "q": "某县开展行政执法大检查：①某食品厂生产腐竹时非法添加硼砂被当场查获，县工商局以证据确凿为由吊销该厂营业执照，不再另行举行听证会；②县矿业公司将含镉的工业废渣倾倒入河，造成河水镉浓度超标，县环保局、县水利局分别进行查封、送检。上述县直单位做法妥当的是：", "options": ["县工商局", "县环保局", "县水利局", "县卫生局"], "a": 1, "e": "【B】根据《工商行政管理机关行政处罚案件听证规则》第六条：工商行政管理机关作出下列行政处罚决定之前，应当告知当事人有要求举行听证的权利……（三）吊销、收缴或者扣缴营业执照、吊销广告经营许可证、撤销商标注册、撤销特殊标志登记……可知①句中工商局的做法不妥当，排除A。根据《中华人民共和国水污染防治法》第八条：县级以上人民政府环境保护主管部门对水污染防治实施统一监督管理，以及《中华人民共和国行政处罚法》第二十四条：对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚,可知②句中罚款应由县环保局决定，县水利局做法不对，排除C。根据卫生监督执法行为规范的相关规定：卫生监督执法人员在进行现场检查时应不少于2人，穿戴制服，出示行政执法证件，说明来意及检查依据，告知被检查人的权利和义务。可知③句中县卫生局做法不妥当，排除D。故正确答案为B。", "tag": "法律常识"},
{"id": "law-70", "q": "中华人民共和国公民，都有服兵役的义务，以下应履行该义务的是：", "options": ["被判处管制附加剥夺政治权利的李某", "因民族宗教信仰不愿履行兵役的蓝某", "幼时发高烧致使出现生理失聪的段某", "身体严重残疾而无法正常训练的张某"], "a": 1, "e": "【B】本题考查法律常识。《中华人民共和国兵役法》第三条规定：“中华人民共和国公民，不分民族、种族、职业、家庭出身、宗教信仰和教育程度，都有义务依照本法的规定服兵役。有严重生理缺陷或者严重残疾不适合服兵役的人，免服兵役。依照法律被剥夺政治权利的人，不得服兵役。”A项错误，剥夺政治权利的李某不得服兵役。B项正确，中华人民共和国公民，不分民族、种族、职业、家庭出身、宗教信仰和教育程度，都有义务服兵役，蓝某不可因民族宗教信仰不履行服兵役的义务。C项错误，有严重生理缺陷的段某可免服兵役。D项错误，严重残疾不适合服兵役的张某可免服兵役。故正确答案为B。", "tag": "法律常识"},
{"id": "law-71", "q": "警方在一家餐馆内展开抓捕行动，由于犯罪嫌疑人暴力抵抗，餐馆部分物品在抓捕过程中被损坏，餐馆的营业秩序受到一定影响。关于餐馆的损失，下列说法中正确的是：", "options": ["应由餐馆自行承担", "应由实施抓捕的警察赔偿", "应由犯罪嫌疑人赔偿", "应由国家补偿"], "a": 3, "e": "【D】D项正确：国家补偿是指国家对国家机关及其工作人员的合法行使职权行为对公民造成的损失给予的补偿。本题中，餐馆的损失是由于警方在抓捕犯罪嫌疑人造成的，属于合法行使职权行为时造成的损失，应当由国家给予补偿；A项错误：餐馆的损失是由于警方抓捕犯罪嫌疑人造成，不应由餐馆自行承担；B项错误：《警察法》第五十条规定:“人民警察在执行职务中，侵犯公民或者组织的合法权益造成损害的，应当依照《中华人民共和国国家赔偿法》和其他有关法律、法规的规定给予赔偿。”根据有关司法解释，这种赔偿并不是民警个人行为，而是国家行为，由其所属的公安机关承担。可知，本题中应由实施抓捕的警察所属的公安机关承担；C项错误：犯罪嫌疑人在逃脱抓捕时损坏公民财物，属于纯粹的民事侵权行为，应当按照《侵权责任法》和《民法通则》的有关规定，受害者可与该嫌疑人商议赔偿问题，商议不成的，可以提起民事诉讼，要求赔偿。可知，餐馆的损失不一定由犯罪嫌疑人赔偿。故正确答案为D。", "tag": "法律常识"},
{"id": "law-72", "q": "A 县某酒厂酿造的“仙液”系列白酒深为当地人喜爱，A 县政府办公室发文指定该酒为“接待用酒”，要求各机关、企事业单位、社会团体在业务用餐时，饮酒应以“仙液”系列为主，同时，酒厂公开承诺用餐者凭市内各酒楼出具的证明，可以取得消费100 元返还10 元的奖励。关于此事，下列说法错误的是：", "options": ["A 县政府办公室的行为属于限制竞争行为", "酒厂的做法，尚未构成商业贿赂行为", "上级机关可以责令A 县政府改正错误", "监督检查部门可以没收酒厂的违法所得，并处以罚款"], "a": 3, "e": "【D】《反不正当竞争法》第七条规定：“政府及其所属部门不得滥用行政权力，限定他人购买其指定的经营者的商品，限制其他经营者正当的经营活动。政府及其所属部门不得滥用行政权力，限制外地商品进入本地市场，或者本地商品流向外地市场。”第八条规定：“经营者不得采用财物或者其他手段进行贿赂以销售或者购买商品。在账外暗中给予对方单位或者个人回扣的，以行贿论处；对方单位或者个人在账外暗中收受回扣的，以受贿论处。经营者销售或者购买商品，可以以明示方式给对方折扣，可以给中间人佣金。经营者给对方折扣、给中间人佣金的，必须如实入账。接受折扣、佣金的经营者必须如实入账。”第三十条规定：“政府及其所属部门违反本法第七条规定，限定他人购买其指定的经营者的商品、限制其他经营者正当的经营活动，或者限制商品在地区之间正常流通的，由上级机关责令其改正；情节严重的，由同级或者上级机关对直接责任人员给予行政处分。被指定的经营者借此销售质次价高商品或者滥收费用的，监督检查部门应当没收违法所得，可以根据情节处以违法所得一倍以上三倍以下的罚款。”D项错误：本题中，该酒厂的“仙液”系列白酒虽然被指定为“接待用酒”，但并没有出现借此销售质次价高商品或者滥收费用的情形，监督检查部门无权没收其违法所得。A项正确：根据《反不正当竞争法》第七条的规定，A县政府办公室指定该酒为“接待用酒”，符合第七条规定的情形，其行为属于限制竞争行为。B项正确：根据《反不正当竞争法》第八条的规定，酒厂以公开承诺的方式给消费者优惠，不属于商业贿赂行为。C项正确：根据《反不正当竞争法》第三十条的规定，根据对于A县政府的行为，上级机关可以责令其改正。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-73", "q": "下列证明与申请部门对应错误的是：", "options": ["家庭收入情况证明——公证机关", "存单名字错误证明——公安机关", "婚姻关系存在证明——民政部门", "家庭成员失踪证明——人民法院"], "a": 1, "e": "【B】本题作答依据为2015年公安部发布的《18个不该由公安机关出具的证明》。A项正确，家庭收入情况不属于派出所工作业务范畴，派出所不知情。因此，派出所不予出具证明，应到公证机关进行公证。B项错误，因非公安机关原因将姓名填写错误，如：银行存单、保险单、学校、单位等档案中姓名同音不同字，需要证明是同一人的。造成错误的责任主体不是公安派出所，而且派出所也不知情，所以不应出具证明。公民应当到公证机关，由公证机关来公证证明。C项正确，民政部门是婚姻登记机关，婚姻状况属于民政部门的责任范畴，公民应到民政部门开取证明。派出所不予出具证明。D项正确，宣告公民失踪是人民法院受案范畴，不是派出所的责任范畴，派出所无权证明人员是否失踪，应向人民法院申请出具证明。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-74", "q": "国家建立健全突发事件预警制度危害程度分为一级、二级、三级和四级，其中三级的标示颜色是（）。", "options": ["蓝色", "白色", "红色", "黄色"], "a": 3, "e": "【D】2007年11月1日起实施的《突发事件应对法》第四十二条规定：“国家建立健全突发事件预警制度。”可以预警的自然灾害、事故灾难和公共卫生事件的预警级别，按照突发事件发生的紧急程度、发展势态和可能造成的危害程度分为一级、二级、三级和四级，分别用红色、橙色、黄色和蓝色标示，一级为最高级别。预警级别的划分标准由国务院或者国务院确定的部门制定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-75", "q": "下列广告行为，不符合法律规定的是（）。", "options": ["在互联网上发布内容符合规定的农药广告", "在广播电台和电视台发布非品牌白酒广告", "在小学教材的封底上发布环保公益广告", "广告代言人为其未使用过的化妆品作广告"], "a": 3, "e": "【D】D项错误，我国广告法第38条规定：广告代言人在广告中对商品、服务做推荐、证明，应当依据事实，符合本法和有关法律、行政法规规定，并不得为其未使用过的商品或者未接受过的服务做推荐、证明。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-76", "q": "李强买房首付不够，向好友刘雷借了三万元，由于关系非常好，双方没有约定还款期限和利息。依照法律规定：", "options": ["刘雷无权要求李强支付利息，但可以要求李强立即还款", "刘雷无权要求李强支付利息，但可以要求李强适时还款", "刘雷有权要求李强按银行同期存款利率支付利息", "刘雷有权要求李强按银行同期贷款利率支付利息"], "a": 1, "e": "【B】1999年3月15日第九届全国人民代表大会第二次会议通过的《中华人民共和国合同法》规定：借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，协议不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。借款合同采用书面形式，但自然人之间借款另有约定的除外。自然人之间的借款合同，自贷款人提供借款时生效。自然人之间的借款合同对支付利息没有约定或者约定不明确的，视为不支付利息。自然人之间的借款合同约定支付利息的，借款的利率不得违反国家有关限制借款利率的规定。公民之间的无息借款，有约定偿还期限而借款人不按期偿还，或者未约定偿还期限但经出借人催告后，借款人仍不偿还的，出借人要求借款人偿付逾期利息，应当予以准许。故正确答案为B。", "tag": "法律常识"},
{"id": "law-77", "q": "某中学附近有家黑网吧，老板经常以打折的方式引诱未成年的中学生逃学进入网吧玩游戏。网吧老板的行为违反了：", "options": ["《中华人民共和国宪法》中有关公民受教育权的规定", "《中华人民共和国义务教育法》中有关适龄儿童入学的规定", "《中华人民共和国未成年人保护法》中有关学校保护的规定", "《中华人民共和国未成年人保护法》中有关社会保护的规定"], "a": 3, "e": "【D】A项：受教育权是一项基本人权，受教育权是中国公民所享有的并由国家保障实现的接受教育的权利，是宪法赋予的一项基本权利，也是公民享受其他文化教育的前提和基础。本题目并未涉及受教育权，排除；B项：2006年6月由中华人民共和国全国人民代表大会常务委员会修订通过的《中华人民共和国义务教育法》第十一条第一款规定：“凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区的儿童，可以推迟到七周岁。”义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育，是国家必须予以保障的公益性事业。本题目并未涉及适龄儿童的入学，排除；C项：学校保护是指有关的学校、幼儿园及其他教育机构依照我国《未成年人保护法》及其他有关法律、法规，对未成年学生和幼儿园儿童实施的专门保护。学校保护是未成年人保护的重要方面。本题目问的是网吧老板而不是学校违反了什么法律，排除；D项：社会保护是指各社会团体、企事业组织和其他组织及公民，对未成年人实施的保护。其主要内容是：保护未成年人的安全与健康、保护未成年人的荣誉权、保护未成年人的智力成果权、保护有特殊天赋和突出成就的未成年人、公共场所优惠开放等。我国《未成年人保护法》关于社会保护中第三十六条第一、二款规定：“中小学校园周边不得设置营业性歌舞娱乐场所、互联网上网服务营业场所等不适宜未成年人活动的场所。营业性歌舞娱乐场所、互联网上网服务营业场所等不适宜未成年人活动的场所，不得允许未成年人进入，经营者应当在显著位置设置未成年人禁入标志；对难以判明是否已成年的，应当要求其出示身份证件。”当选。故正确答案为D。", "tag": "法律常识"},
{"id": "law-78", "q": "下列关于环境治理的说法，错误的是：", "options": ["某造纸厂无证排污，被责令停止却拒不执行，公安机关可对企业主管处以拘留", "某工厂属重点排污单位，没如实公开环境信息，县政府环保部门应责令公开", "某高校未提交迁建项目环评文件而擅自开工建设，环保监管部门可责令停止", "某农药生产企业生产国家禁止生产的农药，主管人员须承担一定的刑事责任"], "a": 3, "e": "【D】《环境保护法》第六十三条规定：“企业事业单位和其他生产经营者有下列行为之一，尚不构成犯罪的，除依照有关法律法规规定予以处罚外，由县级以上人民政府环境保护主管部门或者其他有关部门将案件移送公安机关，对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留：……（四）生产、使用国家明令禁止生产、使用的农药，被责令改正，拒不改正的。”由此可知，D项中该农药生产企业的主管人员需承担一定的刑事责任说法有误。A、B、C项的叙述均符合环境治理的相关法律法规。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-79", "q": "下列企业的行为，违背法律规定的是：", "options": ["某印染企业排污前依照法律规定上缴环境保护税，不缴排污费", "某石化企业取得排污许可证，只按照许可证的要求排放污染物", "某橡胶厂排污导致突发环境事件，未通报可能受到危害的居民", "某家禽屠宰场属一般排污企业，未向社会公开其污染物的名称"], "a": 2, "e": "【C】我国《环境保护法》第四十七条第三款规定：“企业事业单位应当按照国家有关规定制定突发环境事件应急预案，报环境保护主管部门和有关部门备案。在发生或者可能发生突发环境事件时，企业事业单位应当立即采取措施处理，及时通报可能受到危害的单位和居民，并向环境保护主管部门和有关部门报告。”C项某橡胶厂未通报突发环境事件的做法违反该条规定。A、B、D三项中，企业的行为均符合法律规定。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-80", "q": "关于法律援助，下列说法不正确的是：", "options": ["需要援助者应向法律援助机构提交书面申请", "法律援助的形式为诉讼法律服务，不包括非诉讼法律服务", "法院对受援对象减免案件受理费及其他诉讼费"], "a": 1, "e": "【B】中国法律援助有以下特征：（1）法律援助是国家的责任、政府的责任，由政府设立援助机构实施。它体现了国家和政府对公民的义务。（2）法律援助是法律化、制度化的行为，是国家社会保障制度中的重要组成部分。（3）受援对象为经济困难者、残疾者、弱者，或者经人民法院指定的特殊对象。（4）法律援助机构对受援对象减免法律服务费，法院对受援对象减、免案件受理费及其他诉讼费用。（5）法律援助的形式，既包括诉讼法律服务，也包括非诉讼法律服务。主要采取以下形式：刑事辩护和刑事代理；民事、行政诉讼代理；非诉讼法律事务代理；公证证明。由分析可看出，A、C、D三项说法均正确，B项说法错误。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-81", "q": "下列行为不违反国家规定的是：", "options": ["农民甲某外出打工，将其承包的耕地租给同村乙某用于挖塘养鱼", "在承包期内，丙某将所承包的林地改作耕地，种植蔬菜和中药材", "牧民丁某的草场在承包期内发生沙化，遂与人合作进行采砂作业", "某地为发展渔业，将“围湖造田”围垦形成的耕地重新开挖成湖"], "a": 3, "e": "【D】退田还湖是将围垦湖边或湖内淤地改造成的农田恢复为湖面的工程措施。内陆湖泊具有调节江河流量的作用，有利于生态平衡。但是，20世纪70年代以来，中国各湖泊的围湖造田势头愈来愈大，已经对湖泊的调节能力产生了重大负面影响。1998年长江特大洪水期间，作为原来对长江洪水具有调节能力的洞庭湖、鄱阳湖和洪湖等湖泊，都因围湖造田而失去调节能力。《中华人民共和国水法》和《中华人民共和国河道管理条例》都规定，不能盲目围垦，应逐步退田还湖。这是中国自从春秋战国以来，第一次从围湖造田，自觉主动地转变为大规模的退田还湖，给洪水让路。D项正确。故正确答案为D。", "tag": "法律常识"},
{"id": "law-82", "q": "下列说法错误的是：", "options": ["甲某盗取其他网游玩家账号下的一批游戏装备，已涉嫌触犯刑法", "乙某在网络游戏中向网游玩家出售虚拟货币，其所得属非法利益", "丙某在某网游上的账号积分被网游公司清零，丙某对此享有诉权", "丁某网游账号内虚拟货币丢失，丁某可向法院主张追回虚拟货币"], "a": 1, "e": "【B】A项正确，甲构成盗窃罪，涉嫌触犯刑法。B项错误，《关于加强网络游戏虚拟货币管理工作的通知》：“网络游戏虚拟货币是指由网络游戏运营企业发行，游戏用户使用法定货币按一定比例直接或间接购买，存在于游戏程序之外，以电磁记录方式存储于网络游戏运营企业提供的服务器内，并以特定数字单位表现的一种虚拟兑换工具。网络游戏虚拟货币用于兑换发行企业所提供的指定范围、指定时间内的网络游戏服务……”明确其合法性。C项正确，网游公司构成违约，丙对此享有诉权。D项正确，虚拟货币是一种商品，是法律意义上的物，可以向法院主张追回。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-83", "q": "下列保健食品广告用语符合国家有关规定的是：", "options": ["某双岐软胶囊广告：快速治疗慢性腹泻，根除结肠炎", "某三七袋泡茶广告：坚持服用，治疗高血压、脂肪肝", "某灵芝孢子油胶囊广告：高效抗肿瘤，呵护肿瘤患者", "某螺旋藻片广告：增强免疫力，调理肠胃，调节血脂"], "a": 3, "e": "【D】《保健食品管理办法》第二十三条规定：“保健食品的标签、说明书和广告内容必须真实,符合其产品质量要求，不得有暗示可使疾病痊愈的宣传。”A项中的“快速治疗”、B项中的“治疗”、C项中的“高效抗”等字眼，均违反此规定。故正确答案为D。", "tag": "法律常识"},
{"id": "law-84", "q": "下列选项中，免征个人所得税的是：", "options": ["张某的存款利息", "王某的保险赔款", "李某的稿酬所得", "赵某的房屋出租所得"], "a": 1, "e": "【B】根据《个人所得税法》第四条规定：“下列各项个人所得，免征个人所得税：(一)省级人民政府、国务院部委和中国人民解放军军以上单位，以及外国组织、国际组织颁发的科学、教育、技术、文化、卫生、体育、环境保护等方面的奖金;(二)国债和国家发行的金融债券利息;(三)按照国家统一规定发给的补贴、津贴;(四)福利费、抚恤金、救济金;(五)保险赔款;(六)军人的转业费、复员费、退役金;(七)按照国家统一规定发给干部、职工的安家费、退职费、基本养老金或者退休费、离休费、离休生活补助费;(八)依照有关法律规定应予免税的各国驻华使馆、领事馆的外交代表、领事官员和其他人员的所得;(九)中国政府参加的国际公约、签订的协议中规定免税的所得;(十)国务院规定的其他免税所得。前款第十项免税规定，由国务院报全国人民代表大会常务委员会备案。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-85", "q": "下列关系中，不属于我国法定人民团体的是：", "options": ["陕西省工商联", "陕西省作家协会", "陕西省妇女联合会", "西安某大学的学生会"], "a": 3, "e": "【D】中共中央党委序列包含中国人民政治协商会议（全国政协）和全国人民代表大会（全国人大）。工商联和妇联均属于中国人民政治协商会议（全国政协）组成界别；作协是经国务院批准免于登记的社会团体，属于全国人民代表大会（全国人大）组成界别。A、B、C三项均为法律承认的人民团体。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-86", "q": "张某受王某的委托，为王某画了一幅肖像，双方未就这幅画的版权归属作出约定。王某去世后，其继承人王一将这幅画卖给了李某，李某未经任何人同意，将这幅画复制出售。下列关于李某做法的认定中，表达正确的是：", "options": ["李某侵犯了张某的著作权", "李某侵犯了王某的著作权", "李某侵犯了王一的著作权", "李某的行为是合法行使权利的行为"], "a": 0, "e": "【A】根据《著作权法》第十七条规定：“受委托创作的作品，著作权的归属由委托人和受托人通过合同约定。合同未作明确约定或者没有订立合同的，著作权属于受托人。”本案例中双方并未就版权归属作出约定，所以著作权应属于受托人张某。而著作权包含复制权和发行权等多项权利，李某未经张某的同意，擅自复制出售，显然侵犯了张某的复制权和发行权，即侵犯了张某的著作权。故正确答案为A。", "tag": "法律常识"},
{"id": "law-87", "q": "安全生产法规定，在生产经营单位中，对安全生产工作负全面责任的是：", "options": ["生产经营单位中负责安全生产工作的分管负责人", "所在行政区域地方政府的上级政府安全生产管理部门", "所在行政区地方政府的安全生产管理部门", "生产经营单位的主要负责人"], "a": 3, "e": "【D】A项错误：《中华人民共和国安全生产法》第五条规定：“生产经营单位的主要负责人对本单位的安全生产工作全面负责。”因此，对本单位的安全生产工作全面负责的是生产经营单位的主要负责人，并非负责安全生产工作的分管负责人，排除。B、C两项错误：《中华人民共和国安全生产法》第九条规定：“国务院安全生产监督管理部门依照本法，对全国安全生产工作实施综合监督管理；县级以上地方各级人民政府安全生产监督管理部门依照本法，对本行政区域内安全生产工作实施综合监督管理。”因此，政府安全生产管理部门是负责实施综合监督管理，排除。D项正确：《中华人民共和国安全生产法》第五条规定：“生产经营单位的主要负责人对本单位的安全生产工作全面负责。”当选。故正确答案为D。", "tag": "法律常识"},
{"id": "law-88", "q": "某化工厂将废水直接排入河道，流入张某的鱼塘，造成绝大部分鱼死亡。该厂承认其侵权，但不能接受张某提出的赔偿数额。对此，下列哪一表述是不正确的：", "options": ["张某请求损害赔偿的诉讼时效为3 年", "张某可以请求环境保护行政主管部门处理", "张某对环境保护行政主管部门的处理决定不服的，可以向法院起诉", "张某必须先经过环境保护行政主管部门处理，不能直接向法院起诉"], "a": 3, "e": "【D】本题考查《环境保护法》。A项正确，《环境保护法》第四十二条规定：“因环境污染损害赔偿提起诉讼的时效期为三年，从当事人知道或者应当知道受到污染损害时起计算”；B项正确；C项正确，根据第四十一条的规定可知；D项错误，《环境保护法》第四十一条规定：“造成环境污染危害的，有责任排除危害，并对直接受到损害的单位或者个人赔偿损失。赔偿责任和赔偿金额的纠纷，可以根据当事人的请求，由环境保护行政主管部门或者其他依照法律规定行使环境监督管理权的部门处理；当事人对处理决定不服的，可以向人民法院起诉。当事人也可以直接向人民法院起诉”。结合本题情况，张某可以请求环境保护行政主管部门处理，也可直接向人民法院起诉。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-89", "q": "下列表述不符合国家政策规定的是：", "options": ["农民工可以申请参加社区居民委员会选举", "农民工计划生育管理费由输出地政府承担", "农民工可以回原籍参加新农村合作医疗", "做出突出贡献的农民工可以优先准予落户"], "a": 1, "e": "【B】B项错误，根据《流动人口计划生育工作条例》第四条的规定：“流动人口计划生育工作由流动人口户籍所在地和现居住地的人民政府共同负责，以现居住地人民政府为主，户籍所在地人民政府予以配合。”所以，计划生育管理费应纳入现居住地，即由输入地的地方财政承担，输出地政府只是予以配合。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-90", "q": "关于我国兵役制度，下列表述错误的是：", "options": ["我国实行义务兵与志愿兵相结合、民兵与预备役相结合的兵役制度", "普通高等学校毕业生征集服现役的年龄可以放宽至二十四周岁", "义务兵服现役的期限为三年，士官服现役的期限一般不超过三十年", "士兵预备役的年龄为十八周岁至三十五周岁，根据需要可适当延长"], "a": 2, "e": "【C】A项正确，根据《兵役法》第二条的规定，中华人民共和国实行义务兵与志愿兵相结合、民兵与预备役相结合的兵役制度；B项正确，根据《兵役法》第十二条的规定，每年十二月三十一日以前年满十八周岁的男性公民，应当被征集服现役。当年未被征集的，在二十二周岁以前仍可以被征集服现役，普通高等学校毕业生的征集年龄可以放宽至二十四周岁；C项错误，根据《兵役法》第十九条的规定，义务兵服现役的期限为二年；D项正确，根据《兵役法》第二十四条的规定，士兵预备役的年龄，为十八周岁至三十五周岁，根据需要可以适当延长。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-91", "q": "某村民委员会下列做法符合法律规定的是：", "options": ["村委会规定村里的荒山不得以招标、拍卖等形式实行承包经营", "村民乙外出经商，村委会不同意乙在承包期内放弃承包权", "村民丙全家转为城市户口，村委会取消丙承包期内的承包权", "村委会规定凡是嫁往外地的本村妇女，承包地应一律归还村委会"], "a": 2, "e": "【C】本题考查法律常识。A项错误，我国《农村土地承包法》第三条第二款规定，“不宜采取家庭承包方式的荒山、荒沟、荒丘、荒滩等农村土地，可以采取招标、拍卖、公开协商等方式承包”，所以村委会无权禁止家庭承包经营以外的其他方式的承包。B项错误，《农村土地承包法》第二十九条规定，“承包期内，承包方可以自愿将承包地交回发包方”，所以乙有权在承包期内放弃承包权。C项正确，《农村土地承包法》第二十六条规定，“承包期内，承包方全家迁入设区的市，转为非农业户口的，应当将承包的耕地和草地交回发包方。承包方不交回的，发包方可以收回承包的耕地和草地”。D项错误，《农村土地承包法》第三十条规定，“承包期内，妇女结婚，在新居住地未取得承包地的，发包方不得收回其原承包地；妇女离婚或者丧偶，仍在原居住地生活或者不在原居住地生活但在新居住地未取得承包地的，发包方不得收回其原承包地”。故正确答案为C。", "tag": "法律常识"},
{"id": "law-92", "q": "关于未成年人保护法，下列说法正确的是：", "options": ["未成年人是指未满二十周岁的公民", "十四周岁以上不满十六周岁的未成年人犯罪的案件不可公开审理", "该法是义务教育法的制定依据", "该法由全国人大政协会议通过并颁布"], "a": 1, "e": "【B】A、D选项错误，根据《未成年人保护法》第2条规定：本法所称未成年人是指未满十八周岁的公民。此法在", "tag": "法律常识"},
{"id": "law-93", "q": "第十一届全国人民代表大会常务委员会第二十三次会议表决通过了《关于修改居民身份证法的决定》，在居民身份证登记项目中增加了（）信息。", "options": ["家庭", "指纹", "婚姻", "民族"], "a": 1, "e": "【B】第十一届全国人民代表大会常务委员会第二十三次会议决定将《中华人民共和国居民身份证法》第3条第1款修改为：“居民身份证登记的项目包括：姓名、性别、民族、出生日期、常住户口所在地住址、公民身份号码、本人相片、指纹信息、证件的有效期和签发机关。”第3条增加1款，作为第3款：“公民申请领取、换领、补领居民身份证，应当登记指纹信息。”即在居民身份证登记项目中增加了指纹信息。故正确答案为B。", "tag": "法律常识"},
{"id": "law-94", "q": "成立股份有限公司，向公司登记机关登记的应该是：", "options": ["全体股东指定的代表", "全体股东指定的法律代理人", "公司董事长", "公司总经理"], "a": 0, "e": "【A】根据《公司法》第二十九条，成立股份有限公司，股东认足公司章程规定的出资后，由全体股东指定的代表或者共同委托的代理人向公司登记机关报送公司登记申请书、公司章程等文件，申请设立登记。故正确答案为A。本题相关知识点：股份有限公司设董事会，其成员为五人至十九人。董事会设董事长一人，可以设副董事长。董事长和副董事长由董事会以全体董事的过半数选举产生。", "tag": "法律常识"},
{"id": "law-95", "q": "张某因故意杀人罪被判处死刑，执行完毕后，其父急恨交加导致旧病复发而亡。张某有妻、子、女、兄、弟。张父的遗产应由（）继承。", "options": ["张某、妻、子、女、兄、弟", "妻、子、女、兄、弟", "子、女、兄、弟", "妻、兄、弟"], "a": 2, "e": "【C】根据我国《继承法》的规定，丧偶儿媳对公、婆，丧偶女婿对岳父、岳母，尽了主要赡养义务的，作为第一顺序继承人。故张妻不能作为继承人。张某的子女可以通过代位继承的方式继承张父的财产，张某的兄弟可以通过法定继承的方式继承其父的财产。故正确答案为C。", "tag": "法律常识"},
{"id": "law-96", "q": "下列不适用产品质量法规定的产品是：", "options": ["商场销售的燃气热水器", "房地产公司开发的商品房", "张某手工制售的仿古家具", "外企在我国境内销售的手机"], "a": 1, "e": "【B】关于产品质量法的适用范围，《产品质量法》第二条规定：在中华人民共和国境内从事产品生产、销售活动，必须遵守本法。本法所称产品是指经过加工、制作，用于销售的产品。建设工程不适用本法规定；但是，建设工程使用的建筑材料、建筑构配件和设备，属于前款规定的产品范围的，适用本法规定。B项商品房属于建筑工程，不适用产品质量法。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-97", "q": "根据《中华人民共和国禁毒法》的规定，下列吸毒成瘾的人适用强制隔离戒毒的是：", "options": ["怀孕的妇女", "年龄超过60 周岁的", "正在哺乳自己不满1 周岁婴儿的妇女", "不满16 周岁的未成年人"], "a": 1, "e": "【B】《禁毒法》第三十九条规定：“怀孕或者正在哺乳自己不满一周岁婴儿的妇女吸毒成瘾的，不适用强制隔离戒毒。不满十六周岁的未成年人吸毒成瘾的，可以不适用强制隔离戒毒。”因此排除ACD，适用强制隔离戒毒的是B项。故正确答案为B。", "tag": "法律常识"},
{"id": "law-98", "q": "中华人民共和国成立后，中央人民政府颁布的第一部法律是：", "options": ["《宪法》", "《刑事诉讼法》", "《婚姻法》", "《劳动法》"], "a": 2, "e": "【C】中华人民共和国第一部《婚姻法》是1948年华北解放区妇女工作会议后，由中央妇委起草，经过多次讨论和修改，于1950年5月1日颁布实施的法律。它也成为了中央政府在建国后颁布的第一部法律。第一部《宪法》是在1949年颁布的《共同纲领》基础上，几经修改在1954年颁布的，被称为“五四宪法”。《刑事诉讼法》在1979年通过，《劳动法》在1994年通过，所以排除A、B、D三项。故正确答案为C。", "tag": "法律常识"},
{"id": "law-99", "q": "下列关于《中华人民共和国外商投资法》的表述，错误的是（）。", "options": ["本法从2020 年1 月1 日起施行", "国家对外商投资实行准入前国民待遇加负面清单管理制度", "旨在进一步扩大对外开放，积极促进外商投资", "地方政府因国家利益、公共利益需要改变政策承诺和合同约定的，不需要对外商企业进行补偿"], "a": 3, "e": "【D】本题考查法律常识。A项正确，《中华人民共和国外商投资法》第四十二条规定：“本法自2020年1月1日起施行。《中华人民共和国中外合资经营企业法》、《中华人民共和国外资企业法》、《中华人民共和国中外合作经营企业法》同时废止。”B项正确，《中华人民共和国外商投资法》第四条规定：“国家对外商投资实行准入前国民待遇加负面清单管理制度。前款所称准入前国民待遇，是指在投资准入阶段给予外国投资者及其投资不低于本国投资者及其投资的待遇；所称负面清单，是指国家规定在特定领域对外商投资实施的准入特别管理措施。国家对负面清单之外的外商投资，给予国民待遇。”C项正确，《中华人民共和国外商投资法》第一条规定：“为了进一步扩大对外开放，积极促进外商投资，保护外商投资合法权益，规范外商投资管理，推动形成全面开放新格局，促进社会主义市场经济健康发展，根据宪法，制定本法。”D项错误，《中华人民共和国外商投资法》第二十五条规定：“地方各级人民政府及其有关部门应当履行向外国投资者、外商投资企业依法作出的政策承诺以及依法订立的各类合同。因国家利益、社会公共利益需要改变政策承诺、合同约定的，应当依照法定权限和程序进行，并依法对外国投资者、外商投资企业因此受到的损失予以补偿。”本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-100", "q": "关于2018 年10 月起实施的新法新规，下列说法中不准确的一项是（）。", "options": ["个人所得税“起征点”从每月3500 元上调至5000 元", "电子商务经营者搭售商品或者服务不得将搭售商品或者服务作为默认同意的选项", "《彩票管理条例实施细则》规定经营者可利用互联网自行销售福利彩票", "公共人才机构提供人才政策法规咨询等服务不得收费"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，新个税法虽然自2019年1月1日实施，但部分减税红利却从10月1日开始施行。根据财政部、国家税务总局发布的《关于2018年第四季度个人所得税减除费用和税率适用问题的通知》，2018年10月1日至12月31日期间，纳税人实际取得的工资、薪金所得，减除费用（通常所说的“起征点”）统一按照5000元/月执行，并执行新的税率表。B项正确，自2019年1月1日起施行的《电子商务法》第十九条规定：“电子商务经营者搭售商品或者服务，应当以显著方式提请消费者注意，不得将搭售商品或者服务作为默认同意的选项”。C项错误，2018年10月1日起施行的新修改的《彩票管理条例实施细则》规定：“第七条条例第五条所称非法彩票，是指违反条例规定以任何方式发行、销售以下形式的彩票：（五）擅自利用互联网销售的福利彩票、体育彩票”。D项正确，自2018年10月1日起，《人力资源市场暂行条例》施行，其中《条例》第十五条规定：“公共人力资源服务机构提供下列服务，不得收费：（三）就业创业和人才政策法规咨询”。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-101", "q": "根据我国刑事诉讼法的规定，下列证据应当予以直接排除的是：", "options": ["采用刑讯逼供的方法收集的犯罪嫌疑人的供述", "收集犯罪嫌疑人贪污所得现金不符合法定程序的", "收集合同诈骗罪涉案支票不符合法定程序，可能严重影响司法公正的", "收集盗窃自行车不符合法定程序，不会影响司法公正，但无法作出合理解释的"], "a": 0, "e": ".【A】根据《刑事诉讼法》第五十四条：采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除。收集物证、书证不符合法定程序，可能严重影响司法公正的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，对该证据应当予以排除。A项正确：采用刑讯逼供犯罪嫌疑人的供述，应当予以直接排除。B项的“现金”、C项的“支票”、D项的“自行车”都属于“物证”，需要看能否“补正或者作出合理解释”，不能的才要排除，而不能直接排除，故B、C、D选项错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-102", "q": "某毒品案件中的重要证人小张因在诉讼中作证而导致其人身安全面临危险，人民法院、人民检察院和公安机关应当采取的保护措施不包括：", "options": ["免于其出庭作证", "不公开其真实姓名", "禁止特定人员与其接触", "对其住宅采取专门性保护措施"], "a": 0, "e": ".【A】我国《刑事诉讼法》第六十二条规定：“对于危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、毒品犯罪等案件，证人、鉴定人、被害人因在诉讼中作证，本人或者其近亲属的人身安全面临危险的，人民法院、人民检察院和公安机关应当采取以下一项或者多项保护措施：（一）不公开真实姓名、住址和工作单位等个人信息；（二）采取不暴露外貌、真实声音等出庭作证措施；（三）禁止特定的人员接触证人、鉴定人、被害人及其近亲属；（四）对人身和住宅采取专门性保护措施；（五）其他必要的保护措施。”本题中，A项免于出庭作证不属于人民法院、人民检察院和公安机关应当对小张采取的保护措施。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-103", "q": "痴情女子小雯为阻止男友小马与其分手，邀人将小马打成重伤二级，以下说法正确的是：", "options": ["小雯目的正当，手段不妥，可不承担刑事责任", "小雯可选择承担民事赔偿责任或承担刑事责任", "小雯如获得小马谅解，可适用当事人和解程序", "小雯即使获得小马的谅解，也应承担刑事责任"], "a": 3, "e": ".【D】本题考查法律常识。一、关于刑事责任。根据《中华人民共和国刑法》第二百三十四条第一、二款规定：“故意伤害他人身体的，处三年以下有期徒刑、拘役或者管制。犯前款罪，致人重伤的，处三年以上十年以下有期徒刑。”二、关于和解程序。根据《中华人民共和国刑事诉讼法》第二百八十八条第一款规定：“下列公诉案件，犯罪嫌疑人、被告人真诚悔罪，通过向被害人赔偿损失、赔礼道歉等方式获得被害人谅解，被害人自愿和解的，双方当事人可以和解：（一）因民间纠纷引起，涉嫌刑法分则第四章、第五章规定的犯罪案件，可能判处三年有期徒刑以下刑罚的；（二）除渎职犯罪以外的可能判处七年有期徒刑以下刑罚的过失犯罪案件。”A项错误，小雯将男友打成重伤，涉嫌故意伤害罪，应当承担刑事责任。B项错误，根据《中华人民共和国刑事诉讼法》第一百零一条规定：“被害人由于被告人的犯罪行为而遭受物质损失的，在刑事诉讼过程中，有权提起附带民事诉讼”小雯造成了男友身体上的严重伤害，除了应负刑事责任还应承担民事赔偿责任。C项错误，小雯将男友打成重伤，应承担三年以上十年以下有期徒刑，不符合和解程序中“三年有期徒刑以下刑罚的”之规定；小雯是故意伤害的行为也不符合“过失犯罪”之规定，故不适用和解程序。D项正确，小雯的行为不适用和解程序，即使获得小马的谅解，也应承担刑事责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-104", "q": "以下案件不是由人民检察院立案侦查的是：", "options": ["某市公安局警察利用职权非法搜查案", "某法官徇私枉法案", "某公司骗取出口退税案", "王某告公安机关刑讯逼供案"], "a": 2, "e": ".【C】根据《刑事诉讼法》第十九条规定：刑事案件的侦查由公安机关进行，法律另有规定的除外。人民检察院在对诉讼活动实行法律监督中发现的司法工作人员利用职权实施的非法拘禁、刑讯逼供、非法搜查等侵犯公民权利、损害司法公正的犯罪，可以由人民检察院立案侦查。对于公安机关管辖的国家机关工作人员利用职权实施的重大犯罪案件，需要由人民检察院直接受理的时候，经省级以上人民检察院决定，可以由人民检察院立案侦查。自诉案件，由人民法院直接受理。ABD正确，非法搜查，徇私枉法，刑讯逼供等案件，可以由人民检察院立案侦查。C项错误，骗取出口退税由公安机关立案侦查。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-105", "q": "“套路贷”是假借民间借贷之名，非法占有被害人财物的违法犯罪行为，是扫黑除恶专项斗争的重点打击对象。下列关于“套路贷”的说法正确的是：", "options": ["“套路贷”犯罪案件可由犯罪行为发生地、结果发生地及犯罪嫌疑人居住地公安机关侦查", "因法律规定民间借贷最高年利率为", "因“套路贷”属于非法行为，追债时一般不会采用仲裁、诉讼方式", "我国刑法设置有专门针对“套路贷”的罪名"], "a": 0, "e": ".【A】本题考查法律常识。根据最高人民法院、最高人民检察院、公安部、司法部《关于办理“套路贷”刑事案件若干问题的意见》：1.“套路贷”，是对以非法占有为目的，假借民间借贷之名，诱使或迫使被害人签订“借贷”或变相“借贷”“抵押”“担保”等相关协议，通过虚增借贷金额、恶意制造违约、肆意认定违约、毁匿还款证据等方式形成虚假债权债务，并借助诉讼、仲裁、公证或者采用暴力、威胁以及其他手段非法占有被害人财物的相关违法犯罪活动的概括性称谓。A项正确，根据最高人民法院、最高人民检察院、公安部、司法部《关于办理“套路贷”刑事案件若干问题的意见》：", "tag": "法律常识"},
{"id": "law-106", "q": "甲乘坐公交车时因到站未停与司机发生争执，一怒之下抢夺正在行驶的公交车方向盘，致公交车失控撞到路边电线杆，乘客及行人受伤、公交车严重受损。甲的行为构成：", "options": ["以危险方法危害公共安全罪", "交通肇事罪", "寻衅滋事罪", "危险驾驶罪"], "a": 0, "e": ".【A】本题考查法律常识。A项正确，根据《刑法》第一百一十四条、第一百一十五条的规定，以危险方法危害公共安全罪是指故意使用放火、决水、爆炸、投放危险物质以外的危险方法危害公共安全的行为。根据最高人民检察院的指导意见，乘客在公共交通工具行驶的过程中，抢夺方向盘、变速杆等操控装置，殴打、拉拽驾驶人员，或者有其他妨害安全驾驶行为，危害公共安全，无论是否造成严重后果，均应以以危险方法危害公共安全罪定罪处罚。甲在公交车行驶途中抢夺方向盘，危害不特定多人的生命、健康和公私财产的安全，并造成了严重后果，甲的行为构成以危险方法危害公共安全罪。B项错误，根据《刑法》第一百三十三条的规定，交通肇事罪是指违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的行为。交通肇事罪主观方面是过失，而题中甲抢夺方向盘时的主观方面是故意，显然不构成交通肇事罪。C项错误，根据《刑法》第二百九十三条第一款规定：“有下列寻衅滋事行为之一，破坏社会秩序的，处五年以下有期徒刑、拘役或者管制：（一）随意殴打他人，情节恶劣的；（二）追逐、拦截、辱骂、恐吓他人，情节恶劣的；（三）强拿硬要或者任意损毁、占用公私财物，情节严重的；（四）在公共场所起哄闹事，造成公共场所秩序严重混乱的。”寻衅滋事罪侵犯的客体是社会公共秩序，而题中甲的行为危害不特定多人的生命、健康和公私财产的安全，因此不构成寻衅滋事罪。D项错误，根据《刑法》第一百三十三条之一第一款规定：“在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金：（一）追逐竞驶，情节恶劣的；（二）醉酒驾驶机动车的；（三）从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶的；（四）违反危险化学品安全管理规定运输危险化学品，危及公共安全的。”甲抢夺方向盘的行为不符合危险驾驶罪的情形。故正确答案为A。", "tag": "法律常识"},
{"id": "law-107", "q": "下列犯罪行为应以盗窃罪论处的是：", "options": ["甲窃得价值5000 元的手机一部，被发现后持械抗拒抓捕", "乙窃得同事的信用卡一张，并用其消费10000 元", "丙在火车上捡到价值50000 元的提包一只，经失主催要后拒不归还", "丁为某私营公司的销售主管，在销售过程中私自将价值50000 元的产品据为己有"], "a": 1, "e": ".【B】本题主要考查法律常识。A项错误，根据《中华人民共和国刑法》第二百六十九条规定：“犯盗窃、诈骗、抢夺罪，为窝藏赃物、抗拒抓捕或者毁灭罪证而当场使用暴力或者以暴力相威胁的，依照抢劫罪定罪处罚。”甲犯盗窃罪，为抗拒抓捕而当场使用暴力，其行为已转化为抢劫。因此，A项错误。B项正确，根据《中华人民共和国刑法》第一百九十六条第三款规定：“盗窃信用卡并使用的，依照盗窃罪定罪处罚。”乙盗窃信用卡并使用，构成盗窃罪。C项错误，根据《中华人民共和国刑法》第二百七十条第二款规定：“将他人的遗忘物或者埋藏物非法占为己有，数额较大，拒不交出的，依照侵占罪处罚。”丙捡到价值50000的提包，经失主催要拒不归还的行为构成侵占罪。D项错误，根据《中华人民共和国刑法》第二百七十一条第一款规定：“公司、企业或者其他单位的人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的，处五年以下有期徒刑或者拘役；数额巨大的，处五年以上有期徒刑，可以并处没收财产。”丁作为私营公司销售主管，利用职务便利将产品据为己有的行为构成职务侵占罪。故正确答案为B。", "tag": "法律常识"},
{"id": "law-108", "q": "甲乙丙三人从丁处购买我国公民的个人信息，并组织人员利用网络电话实施诈骗行为，获利一百余万元，并由戊负责转账。下列说法错误的是：", "options": ["若甲乙丙三人在境外实施该电信网络诈骗行为，则不予追究刑事责任", "甲乙丙三人为组织者，三人对全部的诈骗行为承担责任", "丁明知甲乙丙三人实施电信网络诈骗犯罪，依然非法向其出售公民个人信息，丁为共犯", "戊明知款项为诈骗所得，仍帮助甲乙丙在不同银行账户间频繁划转，戊为共犯"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，根据《最高人民法院、最高人民检察院、公安部关于办理电信网络诈骗等刑事案件适用法律若干问题的意见》（以下简称《意见》）第二部分第（二）条第4款的规定，实施电信网络诈骗犯罪，达到相应数额标准，在境外实施电信网络诈骗的，酌情从重处罚。另外，根据《最高人民法院、最高人民检察院关于办理诈骗刑事案件具体应用法律若干问题的解释》第一条的规定，利用电信网络技术手段实施诈骗，诈骗公私财物价值三千元以上、三万元以上、五十万元以上的，应当分别认定为诈骗罪的“数额较大”、“数额巨大”和“数额特别巨大”。故A选项错误，应对甲乙丙三人的诈骗行为追究刑事责任。B项正确，根据《意见》第四部分第（二）条的规定，多人共同实施电信网络诈骗，犯罪嫌疑人、被告人应对其参与期间该诈骗团伙实施的全部诈骗行为承担责任。故甲乙丙三人应对全部的诈骗行为承担责任，B项正确。C项正确，根据《意见》第四部分第（三）条第2款的规定，明知他人实施电信网络诈骗犯罪，非法获取、出售、提供公民个人信息的，以共同犯罪论处，但法律和司法解释另有规定的除外。故丁应以共同犯罪论处，C项正确。D项正确，根据《意见》第四部分第（三）条第8款的规定，明知他人实施电信网络诈骗犯罪，帮助转移诈骗犯罪所得及其产生的收益、套现、取现的，以共同犯罪论处，但法律和司法解释另有规定的除外。故戊应以共同犯罪论处，D项正确。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-109", "q": "依据《刑法修正案（九）》的规定，下列说法错误的是：", "options": ["对伪造货币罪不再处以死刑", "对代替他人参加高考的行为应作出行政处罚"], "a": 1, "e": ".【B】B项错误：依据《刑法修正案（九）》第二十五条第一款“在法律规定的国家考试中，组织作弊的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。”和第四款“代替他人或者让他人代替自己参加第一款规定的考试的，处拘役或者管制，并处或者单处罚金。”可知，代替他人参加高考的行为属于犯罪行为，应处于刑事处罚而非行政处罚，当选；A项正确：《刑法修正案（九）》取消了包括伪造货币罪在内的9个适用死刑的罪名，对伪造货币罪不再处以死刑，排除；C项正确：依据《刑法修正案（九）》第三十一条：“聚众扰乱社会秩序，情节严重，致使工作、生产、营业和教学、科研、医疗无法进行，造成严重损失的，对首要分子，处三年以上七年以下有期徒刑；对其他积极参加的，处三年以下D项正确：《刑法修正案（九）》第三十二条规定：“编造虚假的险情、疫情、灾情、警情，在信息网络或者其他媒体上传播，或者明知是上述虚假信息，故意在信息网络或者其他媒体上传播，严重扰乱社会秩序的，处三年以下有期徒刑、序的行为属于犯罪行为，排除。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-110", "q": "下列情形中，行为人不负刑事责任的是：", "options": ["十四周岁的张某，贩卖冰毒0.2 克", "十五周岁的李某，因过失导致他人伤残", "二十周岁的周某，醉酒后殴打他人致人重伤", "三十五周岁的聋哑人宋某，入户盗窃现金5000 元"], "a": 1, "e": ".【B】《刑法》第十七条第一款第二款规定：“已满十六周岁的人犯罪，应当负刑事责任。已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任。”A项正确，十四岁的张某贩毒，属于《刑法》第十七条第二款中的八大行为之一，故张某应当负刑事责任。B项错误，十五岁的李某过失致人伤残，不符合《刑法》第十七条第二款中的故意犯罪，故李某不负刑事责任。C项正确，《刑法》第十八条第四款规定：“醉酒的人犯罪，应当负刑事责任。”在本选项中，周某已满十六周岁，且醉酒不是免责情形，故周某应当负刑事责任。D项正确，《刑法》第十九条规定：“又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。”在本选项中，宋某已满十六周岁，且聋哑人不是免责情形，故宋某应当负刑事责任。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-112", "q": "下列选项中，属于我国《刑法》规定的刑罚。", "options": ["从业禁止", "管制", "训诫", "罚款"], "a": 1, "e": ".【B】本题考查法律常识。根据《刑法》第三十三条规定：“【主刑种类】主刑的种类如下：（一）管制；（二）拘役；（三）有期徒刑；（四）无期徒刑；（五）死刑。”第三十四条规定：“【附加刑种类】附加刑的种类如下：（一）罚金；（二）剥夺政治权利；（三）没收财产。附加刑也可以独立适用。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-113", "q": "某县委办公室主任吴某，吩咐其下属孙某，利用举办会议的机会，通过虚开发票冒领会议经费44860 元。孙某自己留下9860 元，将其余的35000 元交给吴某，吴某据为己有。此事被监察部门发现并移交司法机关，吴某涉嫌的罪名是：", "options": ["贪污罪", "职务侵占罪", "受贿罪", "私分国有资产罪"], "a": 0, "e": ".【A】本题考查法律常识。A项正确，根据《刑法》第三百八十二条的规定，贪污罪是指国家工作人员和受国家机关、国有公司、企业、事业单位、人民团体委托管理、经营国有财产的人员，利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的行为。吴某身为国家工作人员，利用职务便利，虚开发票骗取国家财产的行为构成贪污罪。B项错误，根据《刑法》第二百七十一条的规定，职务侵占罪是指公司、企业或者其他单位的人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的行为。职务侵占罪的构成主体是公司企业或者其他单位的人员，而吴某的身份是国家工作人员，不符合职务侵占罪的构成要件。C项错误，根据《刑法》第三百八十五条的规定，受贿罪是指国家工作人员利用职务上的便利，索取他人财物，或者非法收受他人财物，为他人谋取利益的行为。吴某的行为表现不构成受贿罪。D项错误，根据《刑法》第三百九十六条的规定，私分国有资产罪是指国家机关、国有公司、企业、事业单位、人民团体，违反国家规定，以单位名义将国有资产集体私分给个人，数额较大的行为。吴某的行为表现不构成私分国有资产罪。故正确答案为A。", "tag": "法律常识"},
{"id": "law-114", "q": "根据我国《刑法》规定，下列行为属于“扒窃”的是：", "options": ["甲在超市内偷走柜台里价值3000 元的手机1 部", "乙翻窗进入被害人家里偷走抽屉内现金5000 元", "丙趁人不备偷走公园内自行车1 辆，价值2500 元", "丁在地铁上偷走被害人随身钱包1 个，内有现金500 元"], "a": 3, "e": ".【D】本题考查法律常识。《最高人民法院最高人民检察院关于办理盗窃刑事案件适用法律若干问题的解释》第三条第四款规定：“在公共场所或者公共交通工具上盗窃他人随身携带的财物的，应当认定为‘扒窃’。”A项错误，该项中甲某盗窃的是超市柜台里的手机，不属于“随身携带”财物，不是“扒窃”。B项错误，该项中乙某的行为属于“入户盗窃”，而不是“扒窃”。C项错误，该项中丙某盗窃的自行车不属于“随身携带”财物，不是“扒窃”。D项正确，该项中丁某在地铁（公共交通工具）盗窃被害人随身钱包，属于盗窃“随身携带”的财物，属于“扒窃”行为。故正确答案为D。", "tag": "法律常识"},
{"id": "law-116", "q": "根据《中华人民共和国刑法修正案（九）》，下列说法正确的是：", "options": ["组织恐怖活动培训的，处五年以上有期徒刑，并处罚金", "代替他人或者让他人代替自己参加考试，处三年以下有期徒刑，并处或单处罚金", "在道路上醉酒驾驶机动车的驾驶人，处拘役，并处罚金", "多次扰乱国家机关工作秩序，经行政处罚后仍不改正，造成严重后果的，处三年以上有期徒刑，并处罚金"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，根据《刑法修正案（九）》第七条第二款规定：“第一百二十条之二有下列情形之一的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产：(二)组织恐怖活动培训或者积极参加恐怖活动培训的；”B项错误，根据《刑法修正案（九）》第二十五条第四款规定：“代替他人或者让他人代替自己参加第一款规定的考试的（法律规定的国家考试），处拘役或者管制，并处或者单处罚金。”C项正确，根据《刑法修正案（九）》第八条第一款规定：“将刑法第一百三十三条之一修改为:‘在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金：(一)追逐竞驶，情节恶劣的；(二)醉酒驾驶机动车的；’”D项错误，根据《刑法修正案（九）》第三十一条第二款规定：“多次扰乱国家机关工作秩序，经行政处罚后仍不改正，造成严重后果的，处三年以下有期徒刑、拘役或者管制。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-117", "q": "下列行为构成盗窃罪的是：", "options": ["张某无意间将李某埋藏在屋外树下的十万元现金挖出，并占为己有，拒不交出", "胡某在任邮政局营业员期间，盗取储户的存折密码，然后冒充储户在取款单上签名，提取现金40 余万元", "张某在给客户维修网络过程中获知该客户的网游账号和密码，后张某和其朋友利用该账号和密码在网吧玩网游，共消", "赵某意欲窃走丁某的手提包，在其刚拿到手提包准备离开时被丁某发现，丁某当即抓住手提包，但因力气较小，最终"], "a": 2, "e": ".【C】本题主要考查法律常识。根据《刑法》第二百六十四条规定，盗窃罪是指以非法占有为目的，盗窃公私财物数额较大，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的行为。A项错误，根据《刑法》第二百七十条规定，侵占罪，是指将代为保管的他人财物非法占为己有，数额较大，拒不退还的，或者将他人的遗忘物或者埋藏物非法占为己有，数额较大，拒不交出的行为。该项中的张某将他人的埋藏物非法占为己有，拒不交出，构成侵占罪。B项错误，根据《刑法》第三百八十二条规定：“国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的，是贪污罪。”该项中的胡某作为国家工作人员，利用职务上的便利，私自取走（窃取）储户帐户中的钱款，构成贪污罪。此外，储户的存款同时系邮政局管理的财产，其工作人员取走储户的存款具有公共财产的属性。C项正确，该项中，张某与其朋友以非法占有为目的，非法消费（相当于窃取）客户网游账号里的钱，数额较大（3000余元），构成盗窃罪。D项错误，该项中的赵某盗窃丁某手提包时（尚未实际取得）被发现，丁某当即抓住手提包，赵某为了非法取得手提包，直接夺取，构成抢夺罪，而不是盗窃罪。故正确答案为C。", "tag": "法律常识"},
{"id": "law-118", "q": "刘某偷得同事一张信用卡和身份证，向女朋友黄某谎称路上捡到的，刘某、黄某根据身份证号码试出信用卡密码，持卡消费5000 元，关于刘某和黄某的行为，下列哪一说法正确？", "options": ["刘某和黄某均构成盗窃罪", "刘某和黄某均构成信用卡诈骗罪", "刘某构成盗窃罪，黄某构成信用卡诈骗罪", "刘某构成信用卡诈骗罪，黄某不构成犯罪"], "a": 2, "e": ".【C】本题主要考查法律常识。《刑法》第一百九十六条规定：“有下列情形之一，进行信用卡诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产：（一）使用伪造的信用卡，或者使用以虚假的身份证明骗领的信用卡的；（二）使用作废的信用卡的；（三）冒用他人信用卡的；（四）恶意透支的。前款所称恶意透支，是指持卡人以非法占有为目的，超过规定限额或者规定期限透支，并且经发卡银行催收后仍不归还的行为。盗窃信用卡并使用的，依照本法第二百六十四条的规定定罪处罚。”此外，《刑法》第二百六十四条是关于盗窃罪的规定。本题中，刘某是盗窃信用卡并使用，构成盗窃罪。黄某并不知信用卡是刘某偷的，但知晓使用的是他人的信用卡，属于上述法条中“冒用他人信用卡”的情形，其行为构成信用卡诈骗罪。因此，A、B、D三项不符合题意。故正确答案为C。", "tag": "法律常识"},
{"id": "law-119", "q": "关于因果关系的判断，下列说法正确的是：", "options": ["甲伤害乙后，警察赶到。在警察将乙送医途中，车辆出现故障，致乙长时间得不到救助而亡。甲的行为与乙的死亡具", "甲违规将行人丙撞成轻伤，丙昏倒在路中央，甲驾车逃窜。1 分钟后，超速驾驶的乙发现丙时已经来不及刹车，将丙", "甲向乙的茶水投毒，重病的乙喝了茶水后感觉更加难受，自杀身亡，甲的行为与乙的死亡没有因果关系", "甲以杀人故意向乙开枪，但由于不可预见的原因导致丙中弹身亡，甲的行为与丙的死亡没有因果关系"], "a": 2, "e": ".【C】本题考查法律常识，主要涉及刑法中的因果关系。刑法上的因果关系是指危害行为与危害结果之间的一种引起与被引起的关系。一般情况下，危害行为和危害结果之间的关系是非常明确的，比如用刀砍人致人重伤，砍人和重伤结果明显具有因果关系。但是，如果在行为人的行为实施以后，介入了第三者或者被害人的行为而导致结果发生（比如甲砍伤乙之后，乙接受治疗，由于医生过失，导致乙死亡，或者比如甲砍伤乙之后，乙痛苦难忍，采取了自杀行为），此时，还要进一步判断，要考虑行为人的行为（如拿刀砍人）导致结果发生的可能性的大小，介入情况（如被害人自杀行为）的异常性大小以及介入情况对结果发生作用的大小。A项错误，甲伤害乙，警察到达现场使甲的犯罪行为已经得到控制。由于介入了一异常情况，也就是由于车辆出现故障致使被害人得不到救助而死。故乙的死亡结果与甲的伤害行为不具有因果关系。B项错误，丙昏倒在路中央是由于甲违规将其撞伤而造成的，公路上车辆往来属于正常现象，倒在路中央的丙，被过路车辆碾压的可能性极高，此介入因素不具有异常性，因此，甲的行为与丙的死亡结果具有因果关系。C项正确，乙死亡的直接原因是乙的自杀行为，这个介入因素具有异常性，且自杀行为对最后危害结果发生作用很大，因此，甲的行为与乙的死亡没有因果关系。D项错误，因果关系是一种客观联系，不以人的意志为转移。行为人是否认识到自己的行为可能发生危害后果，不影响对因果关系的认定。虽然是由于不可预见的原因导致丙中枪，但是丙的中枪死亡结果是由于甲开枪射击的行为造成的，甲的行为与丙的死亡有因果关系。故正确答案为C。", "tag": "法律常识"},
{"id": "law-120", "q": "国家工作人员在国内公务活动或者对外交往中接受礼物，依照国家规定应当交公而不交公且数额较大的，应以（）定罪处罚。", "options": ["受贿罪", "贪污罪", "职务侵占罪", "徇私枉法罪"], "a": 1, "e": ".【B】本题考查法律常识，主要考查刑法分则中的具体罪名。根据《刑法》第三百九十四条规定，国家工作人员在国内公务活动或者对外交往中接受礼物，依照国家规定应当交公而不交公，数额较大的，依照贪污罪定罪处罚。因此，B项正确，A、C、D项错误。故正确答案为B。", "tag": "法律常识"},
{"id": "law-121", "q": "根据我国刑法，下列说法中正确的是", "options": ["外国公民甲，在其本国抢劫并杀害了一名中国籍游客，因该行为发生在外国，故不受我国法律约束", "外国公民乙，在中国境内因持有大量大麻被警方抓获，因其本国法律承认持有大麻行为合法，故其行为不受我国法律", "我国公民丙，在某外国工作期间杀害两名当地华裔，因该行为发生在外国，故不受我国法律约束", "我国国家工作人员丁，在外派某国工作期间泄露国家秘密，其行为受我国法律约束"], "a": 3, "e": ".【D】本题主要考查刑法的管辖原则。A项错误，《中华人民共和国刑法》第8条规定：外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，而按本法规定的最低刑为三年以上有期徒刑的，可以适用本法，但是按照犯罪地的法律不受处罚的除外。外国公民甲在其本国抢劫并杀害中国公民，即对我国公民犯罪，根据《中华人民共和国刑法》抢劫并杀人满足最低刑为三年以上有期徒刑，抢劫并杀人按照犯罪地的法律也应受处罚，依据保护管辖，故受我国法律约束。B项错误，《中华人民共和国刑法》第6条第1款规定：凡在中华人民共和国领域内犯罪的，除法律有特别规定的以外，都适用本法。外国公民乙在中国境内因持有大量大麻被警方抓获，依据属地管辖，受我国法律约束。C项错误，《中华人民共和国刑法》第7条第1款规定：中华人民共和国公民在中华人民共和国领域外犯本法规定之罪的，适用本法，但是按本法规定的最高刑为三年以下有期徒刑的，可以不予追究。我国公民丙在外国工作期间杀害两名当地华裔，犯有故意杀人罪，法定最低刑为三年以上有期徒刑，依据属人管辖，受我国法律约束。D项正确，《中华人民共和国刑法》第7条第2款规定：中华人民共和国国家工作人员和军人在中华人民共和国领域外犯本法规定之罪的，适用本法。国家工作人员丁，在外派某国工作期间泄露国家秘密，构成犯罪，依据属人管辖，应受我国法律约束。故正确答案为D。", "tag": "法律常识"},
{"id": "law-122", "q": "王某（14 周岁），蔡某（18 周岁），共同策划实施了一起入室抢劫，抢劫过程中，二人将反抗的户主杀害，下列说法正确的是：", "options": ["蔡某不能获得指定辩护", "王某和蔡某构成了共同犯罪", "抢劫罪和故意杀人罪数罪并罚", "王某是未成年人，不需要承担刑事责任"], "a": 1, "e": ".【B】本题考查法律常识。A项错误：依据《刑事诉讼法》第三十四条第三款规定：犯罪嫌疑人、被告人可能被判处无期徒刑、死刑，没有委托辩护人的，人民法院、人民检察院和公安机关应当通知法律援助机构指派律师为其提供辩护。而蔡某抢劫且致人死亡的行为，依据《刑法》第二百六十三条规定可能“处无期徒刑或死刑”，则蔡某是可以获得指定辩护的；B项正确：按照《刑法》第二十五条第一款规定：共同犯罪是指二人以上共同故意犯罪。共同犯罪成立要件必须包括：2人或2人以上；有共同故意；有共同行为。依此王某、蔡某行为构成共同犯罪；C项错误：抢劫罪的核心就是“压制反抗，强行取财”，本题中“将反抗的户主杀害”是为了实施抢劫而“压制反抗”，所以杀人仅仅是抢劫的手段而已，所以只定抢劫罪一罪。如果是抢劫后为了灭口把人杀了，才是数罪并罚；D项错误：按照《刑法》第十七条第二款规定：已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投毒罪的，应当负刑事责任。本题中，王某14周岁，实施了抢劫行为并致人死亡，应当承担刑事责任。故正确答案为B。", "tag": "法律常识"},
{"id": "law-123", "q": "根据我国现有法律规定，下列最有可能被判处有期徒刑（实刑）的是：", "options": ["19 岁的周某持刀抢劫他人现金10 元", "林某受人胁迫，首次偷窃就盗取了价值400 元的食物", "王某精神病发作，在神志不清时赤手空拳地打伤无辜的路人", "张某为朋友担保，向他人无息借款5 万元，在朋友无法偿还后也未还款"], "a": 0, "e": ".【A】A项：正确，首先19岁是负完全刑事责任；其次按照《刑法》第263条规定，抢劫罪至少判处三年以上有期徒刑。B项：错误，首先按照《刑法》第28条：对于被胁迫参加犯罪的，应当按照他的犯罪情节减轻处罚或者免除处罚。其次按照《刑法》第264条：盗窃公私财物，数额较大的，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。按照《最高人民法院最高人民检察院关于办理盗窃刑事案件适用法律若干问题的解释》第一条：盗窃公私财物价值一千元至三千元以上，认定为刑法第二百六十四条规定的“数额较大”。因林某受胁迫、且盗窃数额达不到较大数额标准，综合判定林某判处有期徒刑的概率较小。C项：错误，按照《刑法》第18条：精神病人在不能辨认或者不能控制自己行为的时候造成危害结果，经法定程序鉴定确认的，不负刑事责任。D项：错误，担保归民法调整，不属于刑法调整范围。故正确答案为A。", "tag": "法律常识"},
{"id": "law-124", "q": "关于我国《刑法》中的罚金，下列说法不正确的是：", "options": ["王某因犯危险驾驶罪被判处拘役一个月，可以并处罚金", "罚金数额的主要决定因素为犯罪情节", "对未成年人犯罪应当从轻或者减轻判处罚金", "因对部分犯罪行为可单处罚金，所以罚金为主刑的一种"], "a": 3, "e": ".【D】D项错误，《刑法》第三十四条规定：“附加刑的种类如下：(一)罚金；(二)剥夺政治权利；(三)没收财产。附加刑也可以独立适用。”故罚金属于附加刑而非主刑。A项正确，根据《刑法》第三十四条规定，附加刑既可以独立适用，也可以附加适用，故该项中判王某拘役一个月，并处罚金的做法是正确的。B项正确，《刑法》第五十二条规定：“判处罚金，应当根据犯罪情节决定罚金数额。”C项正确，《刑法》第十七条规定：“已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投毒罪的，应当负刑事责任。已满十四周岁不满十八周岁的人犯罪，应当从轻或者减轻处罚。”故对于未成年人犯罪应当从轻或减轻判处罚金的做法是正确的。本题为选非题，故正确答案为D。备注：确实不够妥当，根据《刑法》第一百三十三条之一规定，【危险驾驶罪】在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金。但是由于本题是单选题，选最优选项，D选项表述罚金是主刑，明显错误。罚金是附加刑的一种。因而本题最优选项是D选项。", "tag": "法律常识"},
{"id": "law-125", "q": "王某在公园与李某发生言语冲突，用小刀刺伤李某，强行抢走李某身上财物后逃跑。此时，李某紧追不舍，追出500 米后用砖头将王某砸成轻伤，并夺回了自己的财物。李某的行为应当属于（）。", "options": ["故意伤害", "正当防卫", "防卫过当", "紧急避险"], "a": 1, "e": ".【B】根据《刑法》第二十条第一款规定：“为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。”又因法律规定，在财产犯罪的场合，即使犯罪既遂，只要能够当场挽回财物，就视为不法侵害尚未结束，可以实行防卫。本题案例属于财产性犯罪，即使王某已经夺走财物并逃跑，只要现场能挽回，李某仍然可以进行防卫。故李某用砖头将王某砸成轻伤拿回财物属于正当防卫，不负刑事责任。B项正确。A项错误，正当防卫不属于犯罪，不负刑事责任，故不构成故意伤害。C项错误，防卫过当，是指防卫明显超过必要限度造成重大损害的，而本题中，仅仅造成王某轻伤，不属于防卫过当。D项错误，紧急避险，是指为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的紧急避险行为，造成损害的。紧急避险造成的是无辜第三方的损害，而本题中，李某针对的是不法侵害人王某本人，不属于紧急避险。故正确答案为B。", "tag": "法律常识"},
{"id": "law-126", "q": "在某地块招标过程中，张某游说作为国土局长的父亲利用职权影响，使其朋友王某中标，后来背着父亲收受王某100 万元。下列说法正确的是：", "options": ["张某的行为不构成犯罪", "张父的行为构成受贿罪", "张某与张父构成受贿罪的共同犯罪", "张某的行为构成利用影响力受贿罪"], "a": 3, "e": ".【D】受贿罪是指国家工作人员利用职务上的便利，索取他人财物，或者非法收受他人财物，为他人谋取利益的行为；利用影响力受贿罪是指国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，通过该国家工作人员职务上的行为，或者利用该国家工作人员职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物，数额较大或者有其他较重情节的行为。本题中，张父虽为国家工作人员，但是没有直接索取或非法收受中标者的财物，不构成受贿罪，B、C项说法错误。张某的行为明显构成犯罪，其犯罪构成要件符合利用影响力受贿罪的定义，A项错误，D项正确。故正确答案为D。", "tag": "法律常识"},
{"id": "law-127", "q": "根据《中华人民共和国刑法修正案（八）》，下列说法正确的是：", "options": ["社区矫正不适用于犯罪分子", "给予外国政府官员财物可能构成犯罪", "行贿人主动交代行贿行为的，应当减免处罚", "审判的时候已满七十五周岁的人不应判处死刑"], "a": 1, "e": ".【B】A项错误，《中华人民共和国刑法修正案（八）》明确规定，“对判处管制的犯罪分子，依法实行社区矫正”；B项正确，B项是《中华人民共和国刑法修正案（八）》新增加的内容，为谋取不正当商业利益，给予外国公职人员或者国际公共组织官员以财物的，可能被判刑；C项错误，“应当”一词表述有误，行贿人在被追诉前主动交代行贿行为的，可以减轻处罚或者免除处罚，这里是“可以”，不是“应当”；D项错误，表述过于绝对，审判的时候已满七十五周岁的人，不适用死刑，但以特别残忍手段致人死亡的除外。故正确答案为B。", "tag": "法律常识"},
{"id": "law-128", "q": "下列行为中构成犯罪的是：", "options": ["赵某，30 岁，醉酒驾车撞死路人", "刘某，13 岁，盗窃价值人民币50 万元的财物", "张某，30 岁，遇人抢劫奋起反击，将对方打成重伤", "王某，30 岁，为了躲避仇人追杀，抢了路人的摩托车逃跑"], "a": 0, "e": ".【A】A项，《刑法》第十八条规定：“醉酒的人犯罪，应当负刑事责任。”所以A项30岁的赵某醉酒驾车撞死路人，构成犯罪；B项，刘某13岁，不具有刑事责任能力，其盗窃行为不构成犯罪；C项，属于正当防卫；D项，属于紧急避险；C、D两项均属于合法行为。故正确答案为A。本题相关知识点：", "tag": "法律常识"},
{"id": "law-129", "q": "王某持匕首抢劫张某，在争斗中王某头部撞击墙角昏迷倒地，匕首掉在地上。张某见状，捡起匕首往王某心脏部位猛刺数下，导致王某死亡。对于张某用匕首刺死王某的行为，下列说法正确的是：", "options": ["属于正当防卫，不负刑事责任", "属于意外事件，不负刑事责任", "属于防卫过当，应当负刑事责任", "属于故意杀人，应当负刑事责任"], "a": 3, "e": "常【D】《刑法》第20条规定：“为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。”本案中王某晕倒，其不法侵害已经停止，故张某行为不属于正当防卫，更不属于防卫过当。故意杀人罪指故意非法地剥夺他人生命的行为，本案中张某对王某的死，主观上持故意心态，客观上实施了剥夺其生命的行为，构成故意杀人罪，应负刑事责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-130", "q": "甲欲杀死乙，在乙饭碗里投放毒药，不料朋友丙分食了乙的饭菜，甲为了杀死乙，没有阻止丙，结果导致乙和丙均中毒死亡。甲对丙死亡所持的心理态度是：", "options": ["过于自信的过失", "疏忽大意的过失", "间接故意", "直接故意"], "a": 2, "e": ".【C】本题考查法律常识。间接故意，行为人明知自己的行为可能发生危害社会的结果，并且放任这种结果发生的心理态度。放任，是指行为人对于危害结果的发生，虽然没有希望、积极地追求，但也没有阻止、反对，而是放任自流，听之任之，任凭、同意它的发生。显然对于丙的死亡，甲并不是持积极追求的心态，故属于间接故意。故正确答案为C。", "tag": "法律常识"},
{"id": "law-131", "q": "根据《中华人民共和国刑法》的规定，下列主体中不应该承担刑事责任的是：", "options": ["已满十八周岁的公民甲持刀抢劫", "已满七十五周岁的公民乙因为过失致人死亡", "十五周岁的公民丙多次盗窃公私财物，数额较大", "丁公司明知对方是黑社会性质组织犯罪所得，还协助其将资金汇往境外"], "a": 2, "e": ".【C】本题考查法律常识。《刑法》第十七条规定：“已满十六周岁的人犯罪，应当负刑事责任。已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投毒罪的，应当负刑事责任。已满十四周岁不满十八周岁的人犯罪，应当从轻或者减轻处罚。因不满十六周岁不予刑事处罚的，责令他的家长或者监护人加以管教；在必要的时候，也可以由政府收容教养。”《刑法》第十七条之一规定：“已满七十五周岁的人故意犯罪的，可以从轻或者减轻处罚；过失犯罪的，应当从轻或者减轻处罚。”A项正确，公民甲已满十八周岁，持刀抢劫应当承担抢劫罪的刑事责任。B项正确，已满七十五周岁的公民乙因为过失致人死亡，应当承担过失致人死亡罪的刑事责任，但当从轻或者减轻处罚。C项错误，多次盗窃公私财物属于盗窃罪，不在我国刑法第十七条规定的已满十四周岁不满十六周岁应当负刑事责任的八种罪行之中，故十五周岁的公民丙不应该承担刑事责任。D项正确，丁公司明知对方是黑社会性质组织犯罪所得，还协助其将资金汇往境外，应当承担洗钱罪的刑事责任。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-132", "q": "张某和杨某素有矛盾，某日，两人各纠集了一伙人，在一车站附近路段打架。过程中，张某的同伙彭某持钢管追打杨某的背部，并夺走杨某携带的水果刀，持刀划伤对方两人的手臂、大腿，致对方两人轻伤2 级。上述案例中，张某和杨某的行为构成（）。", "options": ["寻衅滋事罪", "聚众斗殴罪", "招摇撞骗罪", "故意杀人罪"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，《中华人民共和国刑法》第二百九十三条规定：“有下列寻衅滋事行为之一，破坏社会秩序的，处五年以下有期徒刑、拘役或者管制：（一）随意殴打他人，情节恶劣的；（二）追逐、拦截、辱骂他人，情节恶劣的；（三）强拿硬要或者任意损毁、占用公私财物，情节严重的；（四）在公共场所起哄闹事，造成公共场所秩序严重混乱的。”在本题中，张某、杨某等人并没有寻衅滋事的行为。B项正确，《中华人民共和国刑法》第二百九十二条规定：“聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制；有下列情形之一的，对首要分子和其他积极参加的，处三年以上十年以下有期徒刑：（一）多次聚众斗殴的；（二）聚众斗殴人数多，规模大，社会影响恶劣的；（三）在公共场所或者交通要道聚众斗殴，造成社会秩序严重混乱的；（四）持械聚众斗殴的。”在本题中，彭某持有钢管，杨某携带水果刀，双方持械聚众斗殴，符合聚众斗殴罪的第四项。C项错误，根据《中华人民共和国刑法》第二百七十九条规定：“冒充国家机关工作人员招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。冒充人民警察招摇撞骗的，依照前款的规定从重处罚。”在本题中，张某等人并没有冒充国家机关工作人员招摇撞骗，因而不构成招摇撞骗罪。D项错误，《中华人民共和国刑法》第二百三十二条规定：“故意杀人，是指故意非法剥夺他人生命的行为。”在本题中，张某、杨某等人并没有要剥夺他人生命的主观意思表示以及客观行为。故正确答案为B。", "tag": "法律常识"},
{"id": "law-133", "q": "甲乙二人决定一同毒死丙，于是趁丙不在，由乙在门外放风，甲潜入丙房间内往丙水杯中下毒。第二天，乙发现丙并未中毒身亡，于是持刀将其杀死。上述案件中，甲属于（）。", "options": ["犯罪中止", "犯罪预备", "犯罪未遂", "犯罪既遂"], "a": 2, "e": ".【C】本题主要考查法律常识。A项错误，《中华人民共和国刑法》第二十四条第一款规定：“在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。”本案中，甲未自动放弃犯罪或者自动有效地防止犯罪结果发生，不构成犯罪中止。B项错误，《中华人民共和国刑法》第二十二条第一款规定：“为了犯罪，准备工具、制造条件的，是犯罪预备。”本案中，甲乙两人已经着手实行杀人行为（下毒），不可能再构成犯罪预备。C项正确，《中华人民共和国刑法》第二十三条第一款规定：“已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂。”本案中，甲乙两人已经着手（下毒）实行犯罪，但丙并未中毒身亡（甲乙意志以外的原因），甲乙两人下毒这一行为，并未造成丙死亡的结果，构成故意杀人未遂。D项错误，本案中，甲乙下毒杀人这一行为并未导致丙死亡，不构成犯罪既遂，而第二天乙持刀将丙杀死，乙构成故意杀人既遂。故正确答案为C。", "tag": "法律常识"},
{"id": "law-134", "q": "《中华人民共和国刑法》规定，国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的，是：", "options": ["受贿罪", "贪污罪", "职务侵占罪", "滥用职权罪"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，根据《刑法》第三百八十五条规定，受贿罪是指国家工作人员利用职务上的便利，索取他人财物的，或者非法收受他人财物，为他人谋取利益。与题干描述不符。B项正确，根据《刑法》第三百八十二条规定，贪污罪是指国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物。与题干描述相符。C项错误，根据《刑法》二百七十一条规定，职务侵占罪是指公司、企业或者其他单位的人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的。与题干描述不符。D项错误，根据《刑法》第三百九十七条规定，滥用职权罪是指国家机关工作人员滥用职权，致使公共财产、国家和人民利益遭受重大损失的。与题干描述不符。故正确答案为B。", "tag": "法律常识"},
{"id": "law-135", "q": "剥夺政治权利是一种附加刑，是指剥夺犯罪分子参加国家管理和政治活动权利的刑罚方法。下列权利中不属于剥夺政治权利的内容的是：", "options": ["选举权和被选举权", "言论、出版、集会、结社、游行、示威自由的权利", "担任国家机关职务的权利和担任国有单位领导职务的权利", "担任公司、企业领导职务的权利​"], "a": 3, "e": ".【D】D项符合题意：根据《刑法》第五十四条：剥夺政治权利是剥夺下列权利：(一)选举权和被选举权；(二)言论、出版、集会、结社、游行、示威自由的权利；(三)担任国家机关职务的权利；(四)担任国有公司、企业、事业单位和人民团体领导职务的权利。该项中“公司、企业”未明确规定为国有公司、国有企业。A、B、C三项均属于剥夺政治权利范畴。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-136", "q": "“开车不喝酒，喝酒不开车”是现在道路交通常用的标语。为保障交通安全，我国《刑法》对“酒后驾车”的相关情形也做了规定。在不考虑驾驶人年龄、行为能力等前提下，下列情形与刑法罪名对应关系正确的是：", "options": ["在道路上，酒后驾驶机动车辆——危险驾驶罪", "在道路上，醉酒驾驶机动车辆——危险驾驶罪", "在道路上，酒后驾驶机动车辆——交通肇事罪", "在道路上，醉酒驾驶机动车辆——交通肇事罪"], "a": 1, "e": ".【B】本题主要考查法律常识——危险驾驶罪。根据《刑法》第133条之一第1款规定，在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金：(一)追逐竞驶，情节恶劣的；(二)醉酒驾驶机动车的；(三)从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶的；(四)违反危险化学品安全管理规定运输危险化学品，危及公共安全的。A项错误，“酒后”错误，应当是“醉酒”。B项正确，符合危险驾驶罪的构成要件。C项错误，交通肇事罪，是指违反道路交通管理法规，发生重大交通事故，致人重伤、死亡或者使公私财产遭受重大损失，依法被追究刑事责任的犯罪行为。酒后驾驶机动车，不一定就构成交通肇事罪。D项错误，醉酒驾驶机动车，不一定就构成交通肇事罪。故正确答案为B。", "tag": "法律常识"},
{"id": "law-137", "q": "关于犯罪构成认识正确的是：", "options": ["犯罪客体是指受害人", "十五周岁的人也可能负刑事责任", "单位不能构成犯罪主体", "犯罪的过失不构成犯罪的主观方面"], "a": 1, "e": ".【B】本题考查法律常识。犯罪构成是指依照我国刑法规定，决定某一具体行为的社会危害性及其程度，为该行为构成犯罪所必需的一切客观和主观要件的有机统一，是使行为人承担刑事责任的根据。任何一种犯罪的成立都必须具备四个方面的构成要件，即犯罪主体、犯罪主观方面、犯罪客体和犯罪客观方面。A项错误，犯罪客体是指我国刑法所保护而为犯罪行为所侵犯的社会关系。B项正确，《刑法》第十七条第一、二款规定：“已满十六周岁的人犯罪，应当负刑事责任。已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投毒罪的，应当负刑事责任。”C项错误，犯罪主体是指实施危害社会的行为，依法应当负刑事责任的自然人或单位，因此单位可构成犯罪主体。D项错误，犯罪主观方面是指犯罪主体对自己危害行为及其危害结果所持的心理态度，包括故意和过失。故正确答案为B。", "tag": "法律常识"},
{"id": "law-138", "q": "甲乘坐中国某航空公司航班由广州飞往伦敦，在飞机经过法国上空时与乙发生争吵，并失手将乙打成重伤，根据我国《刑法》，对于这起犯罪案件，拥有管辖权的是：", "options": ["中国", "法国", "英国", "联合国"], "a": 0, "e": ".【A】本题考查法律常识。《刑法》第六条规定：“凡在中华人民共和国领域内犯罪的，除法律有特别规定的以外，都适用本法。凡在中华人民共和国船舶或者航空器内犯罪的，也适用本法。犯罪的行为或者结果有一项发生在中华人民共和国领域内的，就认为是在中华人民共和国领域内犯罪。”本题中，甲是在中国的航空器内犯罪，适用我国法律。因此，BCD选项不符合。故正确答案为A。", "tag": "法律常识"},
{"id": "law-139", "q": "甲公司因拖欠乙公司贷款被乙公司诉至法院，乙公司胜诉后甲公司拒不执行，乙公司向法院申请强制执行。甲公司知晓后将公司财产陆续转移。下列说法不正确的是：", "options": ["甲公司的行为可能构成拒不执行判决、裁定罪", "乙公司可向司法机关控告，或者向人民法院提起自诉", "因被执行人为甲公司，所以只能追究甲公司的刑事责任", "人民法院可通过纳入失信名单、媒体公布等手段追究甲公司责任"], "a": 2, "e": ".【C】C项错误：《刑法》第三十一条规定：“单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。”故该项“只能追究甲公司的刑事责任”的说法错误。A项正确：《刑法》第三百一十三条规定：“【拒不执行判决、裁定罪】对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，处三年以下有期徒刑、拘役或者罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。”甲公司行为可能构成该罪。B项正确：《刑事诉讼法》第一百零八条第二款规定：“被害人对侵犯其人身、财产权利的犯罪事实或者犯罪嫌疑人，有权向公安机关、人民检察院或者人民法院报案或者控告。”第一百一十二条规定：“对于自诉案件，被害人有权向人民法院直接起诉。”故该项的说法正确。D项正确：《民事诉讼法》第二百五十五条规定：“被执行人不履行法律文书确定的义务的，人民法院可以对其采取或者通知有关单位协助采取限制出境，在征信系统记录、通过媒体公布不履行义务信息以及法律规定的其他措施。”故该项说法正确。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-140", "q": "危害后果是危害行为给刑法所保护的法益所造成的现实侵害事实与现实危险状态，下列关于危害后果说法错误的是（）。", "options": ["小李与人斗殴，将对方打成轻伤，小李事后自首，小李的行为没有造成危害后果", "某顾客携带水果刀进入火车站候车，安检时，水果刀被没收，该旅客的行为没有造成危害后果", "刘某见邻居的汽车很少使用，便私自偷出使用，使用期间勤于保养，汽车不但没有被损坏，而且性能更胜从前，其行", "某活禽市场老板故意不配合活禽卫生检疫检查，但未造成疫病传播，该老板的行为没有造成危害后果"], "a": 0, "e": ".【A】A项打成轻伤已经造成了危害后果，有现实的侵害事实，自首不能表示该情节不存在。B项没收的水果刀显然没有造成任何危害后果。C项虽然车的性能比以前更好，但是私自偷出使用邻居的车辆已经构成了危害后果。D项只是没有配合检查，而且题干表述没有造成疫情传播，更不能确定该老板的货就含有病源，故D也没有造成危害后果。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-141", "q": "果农赵某在柑橘成熟季节为防止柑橘被偷，在果园四周私拉电网。某晚，孙某欲偷柑橘不慎触电，经送医院抢救，不治身亡。赵某对这一损害结果的主观心理状态是：", "options": ["直接故意", "间接故意", "过于自信的过失", "疏忽大意的过失"], "a": 1, "e": ".【B】本题考查法律常识，主要考查犯罪的主观方面。A项错误，直接故意，是指行为人明知自己的行为会发生危害社会的结果，并且希望这种结果的发生。本题中，赵某主观目的是防止柑橘被偷而不是希望别人被伤到，因而其主观心态不是直接故意。B项正确，间接故意，是指行为人明知自己的行为可能发生危害社会的结果，并且放任这种结果发生的心理态度。所谓放任，是指行为人对于危害结果的发生，虽然没有希望、积极地追求，但也没有阻止、反对，而是放任自流，听之任之，任凭、同意它的发生。赵某明知可能会有人偷柑橘并被电伤，虽然其主观上对伤人结果的发生不是积极追求，但对结果的发生也并不反对，属于放任的、无所谓的态度，因而属于间接故意。C项错误，过于自信的过失，是指行为人已经预见自己的行为可能发生危害社会的结果，但轻信能够避免以致发生这种结果的心理态度。赵某对拉电网会电伤人这一结果的心理状态是放任，其知道会有人来偷柑橘并且可能会触电，因而不是轻信不会有人偷柑橘而触电。D项错误，疏忽大意的过失，行为人应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，以致发生了这种危害结果的心理态度。赵某明知私拉电网会导致他人伤亡而放任其发生，造成李某死亡的结果，属于间接故意。故正确答案为B。", "tag": "法律常识"},
{"id": "law-142", "q": "甲因绑架罪被判处有期徒刑十三年，入狱后，甲认真遵守监规，接受教育改造，确有悔改表现。根据我国刑法规定，对甲可以如何处理（）", "options": ["既可以假释也可以减刑", "可以减刑，但不能假释", "可以假释", "既不能减刑，也不能假释"], "a": 1, "e": ".【B】本题考查法律常识。主要涉及假释和减刑的相关内容。我国《刑法》第78条规定：“被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间，如果认真遵守监规，接受教育改造，确有悔改表现的，或者有立功表现的，可以减刑。”我国《刑法》第81条第2款规定：“对累犯以及因杀人、爆炸、抢劫、强奸、绑架等暴力性犯罪被判处10年以上有期徒刑、无期徒刑的犯罪分子，不得假释。”A项错误，根据我国《刑法》第81条第2款的规定，甲因绑架罪被判处有期徒刑十三年，不得给予假释。B项正确，根据我国《刑法》第78条和第81条第2款的规定，甲可以减刑但不能假释。C项错误，根据我国《刑法》第81条第2款的规定，不得给予假释。D项错误，我国《刑法》第78条的规定中，并未对犯罪分子因犯何罪而被判刑做出限制，甲符合该规定，可以减刑。故正确答案为B。", "tag": "法律常识"},
{"id": "law-143", "q": "魏某因曾被赵某当众羞辱，一直对赵某怀恨在心，时时想着报复赵某，一天，魏某在外喝酒后驾车回家，不料在路上撞死一行人，下车查看后发现此人正是赵某。那么，魏某的行为应当属于（）。", "options": ["故意杀人", "过失致人死亡", "交通肇事", "报复陷害"], "a": 2, "e": ".【C】赵某在此次事故中不存在故意杀人的行为，排除A项。最高人民法院《关于审理交通肇事刑事案件具体应用法律若干问题的解释》第八条规定：在实行公共交通管理的范围内发生重大交通事故的，依照交通肇事罪处理。在公共交通管理的范围外，驾驶机动车辆或者使用其他交通工具致人死亡或者致使公共财产或者他人财产遭受重大损失，构成犯罪的，分别依照刑法过失致人死亡罪定罪处罚，此题中并没有提出是在公共交通管理的范围外，所以排除B项；D选项虽然魏某曾经对赵某有怀恨之心，但是并没有付诸实施，此次事故主观上也并没有故意的想法，排除D项。交通肇事罪是指从事交通运输的人员，由于违反交通运输规章制度，发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的行为。题中魏某酒后驾车，撞死行人，属于交通肇事罪，对应C项。故正确答案为C。", "tag": "法律常识"},
{"id": "law-144", "q": "我国刑法给犯罪嫌疑人定罪的一项基本原则是“罪刑法定”。对法律没有规定的侵犯公共利益的行为，应该：", "options": ["不定罪", "依照习惯定罪", "依照法律定罪", "依照以往判例定罪"], "a": 0, "e": ".【A】A项正确，“罪刑法定”原则即法无明文规定不为罪，法无明文规定不处罚，所以对这种刑法没有规定的行为不处罚。B、C、D三项错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-145", "q": "张某是某服装公司的法人代表，与担任出纳职务的妹夫合谋将100 万元公司资金挪用到股市炒股，并将盈利的20 万元平分。张某的行为构成：", "options": ["挪用公款罪", "挪用资金罪", "职务侵占罪", "贪污罪"], "a": 1, "e": ".【B】根据我国《刑法》和有关司法解释规定，挪用资金罪是指公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过3个月未还的，或者虽未超过3个月，但数额较大、进行营利活动的，或者进行非法活动的行为。本题中张某属于普通主体，其行为符合挪用资金罪的构成要件。故正确答案为B。", "tag": "法律常识"},
{"id": "law-146", "q": "下列犯罪嫌疑人、被告人中，哪个人不适用取保候审？", "options": ["甲在逮捕后侦查羁押期限届满仍需继续查证", "有证据证明乙犯故意杀人罪，有可能被判十年以上有期徒刑", "丙涉嫌侮辱罪被起诉", "丁被逮捕后发现其怀孕3 个月"], "a": 1, "e": ".【B】刑事诉讼法第六十五条第一款明确规定：“人民法院、人民检察院和公安机关对有下列情形之一的犯罪嫌疑人、被告人可以取保候审：（一）可能判处管制、拘役或者独立适用附加刑的；（二）可能判处有期徒刑以上刑罚，采取取保候审不致发生社会危险性的；（三）患有严重疾病、生活不能自理、怀孕或者正在哺乳自己婴儿的妇女，采取取保候审不致发生社会危险性的；（四）羁押期限届满，案件尚未办结，需要采取取保候审的。”A项符合上述（四）表述，C项符合（一）、（二）表述，D项符合（三）表述。A、C、D三项正确。根据《最高人民法院<人民检察院刑事诉讼规则（试行）>》第八十四条规定，人民检察院对于严重危害社会治安的犯罪嫌疑人，以及其他犯罪性质恶劣、情节严重的犯罪嫌疑人不得取保候审，故B项错误。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-147", "q": "编造、故意传播虚假恐怖信息，严重扰乱社会秩序，具有下列哪一情形的，应当处五年以上有期徒刑：", "options": ["致使航班备降或返航", "造成直接经济损失二十万元以上的", "多次编造、故意传播虚假恐怖信息", "造成三人以上轻伤或者一人以上重伤"], "a": 3, "e": ".【D】有关规定，编造、故意传播虚假恐怖信息，严重扰乱社会秩序，具有下列情形之一的，应当认定为《刑法》第二百九十一条之一的“造成严重后果”，处五年以上有期徒刑：（一）造成三人以上轻伤或者一人以上重伤的；（二）造成直接经济损失五十万元以上的；（三）造成县级以上区域范围居民生活秩序严重混乱的；（四）妨碍国家重大活动进行的；（五）造成其他严重后果的。拓展：编造、故意传播虚假恐怖信息，严重扰乱社会秩序，具有下列情形之一的，应当依照《刑法》第二百九十一条之一的规定，在五年以下有期徒刑范围内酌情从重处罚：（一）致使航班备降或返航；或者致使列车、船舶等大型客运交通工具中断运行的；（二）多次编造、故意传播虚假恐怖信息的；（三）造成直接经济损失二十万元以上的；（四）造成乡镇、街道区域范围居民生活秩序严重混乱的；（五）具有其他酌情从重处罚情节的。故正确答案为D。", "tag": "法律常识"},
{"id": "law-148", "q": "下列选项中符合我国法律适用原则的是：", "options": ["一男子偷自行车被某村巡逻队员抓住后，将其挂牌游街示众", "某歌星酒后驾车被判拘役，并作罚款处理", "某区政府管委会给该区法院发“警告函”，即“判案不得一意孤行”", "劳动模范犯有贪污罪，合议庭认为该劳模有功于社会，决定从轻处罚"], "a": 1, "e": ".【B】B项正确：《刑法》第133条之一规定：“在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金：(一)追逐竞驶，情节恶劣的；(二)醉酒驾驶机动车的；(三)从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶的；(四)违反危险化学品安全管理规定运输危险化学品，危及公共安全的。机动车所有人、管理人对前款第三项、第四项行为负有直接责任的，依照前款的规定处罚。有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。”所以B项符合我国法律适用原则。（该选项出题人表述不严谨。严谨表述应该是并作罚金处理）A项错误：《中华人民共和国民法通则》第101条规定：“公民、法人享有名誉权，公民的人格尊严受法律保护，禁止用侮辱、诽谤等方式损害公民、法人的名誉。公民的名誉权若受到侵害，有权要求对方停止侵害，恢复名誉，消除影响，赔礼道歉。”A项中的游街示众损害了该男子的名誉权，并且巡逻员没有执法的权利，排除。C项错误：《宪法》第126条规定：“人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。”所以区政府管委会不得干涉法院判案，排除。D项错误：《刑法》第四条规定：“对任何人犯罪，在适用法律上一律平等。不允许任何人有超越法律的特权。”不能因为是劳动模范就减轻处罚，排除。故正确答案为B。", "tag": "法律常识"},
{"id": "law-149", "q": "王某明知某电器产品不符合保障人身安全的国家标准，仍然大量进货销售，销售金额达80 万元。某企业因使用这种电器造成短路，引起火灾，致3 人轻伤，部分厂房被烧毁。下列说法中正确的是：", "options": ["王某的行为已构成失火罪", "王某的行为已构成销售伪劣产品罪", "对王某应按照失火罪和销售伪劣产品罪中的一个重罪定罪处罚", "对王某应按照销售伪劣产品罪和过失伤人罪，数罪并罚"], "a": 1, "e": ".【B】A、C项错误，失火罪是指由于行为人的过失引起火灾，造成严重后果，危害公共安全的行为。本罪在客观方面表现为行为人实施引起火灾，造成严重后果的危害公共安全行为。王某并没有引起火灾的行为，不构成失火罪；B项正确，生产、销售伪劣产品罪，主观方面表现为故意，一般具有非法牟利的目的。行为人在销售领域内分两种情况：一是在销售产品中故意掺杂、掺假；二是明知是伪劣产品而售卖。王某明知某电器产品不符合保障人身安全的国家标准，仍然大量进货销售，构成销售伪劣产品罪；D项错误，刑法规定是失火、交通肇事致人死亡的，按失火罪、交通肇事罪的规定处罚。故正确答案为B。", "tag": "法律常识"},
{"id": "law-150", "q": "某珠宝店聘请的保安盗窃了该店价值300 多万元的首饰，经调查发现，该保安因故意犯罪被刑事处罚，而且所属的保安公司没有保安服务许可证，该保安公司的负责人最可能构成：", "options": ["非法经营罪", "盗窃罪", "破坏生产经营罪", "重大责任事故罪"], "a": 0, "e": ".【A】根据《刑法》第二百二十五条规定，违反国家规定，有下列非法经营行为之一，扰乱市场秩序，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上有期徒刑，并处违法所得一倍以上五倍以下罚金或者没收财产：(一)未经许可经营法律、行政法规规定的专营、专卖物品或者其他限制买卖的物品的；(二)买卖进出口许可证、进出口原产地证明以及其他法律、行政法规规定的经营许可证或者批准文件的；(三)未经国家有关主管部门批准非法经营证券、期货、保险业务的，或者非法从事资金支付结算业务的；(四)其他严重扰乱市场秩序的非法经营行为。本题中保安公司并没有取得相应资格的保安服务许可证，所以该保安公司的负责人的行为符合非法经营罪的犯罪构成。故正确答案为A。", "tag": "法律常识"},
{"id": "law-151", "q": "下列表达中，正确的是：", "options": ["不满18 周岁的人犯罪，不适用附加剥夺政治权利", "不满18 周岁的人犯罪，应当从轻或减轻处罚", "不满18 周岁的人犯罪，应当宣告缓刑", "不满18 周岁的人犯罪，不适用无期徒刑"], "a": 1, "e": ".【B】根据刑法第十七条第3款规定：已满十四周岁不满十八周岁的人犯罪，应当从轻或者减轻处罚。故正确答案为B。", "tag": "法律常识"},
{"id": "law-152", "q": "根据我国《刑法》规定，已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂。这里“未得逞”是指：", "options": ["犯罪行为没有实施完毕", "犯罪目的没有达到", "犯罪结果没有发生", "行为没有具备某种犯罪构成的全部要件"], "a": 3, "e": ".【D】犯罪未遂中的“未得逞”指的是行为没有具备犯罪构成的全部要件。故正确答案为D。", "tag": "法律常识"},
{"id": "law-153", "q": "甲开汽车到单位后，因疏忽忘记拔出车钥匙，被乙发现，乙发动甲的汽车刚要离开时，甲正好回来，将乙抓获。关于乙的行为，下列说法正确的是：", "options": ["构成抢夺罪未遂", "构成侵占罪未遂", "构成抢劫罪未遂", "构成盗窃罪未遂"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，抢夺罪，是指以非法占有为目的，直接夺取他人紧密占有的数额较大的公私财物，或者多次夺取他人紧密占有的公私财物的行为。抢夺罪的典型特征就是直接夺取财物，即在被害人当场可得知财物被抢的情况下实施抢夺行为，仅针对物采用暴力夺取。而本题中乙是趁甲离开之际，想用和平的手段窃取汽车，没有对物使用暴力，不构成抢夺罪。B项错误，侵占罪，是指以非法占有为目的，将代为他人保管的财物、他人的遗忘物、埋藏物占为己有，拒不退还的。侵占罪针对三种物，即保管物、遗忘物和埋藏物非法占为己有，拒不归还。本题中，乙窃取的汽车并非这三种物，因而不构成侵占罪。C项错误，抢劫罪，是指以非法占有为目的，对财物的所有人、保管人当场使用暴力、胁迫或其他方法，强行将公私财物抢走的行为。即通过压制反抗，达到强行取财的目的。本题中乙并未压制甲反抗，故不构成抢劫罪。D项正确，盗窃罪，是指以非法占有为目的，秘密窃取数额较大的公私财物或者多次秘密窃取公私财物的行为。乙趁甲离开之际，通过和平手段窃取汽车，构成盗窃罪。又因犯罪未遂，是指犯罪分子已经着手实施犯罪，由于意志以外的原因未得逞。本题中，乙已经发动汽车，已经在着手犯罪，由于被甲发现，属于意志以外的原因未得逞，故乙属于盗窃罪未遂。故本题答案为D。", "tag": "法律常识"},
{"id": "law-154", "q": "甲遭遇仇敌追杀，情急之下，从一住户的窗户跳入屋内躲避，不想将睡在窗边的一小孩踩成重伤。则甲的行为性质为：", "options": ["过失致人重伤罪", "防卫过当", "紧急避险", "意外事件"], "a": 3, "e": ".【D】本题考查防卫、紧急避险和意外事件的区别。A项错误，本题目中首先是“遭遇仇敌追杀”所以有了先决条件，可以排除过失伤人的A；B项错误，这里没有针对仇敌展开反抗，致使仇敌身体受伤或死亡，因此也不是防卫过当；C项错误，紧急避险是指为了本人或者他人的人身、财产和其他权利免受正发生的危险，不得已而采取的损害另一较小合法权益的行为。要求“甲”在选择逃入屋内时知道小孩的存在，但不得不在自己被害和损伤小孩肌体中选择，但本题中显然不是，题干中甲并不知晓小孩的存在；D项正确，意外事件是指行为人实施某一行为在客观上导致了损害的结果，但其既不是出于故意，也不存在主观上的过失，而是由于不能预见的原因引起的。故正确答案为D。本题为有争议题目，曾经考察过真题，没有意外事件这个选项，因而只能选紧急避险。但是本题中，有更好的选项意外事件，故选择最优选项，意外事件。", "tag": "法律常识"},
{"id": "law-155", "q": "我国公民甲乙二人乘坐中国客轮去美国，途经日本海域时，甲乙二人发生争吵，甲掏出水果刀，连续向乙猛刺五刀，遂将乙刺死，甲的行为：", "options": ["适用于中国法律", "可适用于中国法律，也可适用于日本法律", "适用于美国法律", "适用于日本法律"], "a": 0, "e": ".【A】本题考查刑法的属地和属人原则，本题中施害方和受害者都是中国公民，虽然在日本海域，但在当事双方都为中国人的情况下，这属于刑法中的属人原则，因此应该适用于中国法律。故正确答案为A。", "tag": "法律常识"},
{"id": "law-156", "q": "一艘行驶在日本海域的美国货船上，有甲、乙两个中国人，发生争执，甲将乙捅死，依据我国《刑法》，该案件适用于哪国法律：", "options": ["中国法律", "美国法律", "日本法律", "既适用中国法律也适用日本法律"], "a": 0, "e": ".【A】《刑法》第七条规定：“中华人民共和国公民在中华人民共和国领域外犯本法规定之罪的，适用本法，但是按本法规定的最高刑为三年以下有期徒刑的，可以不予追究。”甲将乙捅死，已构成故意杀人罪，故适用《刑法》。故正确答案为A。本题相关知识点：", "tag": "法律常识"},
{"id": "law-158", "q": "下列选项中，哪一行为构成正当防卫：", "options": ["甲到商场购物时将自己的汽车停在商场门口，买完东西出来时发现乙打碎了车窗玻璃，在偷车内的东西，于是上前将", "甲持枪闯进某单位财务室，逼着财务室工作人员乙打开保险柜，在甲让乙往口袋里装钱时，乙的同事进来趁甲不注意", "甲对乙心存怨恨，故意辱骂乙，乙气急要动手打甲，甲拿起准备好的棍子将乙手臂打伤。", "甲在大街上打电话，被乙抢走了手机，甲追赶乙未果。第二天甲在大街上发现了乙，于是偷偷在其背后将其打倒，抢"], "a": 1, "e": ".【B】《刑法》第20条规定，为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。正当防卫的构成条件如下：起因条件：不法侵害现实存在时间条件：不法侵害正在进行主观条件：具有防卫意识对象条件：针对侵害人防卫限度条件：没有明显超过必要限度A项错误，是甲的财产正在受到不法侵害，但防卫过程中已经将乙抓住，即可避免侵害继续，这时候将其打昏属于明显超过必要限度，排除；C项错误，乙气急要动手打甲，这是不法侵害并非正在进行，且甲的棍子是准备好，联系到前述心存怨恨表明这不是防卫意识，排除；D项错误，第二天表明不法侵害已经结束，不符合要求，排除。故正确答案为B。", "tag": "法律常识"},
{"id": "law-159", "q": "关于野生动物保护，下列说法符合法律规定的是：", "options": ["走私国家禁止进出口的珍贵动物，最高可判无期徒刑", "国家重点保护的野生动物分为一级、二级和三级保护野生动物", "除农村集体土地上的野生动物资源以外，其他野生动物资源属于国家所有", "持政府颁发的猎捕证猎捕野生动物给他人造成损失的，由政府和猎捕者共同承担赔偿"], "a": 0, "e": ".【A】A选项正确，根据《刑法》第一百五十一条规定，走私国家禁止出口的文物、黄金、白银和其他贵重金属或者国家禁止进出口的珍贵动物及其制品的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处没收财产；情节较轻的，处五年以下有期徒刑，并处罚金；B选项错误，《中华人民共和国野生动物保护法》第九条规定：国家对珍贵、濒危的野生动物实行重点保护。国家重点保护的野生动物分为一级保护野生动物和二级保护野生动物；C选项错误，《中华人民共和国野生动物保护法》第三条第1款规定：“野生动物资源属于国家所有。”第8条规定：“国家保护野生动物及其生存环境，禁止任何单位和个人非法猎捕或者破坏。”就是说，野生动物资源的所有权主体只有一个，即国家，其他任何组织和个人都不能成为野生动物资源的所有者；D选项错误，政府颁发的猎捕证只是政府确认了猎捕行为合法，但是因为猎捕行为给别人造成损失，当然要猎捕者承担责任的，因为损失的造成和猎人的猎捕行为有直接的因果关系，依据《中华人民共和国侵权责任法》猎捕者当然要承担法律责任。故正确答案为A。", "tag": "法律常识"},
{"id": "law-160", "q": "甲某贩运假烟，驾车路过一个检查站，检查人员朱某正要登车检查时，甲某突然发动汽车夺路而逃，朱某抓住车门不放。甲某为了摆脱朱某，在疾驶后突然急刹车，朱某被摔倒在地，头部着地死亡。甲某对朱某死亡的心理态度是：", "options": ["直接故意", "间接故意", "过于自信的过失", "疏忽大意的过失"], "a": 1, "e": ".【B】A项错误，直接故意，是指行为人明知自己的行为会发生危害社会的结果，并且希望这种结果的发生。在本题中，甲某是为了摆脱朱某的检查，主观上并非想导致朱某死亡，故其主观心态不是直接故意。B项正确，间接故意，是指行为人明知自己的行为可能发生危害社会的结果，并且放任这种结果发生的心理态度。甲某明知疾驶后刹车后可能会导致朱某受伤，还放任这种行为的发生。因此，甲某的主观心态属于间接故意。C项错误，过于自信的过失，是指行为人已经预见自己的行为可能发生危害社会的结果，但轻信能够避免以致发生这种结果的心理态度。D项错误，疏忽大意的过失，是指行为人应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，以致发生了这种危害结果的心理态度。故正确答案为B。", "tag": "法律常识"},
{"id": "law-161", "q": "下列行为中，构成使用假币罪的是：", "options": ["甲用总面额1 万元的假币参加赌博", "甲是某银行工作人员，利用职务上的便利，用假币换取真币", "甲在与乙签订经济合同时，为显示自己的经济实力，将总面额20 万元的假币冒充真币出示给乙看", "甲用总面额10 万元的假币换取乙1 万元的真币"], "a": 0, "e": ".【A】根据《关于惩治破坏金融秩序犯罪的规定》第4条：使用假币罪是指“明知是伪造的货币而使用，数额较大的……”。“使用”是指将假币取代真币在经济交易中运用，即用于流通，如正常的买卖活动，也有的用作赌资非法活动。A项正确，根据最高人民检察院、公安部《关于经济案件追诉标准的规定》第19条“明知是伪造的货币而持有、使用，总面额在四千元以上的，应予追诉”的规定，数额较大的起点为四千元；B项错误，银行工作人员并没有将假币用于流通，其行为构成以假币换取货币罪。金融机构工作人员购买假币、以假币换取货币罪，是指银行或者其他金融机构的工作人员购买伪造的货币，或者利用职务上的便利，以伪造的货币换取货币的行为；C项错误，甲的行为是为了取信于乙，其行为不构成使用假币罪，但不排除非法持有假币罪；D项错误，甲的行为不属于正常的买卖活动，其行为实质构成了出售假币罪。故正确答案为A。", "tag": "法律常识"},
{"id": "law-162", "q": "罪责刑相适应原则是我国《刑法》的基本原则之一，其含义是：", "options": ["刑罚的轻重应当与犯罪行为相适应", "刑罚的轻重应当与犯罪个人情况（主观恶性与人身危险性）相适应", "刑罚的轻重应当与犯罪客观危害相适应", "刑罚的轻重应当与犯罪分子所犯罪行和承担的刑事责任相适应"], "a": 3, "e": ".【D】罪责刑相适应原则，是指犯多大的罪，就应承担多大的刑事责任，法院也应判处其相应轻重的刑罚，做到重罪重罚，轻罪轻罚，罚当其罪，罪刑相称。即刑罚的轻重应当与犯罪分子所犯罪行和承担的刑事责任相适应。故正确答案为D。", "tag": "法律常识"},
{"id": "law-163", "q": "张某为了要男孩，将妻子刚生下的生重病的女婴扔进小河里淹死。张某应被定为犯有：", "options": ["过失杀人罪", "故意杀人罪", "遗弃罪", "虐待罪"], "a": 1, "e": ".【B】B项正确，《刑法》上的故意杀人，是指故意非法剥夺他人生命的行为。本题中，张某明知把婴儿扔进河里必然会导致婴儿死亡，还将该女婴扔入小河淹死，剥夺了该女婴的生命，符合故意杀人罪的犯罪构成要件。故正确答案为B。", "tag": "法律常识"},
{"id": "law-164", "q": "某日，刘某因给朋友过生日而喝醉了。在意识不清的情况下，刘某用刀捅死了前来劝阻其闹事的饭店服务员。下列关于刘某行为的判断正确的是：", "options": ["刘某是在意识不清情况下实施的杀人行为，因而不构成犯罪", "刘某应负刑事责任，但应从轻或减轻处罚", "刘某酗酒后杀人，应当从重处罚", "刘某的行为构成故意杀人罪"], "a": 3, "e": ".【D】我国《刑法》第十八条规定：“醉酒的人犯罪，应当负刑事责任。”酒后犯罪和正常人犯罪一样对待。醉酒的行为，并不是故意杀人罪的法定从重或者从轻情节。另外，犯罪行为的免除事由也不包括醉酒。故正确答案为D。", "tag": "法律常识"},
{"id": "law-165", "q": "下列不属于刑事处罚的是：", "options": ["罚金", "管制", "拘留", "拘役"], "a": 2, "e": ".【C】刑事处罚是指违反刑法，应当受到刑法的制裁。根据我国刑法的规定，刑事处罚包括主刑和附加刑两部分。主刑有：管制、拘役、有期徒刑、无期徒刑和死刑。附加刑有：罚金、剥夺政治权利和没收财产；此外还有适用于犯罪的外国人的驱逐出境。拘留不在此范围内。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-166", "q": "李军是某单位的会计，他为了盗窃单位保险柜里的现金而设法配制了保险柜的钥匙。后来李军在盗窃过程中因害怕被发现而将配制的钥匙丢弃，没有窃取现金。李军的行为属于：", "options": ["犯罪预备", "犯罪既遂", "犯罪中止", "犯罪未遂"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，犯罪预备，是指犯罪分子在犯罪的准备阶段，由于意志以外的原因未能着手。而本题中，李军在盗窃过程中，属于着手实行阶段。且因害怕被发现而将配制的钥匙丢弃，属于意志以内的原因，故不属于犯罪预备。B项错误，盗窃罪的既遂标准通说观念为财物已经脱离主人控制。本题中，李军尚且没有盗得财物，更不谈脱离主人控制，故盗窃罪没有既遂。C项正确，犯罪中止，是指犯罪分子在犯罪的实施过程中，自动放弃犯罪或者自动有效地防止犯罪结果的发生。本题中，李军属于在犯罪过程中自动放弃犯罪，属于犯罪中止。D项错误，犯罪未遂，是指犯罪分子已经着手实施犯罪，由于意志以外的原因未得逞。本题中，李军虽然属于着手实施阶段，但是最终没有盗得财物，是其主动放弃，而非意志以外的原因，不构成犯罪未遂。故正确答案为C。", "tag": "法律常识"},
{"id": "law-167", "q": "李某因诈骗罪被判处有期徒刑2 年，缓刑3 年，缓刑考验期满后，司法机关查获李某在缓刑考验期内，曾经伙同他人盗窃财物价值3 万元，对李某应当如何处理：", "options": ["不撤销缓刑，以累犯从重处罚", "撤销缓刑，以惯犯从重处罚", "不撤销缓刑，以盗窃罪从重处罚", "撤销缓刑，前后罪数罪并罚"], "a": 3, "e": ".【D】《中华人民共和国刑法》第七十七条规定：“被宣告缓刑的犯罪分子，在缓刑考验期限内犯新罪或者发现判决宣告以前还有其他罪没有判决的，应当撤销缓刑，对新犯的罪或者新发现的罪作出判决，把前罪和后罪所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚。”李某是在缓刑考验期内犯新罪，所以应该撤销缓刑，前后罪数罪并罚。故正确答案为D。本题相关知识点：《刑法》第六十九条规定：“判决宣告以前一人犯数罪的，除判处死刑和无期徒刑的以外，应当在总和刑期以下、数刑中最高刑期以上，酌情决定执行的刑期，但是管制最高不能超过三年，拘役最高不能超过一年，有期徒刑总和刑期不满三十五年的，最高不能超过二十年，总和刑期在三十五年以上的，最高不能超过二十五年。如果数罪中有判处附加刑的，附加刑仍须执行。”", "tag": "法律常识"},
{"id": "law-168", "q": "李某为公司仓库保管员。某日，两歹徒为逼李某交出仓库钥匙而持刀追打李某，李某被打成重伤，无奈之中李某抢了路边正在停车的黄某的摩托车逃走。李某抢走摩托车的行为：", "options": ["应负刑事责任。李某抢走他人车辆，属于抢劫行为，侵犯他人利益", "应负刑事责任。李某抢走他人车辆，属于盗窃行为，侵犯他人利益", "不应负刑事责任。李某抢走摩托车属于正当防卫，保护了公司和个人的合法权益", "不应负刑事责任。李某抢走摩托车属于紧急避险，损害了他人合法权益但保全了更大的合法权益"], "a": 3, "e": ".【D】本题是考查刑法的题。根据《刑法》第二十一条，为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的紧急避险行为，造成损害的，不负刑事责任。本题中李某的职务仅是仓库保管员，没有与歹徒搏斗的义务，为了保全公司的公共利益和个人人身安全，抢走摩托车逃走的行为完全符合紧急避险的构成要件。故正确答案为D。", "tag": "法律常识"},
{"id": "law-169", "q": "下列关于死刑的说法中，错误的是：", "options": ["死刑只适用于罪行极其严重的犯罪分子", "犯罪时不满18 周岁的人和审判时怀孕的妇女不适用死刑", "判决死刑立即执行的，由最高人民法院和最高人民法院授权的部分高级人民法院核准", "判处死刑缓期执行的，在死刑缓期执行期间，如果没有故意犯罪，两年期满后减为无期徒刑"], "a": 2, "e": ".【C】A项正确，死刑是剥夺犯罪分子生命的刑罚方法，这是最严厉的一种刑罚方法，死刑只适用于罪行极其严重的犯罪分子；B项正确，犯罪的时候不满18周岁的人和审判的时候怀孕的妇女，不适用死刑（包括不适用死缓）；C项错误，死刑有两种执行制度，一种是判处死刑立即执行，另一种是判处死刑同时宣告缓期2年执行（简称死缓）。死刑立即执行除由最高人民法院直接判决的外，依法都应当报最高人民法院核准，对于被判死刑缓期执行的各高级人民法院有权直接核准，无需上报；D项正确，《中华人民共和国刑法》规定：“判处死刑缓期执行的，在死刑缓期执行期间，如果没有故意犯罪，二年期满以后，减为无期徒刑”。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-170", "q": "李某因犯杀人（未遂）罪、抢劫罪、盗窃罪而分别被判处10 年、8 年、5 年有期徒刑，对其最后量刑应为多少年：", "options": ["10 年", "23 年", "10-23 年", "10-20 年"], "a": 3, "e": ".【D】我国《刑法》第六十九条规定：“判决宣告以前一人犯数罪的，除判处死刑和无期徒刑的以外，应当在总和刑期以下、数刑中最高刑期以上，酌情决定执行的刑期，但是管制最高不能超过三年，拘役最高不能超过一年，有期徒刑总和刑期不满三十五年的，最高不能超过二十年，总和刑期在三十五年以上的，最高不能超过二十五年。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-171", "q": "根据我国《刑法》的相关规定，下列罪犯不得假释的是：", "options": ["甲犯强奸罪被判处有期徒刑11 年", "乙犯贪污罪被判处有期徒刑13 年", "丙犯受贿罪被判处无期徒刑", "丁犯盗窃罪被判处有期徒刑8 年"], "a": 0, "e": ".【A】《刑法》第八十一条第二款规定：“对累犯以及因杀人、爆炸、抢劫、强奸、绑架等暴力性犯罪被判处十年以上有期徒刑、无期徒刑的犯罪分子，不得假释。”甲犯强奸罪，被判处有期徒刑11年，不符合假释条件。本题为选非题，故正确答案为A。本题相关知识点：关于“假释”，《刑法》第八十三条规定，“有期徒刑的假释考验期限，为没有执行完毕的刑期；无期徒刑的假释考验期限为十年。假释考验期限，从假释之日起计算”。", "tag": "法律常识"},
{"id": "law-172", "q": "甲因犯盗窃罪被公安机关逮捕，在审查期间，甲又主动交代曾实施抢劫犯罪。甲交代出抢劫案件的行为属于：", "options": ["自首", "坦白", "立功", "悔改表现"], "a": 0, "e": ".【A】本题考查刑法。自首分为一般自首和特别自首两种。特别自首是指被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪刑的行为。本题中，甲抢劫的行为是公安机关尚未掌握的，因此单就抢劫案件来说，属于特别自首。故正确答案为A。", "tag": "法律常识"},
{"id": "law-173", "q": "在我国刑罚执行中，对判处哪种刑法采取吸收原则：", "options": ["有期徒刑", "无期徒刑", "拘役", "管制"], "a": 1, "e": ".【B】吸收原则，是指对一人所犯数罪采用重罪吸收轻罪或者重罪刑吸收轻罪刑的合并处罚规则。换言之，它是由一人所犯数罪中法定刑最重的罪吸收其它较轻的罪，或者由最重宣告刑吸收其它较轻的宣告刑，仅以最重罪的宣告刑或者已宣告的最重刑罚作为执行刑罚的合并处罚规则。这种原则对死刑、无期徒刑比较适宜。故正确答案为B。", "tag": "法律常识"},
{"id": "law-174", "q": "被判处无期徒刑的罪犯，经过一次或几次减刑以后，实际执行的刑期不能少于：", "options": ["原判刑期的二分之一", "13 年", "15 年", "15 年以上20 年以下"], "a": 1, "e": ".【B】《刑法修正案（八）》将原七十八条第二款修改为：“减刑以后实际执行的刑期不能少于下列期限：（一）判处管制、拘役、有期徒刑的，不能少于原判刑期的二分之一；（二）判处无期徒刑的，不能少于十三年。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-175", "q": "自动放弃犯罪行为，从而避免了犯罪结果的发生，这种行为属于：", "options": ["犯罪预备", "犯罪表示", "犯罪未遂", "犯罪中止"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，犯罪预备，是指在犯罪分子在犯罪的准备阶段，由于意志以外的原因未能着手。B项错误，犯罪表示，又称为犯意表示，一般是指以口头、书面或者其他方法，将真实的犯罪意图表现于外部。比如，张三告诉李四，他想杀王五，属于犯意表示。C项错误，犯罪未遂，是指犯罪分子已经着手实施犯罪，由于意志以外的原因未得逞。D项正确，犯罪中止，是指犯罪分子在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生。故正确答案为D。", "tag": "法律常识"},
{"id": "law-176", "q": "李某属国有企业的财务人员，私自动用了一笔数额较大的公款去炒股，一个月后被领导发现，其行为属于：", "options": ["贪污", "挪用公款", "滥用职权", "职务侵占罪"], "a": 1, "e": ".【B】挪用公款罪是指国家工作人员利用职务上的便利，挪用公款归个人使用，进行非法活动，或者挪用公款数额较大，进行盈利活动，或者挪用公款数额较大，超过三个月未还的行为。根据《中华人民共和国刑法》第九十三条规定：“本法所称国家工作人员，是指国家机关中从事公务的人员。国有公司、企业、事业单位、人民团体中从事公务的人员和国家机关、国有公司、企业、事业单位委派到非国有公司、企业、事业单位、社会团体从事公务的人员，以及其他依照法律从事公务的人员，以国家工作人员论。”根据该条规定，李某（国企财务）是国家工作人员，所以属于挪用公款罪。故正确答案为B。", "tag": "法律常识"},
{"id": "law-177", "q": "关于正当防卫与紧急避险，下列说法正确的是：", "options": ["正当防卫明显超过必要限度造成重大损害的，应当以防卫过当罪定罪，但是应当酌情减轻或者免除处罚", "紧急避险用于解决紧迫情况下合法利益之间的冲突", "防卫过当的场合，其罪过形式通常是直接故意", "对于事后防卫的，通常按照防卫过当处理"], "a": 1, "e": ".【B】本题考查法律常识。", "tag": "法律常识"},
{"id": "law-178", "q": "2018 年10 月26 日，全国人大常委会审议通过了《中华人民共和国刑事诉讼法修正案》。下列刑事诉讼制度中，不属于该修正案新增内容的是（）。", "options": ["认罪认罚制度", "缺席审判制度", "速裁程序制度", "违法所得没收制度"], "a": 3, "e": ".【D】本题考查法律常识。A项正确，2018年新修订的《刑事诉讼法》在第一编第一章中明确规定了刑事案件认罪认罚可以依法从宽处理的原则，如增加一条作为第十五条：“犯罪嫌疑人、被告人自愿如实供述自己的罪行，承认指控的犯罪事实，愿意接受处罚的，可以依法从宽处理。”B项正确，2018年新修订的《刑事诉讼法》在第五编特别程序中增设缺席审判程序一章，涉及的法条是第291条至第", "tag": "法律常识"},
{"id": "law-179", "q": "下列情形中，用人单位不需要支付经济补偿金的是：", "options": ["甲公司提出并与张某协商一致解除劳动合同", "乙公司未依法为李某提供劳动保护，李某提出解除劳动合同", "丙公司生产经营发生严重困难而解除与孙某的劳动合同", "丁公司于劳动合同期满后提高待遇要求续签，赵某拒绝"], "a": 3, "e": ".【D】本题考查法律常识。关于经济补偿的问题，《劳动合同法》第四十六条作出了规定：“有下列情形之一的，用人单位应当向劳动者支付经济补偿：（一）劳动者依照本法第三十八条规定解除劳动合同的；（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；（三）用人单位依照本法第四十条规定解除劳动合同的；（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的；（六）依照本法第四十四条第四项、第五项规定终止劳动合同的；（七）法律、行政法规规定的其他情形。”《劳动合同法》第四十四条规定：“有下列情形之一的，劳动合同终止：（一）劳动合同期满的；（四）用人单位被依法宣告破产的；（五）用人单位被吊销营业执照、责令关闭、撤销或者用人单位决定提前解散的；”A项正确，《劳动合同法》第三十六条规定：“用人单位与劳动者协商一致，可以解除劳动合同。”因此，甲公司应当向张某支付经济补偿金。B项正确，《劳动合同法》第三十八条规定：“用人单位有下列情形之一的，劳动者可以解除劳动合同：（一）未按照劳动合同约定提供劳动保护或者劳动条件的；”因此，乙公司应当向李某支付经济补偿金。C项正确，《劳动合同法》第四十一条第一款规定：“有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员：（二）生产经营发生严重困难的；”因此，丙公司应当向孙某支付经济补偿金。D项错误，根据《劳动合同法》第四十六条第（五）项的规定，劳动合同期满，用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的，用人单位不支付经济补偿金。因此，丁公司不需要向赵某支付经济补偿金。本题为选非题，故正确答案为D。", "tag": "法律常识"}
);
